appHeadingStyle.textContent="/* One type scale for the app. Small status labels remain metadata, not headings. */\n:root{--cb-heading-page:28px;--cb-heading-section:20px;--cb-heading-subsection:17px;--cb-heading-detail:16px}\n:is(#app,dialog,[role=\"dialog\"]) :is(h1,h2,h3,h4,h5,h6,[role=\"heading\"]){font-weight:700!important;line-height:1.3!important;letter-spacing:normal!important;overflow-wrap:anywhere}\n:is(#app,dialog,[role=\"dialog\"]) h1{font-size:var(--cb-heading-page)!important}\n:is(#app,dialog,[role=\"dialog\"]) h2{font-size:var(--cb-heading-section)!important}\n:is(#app,dialog,[role=\"dialog\"]) h3{font-size:var(--cb-heading-subsection)!important}\n:is(#app,dialog,[role=\"dialog\"]) :is(h4,h5,h6){font-size:var(--cb-heading-detail)!important}\n:is(#app,dialog,[role=\"dialog\"]) [aria-level=\"1\"]{font-size:var(--cb-heading-page)!important}\n:is(#app,dialog,[role=\"dialog\"]) [aria-level=\"2\"]{font-size:var(--cb-heading-section)!important}\n:is(#app,dialog,[role=\"dialog\"]) [aria-level=\"3\"]{font-size:var(--cb-heading-subsection)!important}\n:is(#app,dialog,[role=\"dialog\"]) :is([aria-level=\"4\"],[aria-level=\"5\"],[aria-level=\"6\"]){font-size:var(--cb-heading-detail)!important}\n/* Expandable sections and navigation tiles use the same shared scale. */\n#app .plan-section-tile>summary>strong{font-size:var(--cb-heading-section)!important;line-height:1.3}\n#app :is(.train-format-accordion summary strong,.training-tool-tile>strong,.player-home-tile>strong,.training-disclosure>summary,.innings-prep-section>summary,.innings-reflection-options>summary){font-size:var(--cb-heading-subsection)!important;line-height:1.3}\n#app .call-award-title{font-size:var(--cb-heading-detail)!important;line-height:1.3}\n\n/* Headings focused after navigation are landmarks, not input fields. */\n#app :is(h1,h2,h3,h4,h5,h6)[tabindex=\"-1\"]:focus{outline:none}\n";
document.head.append(appHeadingStyle);
// END SHARED HEADING STYLES V89

function upgradeLegacyHowWeBatWording(draft){
  if(!draft || typeof draft!=='object')return draft;
  const formats=draft.formats||{};
  for(const f of Object.values(formats)){
    if(!f || !Array.isArray(f.banners))continue;
    for(const b of f.banners){
      // Only upgrade the platform's old default. Genuine club-written wording is untouched.
      if(b?.key==='use_phase' && b.title==='USE THE PHASE')b.title='KNOW WHEN TO GO';
    }
  }
  if(typeof draft.closing_strapline==='string' && draft.closing_strapline.includes('USE THE PHASE')){
    draft.closing_strapline=draft.closing_strapline.replaceAll('USE THE PHASE','KNOW WHEN TO GO');
  }
  return draft;
}

