function matchDraftKey(kind,id){const scope=matchDraftScope();return scope?matchDraftRecovery.prefix+encodeURIComponent(scope.user)+':'+encodeURIComponent(scope.club)+':'+kind+':'+encodeURIComponent(id):null;}
function matchDraftStorageKeys(){const keys=Object.keys(localStorage).filter(k=>k.startsWith(matchDraftRecovery.prefix)&&!k.endsWith(':index'));try{for(const key of JSON.parse(localStorage.getItem(matchDraftRecovery.prefix+':index')||'[]'))if(!keys.includes(key))keys.push(key);}catch{}return keys;}
function matchDraftClone(value){return JSON.parse(JSON.stringify(value));}
function matchDraftEntries(){const scope=matchDraftScope(),out=[];if(!scope)return out;try{for(const key of matchDraftStorageKeys()){let value;try{value=JSON.parse(localStorage.getItem(key));}catch{localStorage.removeItem(key);continue;}if(value?.version!==129||!value.command&&value.updated<Date.now()-matchDraftRecovery.ttl){localStorage.removeItem(key);continue;}if(value.user===scope.user&&value.club===scope.club)out.push({key,...value});}}catch{}return out;}
