function matchDraftDiscardForm(form){const ctx=matchDraftRecovery.forms.get(form);if(ctx&&!matchDraftRead(ctx.key)?.command){matchDraftRemove(ctx);ctx.adopted=false;}}
function matchDraftDiscardTeam(s){const ctx=matchDraftTeamContext(s);if(ctx&&!matchDraftRead(ctx.key)?.command)matchDraftRemove(ctx);}
function matchDraftRemove(ctx){try{localStorage.removeItem(typeof ctx==='string'?ctx:ctx.key);}catch{}}
