function matchDraftFields(form){return [...form.querySelectorAll('input,textarea,select')].filter(x=>!x.closest('[data-match-draft-banner]')&&!['password','file'].includes(x.type)).map((x,index)=>({index,id:x.id||'',name:x.name||'',type:x.type||x.tagName,value:x.value,checked:!!x.checked}));}
