function matchDraftLock(ctx){if(!ctx.form||ctx.unlock)return;const controls=[...ctx.form.querySelectorAll('input,textarea,select,button')].filter(x=>!x.closest('[data-match-draft-banner]')),prior=controls.map(x=>[x,x.disabled]);for(const [x] of prior)x.disabled=true;ctx.unlock=()=>{for(const [x,disabled]of prior)if(x.isConnected)x.disabled=disabled;ctx.unlock=null;if(typeof syncPlayerFixtureSave==='function')syncPlayerFixtureSave(ctx.form);};ctx.blocked=true;}
function matchDraftShowForm(ctx){const entry=matchDraftRead(ctx.key);if(!entry||ctx.adopted)return;ctx.form.querySelector('[data-match-draft-banner]')?.remove();const box=document.createElement('section');box.className='match-draft-recovery';box.dataset.matchDraftBanner='form';const changed=entry.revision!==ctx.revision;box.innerHTML='<strong>Unfinished '+esc(ctx.label)+'</strong><p data-draft-message></p><div class="btnrow"><button type="button" class="btn" data-draft-restore></button><button type="button" class="btn ghost" data-draft-discard>Discard draft</button></div>';ctx.form.prepend(box);box.querySelector('[data-draft-message]').textContent=entry.command?'A previous save was not confirmed. Check that same save before making more changes.':changed?'The saved record changed while this draft was closed. Read your draft below alongside the current record; it will not overwrite the newer version.':'Your unsaved work is available on this device.';const restore=box.querySelector('[data-draft-restore]');restore.textContent=entry.command?'Check previous save':'Restore draft';restore.disabled=changed&&!entry.command;restore.onclick=async()=>{if(entry.command)return matchDraftRecoverCommand(ctx,entry,box);restore.disabled=true;try{await matchDraftPreflight(ctx,entry);if(ctx.form?.isConnected){ctx.unlock?.();ctx.blocked=false;matchDraftRestoreFields(ctx,entry);}}catch(error){matchDraftLock(ctx);box.querySelector('[data-draft-message]').textContent=error.message||'Could not check current access.';restore.disabled=false;}};box.querySelector('[data-draft-discard]').disabled=!!entry.command;box.querySelector('[data-draft-discard]').onclick=()=>{matchDraftRemove(ctx);ctx.adopted=true;ctx.blocked=false;ctx.unlock?.();box.remove();};if(changed&&!entry.command){const details=document.createElement('details');details.innerHTML='<summary>Read my draft</summary>';const text=document.createElement('pre');text.style.whiteSpace='pre-wrap';text.textContent=(entry.snapshot?.fields||[]).filter(f=>f.value&&!['radio','checkbox','hidden','select-one'].includes(f.type)).map(f=>f.value).join('\n\n');details.append(text);box.append(details);}if(entry.command||!changed)matchDraftLock(ctx);}
async function matchDraftPreflight(ctx,entry){const scope=matchDraftScope();if(scope?.user!==ctx.user||scope?.club!==ctx.club)throw Error('Sign in to the same account and club to recover this draft.');let response;if(ctx.kind==='observation'){response=await supabase.rpc('get_coach_observation_context',{p_player_id:ctx.route.playerId});if(response.error)throw response.error;response=await supabase.rpc('get_individual_match_fixtures',{p_club_id:ctx.club,p_player_id:ctx.route.playerId,p_match_id:ctx.route.matchId||null});}else if(ctx.kind==='team')response=await supabase.rpc('get_team_review_roster',{p_club_id:ctx.club});else response=await supabase.rpc('get_my_innings',{p_club_id:ctx.club});if(response.error)throw response.error;if(matchDraftScope()?.user!==ctx.user||matchDraftScope()?.club!==ctx.club)throw Error('The account changed. Reopen the draft from the correct account.');return response.data;}
