const matchDraftRpcs=new Set(['save_coach_observation','save_fixture_match_observation','save_individual_fixture_observation','save_my_match_preparation','save_my_innings','save_my_fixture_preparation','save_my_fixture_innings','save_team_match_review','save_match_review_players']);
async function matchDraftRpc(form,name,args,options={}){const ctx=options.team?matchDraftTeamContext(options.team):matchDraftRecovery.forms.get(form);if(!ctx||!matchDraftRpcs.has(name))return supabase.rpc(name,args);if(!args?.p_request_id)throw Error('A recovery-safe save request is required.');if(ctx.blocked)throw Error('Check the previous save before making another change.');ctx.adopted=true;const snapshot=form?matchDraftSnapshot(form):matchDraftTeamSnapshot(options.team);matchDraftWrite(ctx,{snapshot,command:{name,args:matchDraftClone(args)}});try{const result=await supabase.rpc(name,args);if(result.error&&matchDraftDefinite(result.error)){matchDraftWrite(ctx,{command:null});}return result;}catch(error){if(matchDraftDefinite(error))matchDraftWrite(ctx,{command:null});throw error;}}
