async function restoreDeviceSignIn(){
  const {error:authLinkError}=await supabase.auth.initialize();
  const {data,error}=await supabase.auth.getSession();
  // A failed connection is not a signed-out account. Keep the saved session and
  // let the existing startup retry reconnect instead of asking for a password.
  if(error)throw error;
  if(!data?.session&&isAuthRetryableFetchError(authLinkError))throw authLinkError;
  return {session:data?.session||null,authLinkError};
}

async function boot(){
  const moved=legacyAppRedirect(location.href);if(moved){location.replace(moved);return;}
  void initialisePhoneApp();
  document.title='Mirelion';
  const {session:s,authLinkError}=await restoreDeviceSignIn();
  session=s;
  passwordFlow.initialise(session,authLinkError);
  if(passwordFlow.isPasswordEntry)history.replaceState(history.state,'',cleanPasswordUrl(location.href));
  matchDraftAuthChanged(null,s?.user?.id||null);matchDraftStart();
  supabase.auth.onAuthStateChange((event,s2)=>{
    const previousUserId=session?.user?.id||null;
    const nextUserId=s2?.user?.id||null;
    matchDraftAuthChanged(previousUserId,nextUserId);
    session=s2;
    passwordFlow.authChanged(session);
    if(previousUserId!==nextUserId){mirelionAssist.reset();clubMessageState=null;clubMessageUnread=0;if(previousUserId)void phoneWorkerMessage('CB_SIGN_OUT');}

    // Supabase can emit SIGNED_IN again when an already-signed-in browser tab regains focus.
    // Rebuilding the SPA for that same-user event destroys the user's scroll position. Only a
    // genuine identity/session change should route the app again.
    const meaningfulAuthChange=
      previousUserId!==nextUserId ||
      ['SIGNED_OUT','USER_UPDATED'].includes(event);
    if(meaningfulAuthChange&&!authActionInFlight)setTimeout(()=>routeAuth(),0);
  });

  // Preserve Market Discovery position when the user opens a club/source in another tab and
  // comes back. This is independent of browser back/forward restoration and survives a redraw.
  window.addEventListener('pagehide',savePlatformMarketScroll);
  window.addEventListener('popstate',handleAppNavigationHistory);
  window.addEventListener('beforeunload',event=>{if(mirelionAssist.hasChanges()||(typeof selectionGroupPermissions!=='undefined'&&selectionGroupPermissions.hasChanges())||(typeof playCricketConnection!=='undefined'&&playCricketConnection.hasChanges())||(typeof playhqImport!=='undefined'&&playhqImport.hasChanges())||(typeof selectionGroupSetup!=='undefined'&&selectionGroupSetup.hasChanges())||(typeof clubWeek!=='undefined'&&clubWeek.hasChanges())||selectionState?.busy||selectionState?.pending||selectionState?.formDirty||coachingStaffDirty()||coachingStaffPending()||clubMessageDirty()||clubMessageState?.sending||teamReviewSavePending()||teamReviewHasUnsavedChanges()||weeklyLoopSavePending()||weeklyLoopHasUnsavedChanges()||makeYourCallSavePending()||makeYourCallHasUnsavedChanges()||engagementSavePending()||engagementHasUnsavedChanges()){event.preventDefault();event.returnValue='';}});
  window.addEventListener('pageshow',()=>restorePlatformMarketScroll());
  document.addEventListener('visibilitychange',()=>{
    if(document.visibilityState==='hidden')savePlatformMarketScroll();
    else if(document.visibilityState==='visible')restorePlatformMarketScroll();
  });
  window.addEventListener('scroll',()=>{
    if(platformView!=='market')return;
    if(window.__bdpMarketScrollRaf)return;
    window.__bdpMarketScrollRaf=requestAnimationFrame(()=>{
      window.__bdpMarketScrollRaf=null;
      savePlatformMarketScroll();
    });
  },{passive:true});

  await routeAuth();
}

function redirectUrl(){
  return location.origin+location.pathname+location.search;
}

async function kickLiveEmailDelivery(){
  // Normal club workflow emails are delivered by the Supabase Database Webhook
  // on outbound_messages. Only Platform Admin pages manually flush the global queue.
  if(!platformRole)return;
  try{
    await supabase.functions.invoke('dispatch-outbox',{
      body:{action:'dispatch',limit:20,public_base_url:`${location.origin}${location.pathname}`}
    });
  }catch(err){
    console.warn('Email dispatch could not be started',err);
  }
}

function outboundMessageAgeMinutes(message){
  const started=message?.processing_at||message?.created_at;
  if(!started)return 0;
  return Math.max(0,(Date.now()-new Date(started).getTime())/60000);
}

async function loadAllPlatformRows(makeQuery){
  const rows=[];
  const pageSize=500;
  try{
    for(let offset=0;;offset+=pageSize){
      const {data,error}=await makeQuery().range(offset,offset+pageSize-1);
      if(error)return {data:null,error};
      rows.push(...(data||[]));
      if(!data||data.length<pageSize)return {data:rows,error:null};
    }
  }catch(error){return {data:null,error};}
}

function safePublicSourceUrl(value){
  try{const url=new URL(String(value||'').trim());return ['https:','http:'].includes(url.protocol)?url.href:'';}
  catch{return '';}
}

async function retryPlatformDelivery(message,settings){
  if(settings?.email_mode!=='live')throw new Error('Email delivery is not in Live mode. Check provider setup in Platform Settings.');
  if(!settings.email_live_from||new Date(message.created_at)<new Date(settings.email_live_from))throw new Error('This message is outside the live delivery window and cannot be retried.');
  if(message.failed_at&&!message.sent_at){
    const {error}=await supabase.rpc('platform_retry_outbound_message',{p_message_id:message.id});
    if(error)throw error;
  }
  // Keep the existing dispatcher unchanged. It processes the queue in date order.
  // Check this exact message afterwards; a successful request does not prove it sent.
  const {data,error}=await supabase.functions.invoke('dispatch-outbox',{body:{action:'dispatch',limit:25,public_base_url:`${location.origin}${location.pathname}`}});
  if(error||data?.error)throw new Error(data?.error||error?.message||'Delivery retry could not start.');
  if(data?.skipped)throw new Error(data.reason||'Delivery was skipped.');
  const {data:current,error:readError}=await supabase.from('outbound_messages').select('sent_at,failed_at,last_error,processing_at').eq('id',message.id).single();
  if(readError)throw new Error(`Retry requested, but the result could not be checked: ${readError.message}`);
  if(current?.failed_at&&!current.sent_at)throw new Error(current.last_error||'Email delivery failed again.');
  return current?.sent_at?'Email recorded as sent.':'Retry requested. This email is still waiting in the delivery queue.';
}

function outboundMessageState(message,settings){
  if(message?.sent_at)return 'sent';
  if(message?.failed_at)return 'failed';
  const live=settings?.email_mode==='live';
  const liveFrom=settings?.email_live_from?new Date(settings.email_live_from).getTime():null;
  const createdAt=message?.created_at?new Date(message.created_at).getTime():null;
  if(!live || (liveFrom&&createdAt&&createdAt<liveFrom))return 'prototype-only';
  if(message?.processing_at)return 'sending';
  return 'queued';
}

function outboundMessageNeedsAttention(message,settings){
  if(message?.hidden_from_platform_queue)return false;
  if(settings?.email_mode!=='live'||!settings.email_live_from)return false;
  if(new Date(message?.created_at)<new Date(settings.email_live_from))return false;
  const state=outboundMessageState(message,settings);
  return state==='failed'||(['queued','sending'].includes(state)&&outboundMessageAgeMinutes(message)>=10);
}

function outboundMessageLabel(message,settings){
  const state=outboundMessageState(message,settings);
  if(state==='sent')return `Sent ${new Date(message.sent_at).toLocaleString()}`;
  if(state==='failed')return 'Delivery failed';
  if(state==='prototype-only')return 'Prototype history';
  if(outboundMessageAgeMinutes(message)>=10)return state==='sending'?'Sending is delayed':'Queued for more than 10 minutes';
  return state==='sending'?'Sending':'Queued';
}

function outboundTemplateLabel(templateKey){
  return ({
    prospect_intro:'Prospect invitation',
    prospect_follow_up:'Prospect follow-up',
    club_trial_invitation:'Club Trial invitation',
    club_trial_reminder:'Club Trial activation reminder',
    club_admin_invitation:'Club Admin invitation',
    philosophy_lead_invitation:'Philosophy Lead invitation'
  }[templateKey]||String(templateKey||'Email').replaceAll('_',' '));
}

async function loadPlatformContext(){
  if(!session){platformRole=null;platformAccessError=false;canBootstrapPlatform=false;return;}
  const userId=session.user.id;
  const [roleResult,bootstrapResult]=await Promise.allSettled([
    supabase.rpc('get_my_platform_role'),
    supabase.rpc('can_bootstrap_platform_owner')
  ]);
  if(session?.user?.id!==userId)return;
  platformAccessError=roleResult.status==='rejected'||!!roleResult.value?.error;
  platformRole=platformAccessError?null:roleResult.value?.data||null;
  canBootstrapPlatform=!platformAccessError&&bootstrapResult.status==='fulfilled'&&!bootstrapResult.value?.error&&!!bootstrapResult.value?.data;
}

async function routeAuth(){
  const params=new URLSearchParams(location.search);
  const passwordNotice=passwordFlow.takeNotice();
  if(passwordNotice){renderLogin(passwordNotice);return;}
  if(passwordFlow.activeFor(session)){renderPasswordSetup();return;}
  if(isLegacyOrigin(location.href)&&!legacyAppSession){
    app.innerHTML=`<div class="login"><div class="section-label">Mirelion</div><h1>Continue at our new home.</h1><p>${session?'Your account link has been completed.':'If your account link has expired, request a new one from the sign-in page.'} Sign in at Mirelion with your existing email and password. Your club and access stay with your account.</p><a class="btn secondary" href="${esc(mirelionAppUrl(location.href))}">Continue to Mirelion</a></div>`;return;
  }
  if(params.has('trial_product')){await renderProductTrialEntry();return;}
  if(params.has('enquiry')){await renderProductEnquiryEntry();return;}
  if(params.has('close_invitation')){await renderCloseInvitationRoute(params.get('close_invitation'));return;}
  if(!session && params.has('signin')){renderLogin();return;}
  if(params.has('trial')){await renderPublicTrialEntry();return;}
  const leadToken=params.get('lead');
  const prospectToken=params.get('prospect');
  const paymentToken=params.get('payment');
  const adminInviteToken=params.get('admin_invite');
  const philosophyInviteToken=params.get('philosophy_invite');
  const selectionInviteToken=params.get('selection_invite');
  const leadHandoverToken=params.get('lead_handover');
  const playerJoinToken=params.get('player_join');
  const joinCodeToken=params.get('join');

  if(leadToken){await renderSalesProspectRoute(leadToken);return;}
  if(prospectToken){await renderProspectRoute(prospectToken);return;}
  if(paymentToken){await renderPaymentRoute(paymentToken);return;}
  if(adminInviteToken){await renderAdminInviteRoute(adminInviteToken);return;}
  if(selectionInviteToken){await renderSelectionInviteRoute(selectionInviteToken);return;}
  if(philosophyInviteToken){await renderPhilosophyInviteRoute(philosophyInviteToken);return;}
  if(leadHandoverToken){await renderLeadAdminHandoverRoute(leadHandoverToken);return;}
  if(params.has('player_join')){await renderPlayerJoinRoute(playerJoinToken);return;}

  if(joinCodeToken){
    if(!session){
      renderJoinAccountEntry();
      return;
    }
    await loadPlatformContext();
    await renderJoinByCode(joinCodeToken);
    return;
  }

  if(!session){renderLogin();return;}
  await loadPlatformContext();
  // Reload this browser entry after authentication. Explicit club/platform links win.
  if(!params.has('club')&&!params.has('tab')&&!params.has('platform')&&await resumeAppNavigationOnLoad())return;
  await loadContext();
}

function authEntryLinks(){
  return '<p class="help"><a href="./">Mirelion home</a> · <a href="./demo.html?stage=help">Explore the tutorials</a> · <a href="./contact.html">Help and contact</a></p>';
}

// Keep only a short-lived club invitation in this tab. Never store email,
// passwords or auth tokens here, and never resume/join a club automatically.
const CLUB_SIGNUP_RETURN_KEY='club-batting-signup-return-v1';
let pendingClubSignupEntry=null;
function clubSignupEntryFromUrl(){
  const params=new URLSearchParams(location.search);
  if(['trial_product','enquiry','trial','lead','prospect','payment','admin_invite','philosophy_invite','selection_invite','lead_handover','close_invitation','platform','club','tab'].some(key=>params.has(key)))return null;
  if(params.has('player_join'))return params.get('player_join').trim()?{kind:'player',token:params.get('player_join')}:null;
  if(params.has('join'))return params.get('join').trim()?{kind:'code',token:params.get('join'),involvement:params.get('involvement')==='coach_captain'?'coach_captain':''}:null;
  return null;
}
function forgetClubSignupEntry(){
  pendingClubSignupEntry=null;
  try{sessionStorage.removeItem(CLUB_SIGNUP_RETURN_KEY);}catch{/* storage unavailable */}
}
function rememberClubSignupEntry(clubName=''){
  if(session)return;
  const entry=clubSignupEntryFromUrl();if(!entry)return;
  pendingClubSignupEntry={...entry,clubName:String(clubName||''),savedAt:Date.now()};
  try{sessionStorage.setItem(CLUB_SIGNUP_RETURN_KEY,JSON.stringify(pendingClubSignupEntry));}catch{/* in-memory fallback */}
}
function clubSignupReturnEntry(){
  if(session)return null;
  const current=clubSignupEntryFromUrl();if(current)return current;
  // Another explicit destination, even an incomplete invitation, wins over a saved one.
  const params=new URLSearchParams(location.search);
  if([...params.keys()].some(key=>!['signin','password_setup','code'].includes(key)))return null;
  let entry=pendingClubSignupEntry;
  try{entry=entry||JSON.parse(sessionStorage.getItem(CLUB_SIGNUP_RETURN_KEY)||'null');}catch{/* bad/unavailable storage */}
  const age=Date.now()-Number(entry?.savedAt);
  if(!entry||!['player','code'].includes(entry.kind)||typeof entry.token!=='string'||!entry.token.trim()||!Number.isFinite(age)||age<0||age>2*60*60*1000){forgetClubSignupEntry();return null;}
  return entry;
}
function clubSignupReturnHtml(){
  const params=new URLSearchParams(location.search);
  if(['trial_product','enquiry','trial','lead','prospect','payment','admin_invite','philosophy_invite','selection_invite','lead_handover','close_invitation','platform','club','tab'].some(key=>params.has(key)))return '';
  const entry=clubSignupReturnEntry();
  if(!entry)return '<p class="help"><strong>Joining a club for the first time?</strong> Open the player or non-playing staff sign-up link your club shared, or scan its QR code. Create your account there before using password help.</p>';
  const target=new URL(location.pathname,location.origin);
  target.searchParams.set(entry.kind==='player'?'player_join':'join',entry.token);
  if(entry.kind==='code'&&entry.involvement==='coach_captain')target.searchParams.set('involvement','coach_captain');
  const label=entry.kind==='player'?'Start player sign-up':entry.involvement==='coach_captain'?'Start non-playing staff sign-up':'Start club sign-up';
  return `<div class="notice" id="clubSignupReturn"><strong>New to Mirelion?</strong><p>Create your account while joining ${esc(entry.clubName||'your club')}. You do not need an existing password.</p><a class="btn secondary" id="returnToClubSignup" href="${esc(target.href)}">${label}</a></div>`;
}

function renderJoinAccountEntry(){
  rememberClubSignupEntry();
  const params=new URLSearchParams(location.search);
  const staffRoute=params.get('involvement')==='coach_captain';
  const passwordUrl=new URL(location.href);passwordUrl.searchParams.set('signin','1');
  app.innerHTML=`<div class="login" style="max-width:650px">
    <div class="section-label">${staffRoute?'Non-playing staff sign-up':'Club invitation'}</div>
    <h1>${staffRoute?'Join your club as non-playing staff.':'Join your club.'}</h1>
    <p>Enter your email. We’ll send you a secure link to create or open your Mirelion account, then bring you back here to finish joining.</p>
    ${staffRoute?'<div class="notice">This registers you as <strong>non-playing staff</strong>, so you won’t receive a Player Plan. Your club assigns any coaching or administration role separately.</div>':''}
    <form id="joinAccountForm">
      <div class="field"><label for="joinAccountEmail">Your email</label><input id="joinAccountEmail" type="email" autocomplete="email" required></div>
      <button class="btn secondary" id="joinAccountButton" type="submit">Email my secure account link</button>
    </form>
    <div id="joinAccountStatus" class="help" role="status" aria-live="polite"></div>
    <p class="help">Already use Mirelion? <a href="${esc(passwordUrl.href)}">Sign in with your password</a>.</p>
    ${authEntryLinks()}
  </div>`;
  document.getElementById('joinAccountForm').onsubmit=async event=>{
    event.preventDefault();
    const button=document.getElementById('joinAccountButton'),status=document.getElementById('joinAccountStatus');
    button.disabled=true;status.textContent='Sending…';authActionInFlight=true;
    try{
      const {error}=await supabase.auth.signInWithOtp({
        email:val('joinAccountEmail'),
        options:{emailRedirectTo:redirectUrl(),shouldCreateUser:true}
      });
      if(error)throw error;
      status.textContent='Check your email and tap the secure link. It will bring you back here to finish joining your club.';
    }catch(error){status.textContent=error.message||'The secure account link could not be sent. Please try again.';}
    finally{authActionInFlight=false;button.disabled=false;}
  };
}

function renderLogin(msg=''){
  const platform=new URLSearchParams(location.search).has('platform');
  const trialEntry=new URLSearchParams(location.search).has('trial');
  app.innerHTML=`<div class="login">
    <div class="section-label">Mirelion${platform?' · Platform Admin':''}</div>
    <h1>${platform?'Platform Admin sign-in':'Welcome back.'}</h1>
    <p>Sign in with your email and password. Your club and access stay with your account.</p>
    ${msg?`<div class="notice">${esc(msg)}</div>`:''}
    ${!platform&&!trialEntry?clubSignupReturnHtml():''}
    <form id="passwordSignIn">
      <div class="field"><label for="email">Email</label><input id="email" name="email" type="email" autocomplete="username" required></div>
      <div class="field"><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="current-password" required></div>
      <button class="btn secondary" type="submit" id="signInButton">Sign in</button>
    </form>
    <p><button class="guide-inline-link" type="button" id="resetPassword">Forgot password?</button> · <button class="guide-inline-link" type="button" id="firstPassword">Set a first password</button></p>
    <p class="help">This browser keeps you signed in. Use Sign out on a shared device.</p>
    <div id="authStatus" class="help" role="status" aria-live="polite"></div>
    <p class="help">${trialEntry?'<a href="./app.html?trial=1" id="backToTrialEntry">Back to club details / create an account</a>':'New club? <a href="./app.html?trial_product=">Try it free with your club</a>.'}</p>
    ${!platform?'<p class="help"><a href="./app.html?platform=1">Platform Admin sign-in</a></p>':''}
    ${authEntryLinks()}
  </div>`;
  document.getElementById('passwordSignIn').onsubmit=async event=>{
    event.preventDefault();
    const button=document.getElementById('signInButton'),status=document.getElementById('authStatus');
    button.disabled=true;status.textContent='Signing in…';authActionInFlight=true;
    try{
      const {data,error}=await supabase.auth.signInWithPassword({email:val('email'),password:document.getElementById('password').value});
      if(error)throw error;
      session=data.session;
      passwordFlow.finish();
      const url=cleanPasswordUrl(location.href);url.searchParams.delete('signin');history.replaceState(history.state,'',url);
      authActionInFlight=false;await routeAuth();
    }catch(error){status.textContent=error.message||'Sign-in could not complete. Please try again.';}
    finally{authActionInFlight=false;button.disabled=false;}
  };
  document.getElementById('resetPassword').onclick=()=>renderPasswordReset(val('email'));
  document.getElementById('firstPassword').onclick=()=>renderPasswordReset(val('email'),true);
  if(trialEntry)document.getElementById('backToTrialEntry').onclick=event=>{
    event.preventDefault();
    if(authActionInFlight)return;
    const target=new URL(location.href);target.searchParams.delete('signin');target.searchParams.delete('continue_trial');
    history.replaceState({},'',target);renderPublicTrialEntry();
  };
}

function renderPasswordReset(email='',firstPassword=false){
  app.innerHTML=`<div class="login"><div class="section-label">Your account</div><h1>${firstPassword?'Set your first password.':'Reset your password.'}</h1>
    ${clubSignupReturnHtml()}
    <p>${firstPassword?'Use your registered email to set a password once. If you have already chosen one, sign in with it.':'Only needed if you have forgotten your password. Otherwise, sign in with your existing password.'}</p>
    <form id="passwordResetForm"><div class="field"><label for="resetEmail">Email</label><input id="resetEmail" type="email" autocomplete="email" value="${esc(email)}" required></div>
    <button class="btn secondary" id="requestReset" type="submit">${firstPassword?'Send password setup link':'Send password reset link'}</button></form>
    <div id="resetStatus" class="help" role="status" aria-live="polite"></div>
    <p><button class="guide-inline-link" id="backToSignIn">Back to sign-in</button></p>${authEntryLinks()}</div>`;
  document.getElementById('backToSignIn').onclick=()=>{
    passwordFlow.finish();
    history.replaceState(history.state,'',cleanPasswordUrl(location.href));renderLogin();
  };
  document.getElementById('passwordResetForm').onsubmit=async event=>{
    event.preventDefault();const button=document.getElementById('requestReset'),status=document.getElementById('resetStatus');
    button.disabled=true;status.textContent='Sending…';
    const target=cleanPasswordUrl(location.href);target.hash='';target.searchParams.set('password_setup','1');
    try{
      const {error}=await supabase.auth.resetPasswordForEmail(val('resetEmail'),{redirectTo:target.href});
      if(error)throw error;
      status.textContent='If an account exists for that email, a password link is on its way. Check your inbox and junk folder. If you have not registered yet, use your club’s sign-up link first.';
    }catch(error){status.textContent=error.message||'The link could not be requested. Please try again.';}
    finally{button.disabled=false;}
  };
}

function renderPasswordSetup(){
  if(!session){
    passwordFlow.finish();
    renderLogin('Sign in with your existing password. Choose “Forgot password?” only if you need to reset it.');
    return;
  }
  const passwordAccountId=session.user.id;
  app.innerHTML=`<div class="login"><div class="section-label">Your account</div><h1>Choose your password.</h1>
    <p>Set a password for ${esc(session.user.email||'your account')} so you can sign in directly next time.</p>
    <form id="savePasswordForm"><div class="field"><label for="newPassword">New password</label><input id="newPassword" type="password" autocomplete="new-password" minlength="10" required></div>
    <div class="field"><label for="confirmPassword">Confirm password</label><input id="confirmPassword" type="password" autocomplete="new-password" minlength="10" required></div>
    <p class="help">Use at least 10 characters.</p><div class="btnrow"><button class="btn secondary" id="savePassword" type="submit">Save password & continue</button><button class="guide-inline-link" id="cancelPassword" type="button">Continue without changing</button></div></form>
    <div id="passwordStatus" class="help" role="status" aria-live="polite"></div>${authEntryLinks()}</div>`;
  document.getElementById('cancelPassword').onclick=async()=>{
    if(authActionInFlight)return;
    passwordFlow.finish();history.replaceState(history.state,'',cleanPasswordUrl(location.href));await routeAuth();
  };
  document.getElementById('savePasswordForm').onsubmit=async event=>{
    if(authActionInFlight){event.preventDefault();return;}
    event.preventDefault();const password=document.getElementById('newPassword').value;
    const status=document.getElementById('passwordStatus'),button=document.getElementById('savePassword');
    if(session?.user?.id!==passwordAccountId){status.textContent='Your signed-in account changed. Continue without changing, then check your account before trying again.';return;}
    if(password.length<10){status.textContent='Use at least 10 characters.';return;}
    if(password!==document.getElementById('confirmPassword').value){status.textContent='The passwords do not match.';return;}
    button.disabled=true;authActionInFlight=true;status.textContent='Saving…';
    try{
      const {error}=await supabase.auth.updateUser({password});if(error)throw error;
      passwordFlow.finish();
      history.replaceState(history.state,'',cleanPasswordUrl(location.href));authActionInFlight=false;await routeAuth();
    }catch(error){status.textContent=error.code==='same_password'?'That is already your current password. Choose “Continue without changing” to keep using it.':error.message||'The password could not be saved. Please try again.';}
    finally{authActionInFlight=false;button.disabled=false;}
  };
}

async function openAccountPassword(){
  if(club&&!await saveClubEditsBeforeNavigation())return;
  passwordFlow.begin(session);
  renderPasswordSetup();
}

async function continueWebsiteTrial(clubName,contactName){
  const requestingUserId=session?.user?.id||null;
  const {data,error}=await supabase.rpc('begin_public_club_trial',{p_club_name:clubName,p_contact_name:contactName});
  if(error)throw error;
  if((session?.user?.id||null)!==requestingUserId)throw new Error('Your signed-in account changed. Check the email shown before continuing.');
  if(!data?.public_token&&!data?.existing_club_id)throw new Error('The trial could not be prepared. Please try again.');
  publicTrialDraft=null;
  const target=new URL(location.href);target.hash='';target.search='';
  if(data.existing_club_id){target.searchParams.set('club',data.existing_club_id);localStorage.setItem('bdp-context','club');}
  else target.searchParams.set('prospect',data.public_token);
  history.replaceState({},'',target);
  await routeAuth();
}

async function renderPublicTrialEntry(){
  const continuation=new URLSearchParams(location.search).get('continue_trial')==='1';
  // Historical signup metadata belongs to its email-confirmation return only.
  // Opening a fresh trial must not prefill an earlier club on this account.
  const saved=continuation?(session?.user?.user_metadata?.club_trial_request||{}):(publicTrialDraft||{});
  if(session&&continuation&&saved.club_name&&saved.contact_name){
    app.innerHTML='<div class="login"><h1>Preparing your club’s trial…</h1><p>Your trial starts only when you activate it on the next screen.</p></div>';
    try{await continueWebsiteTrial(saved.club_name,saved.contact_name);return;}
    catch(error){renderPublicTrialForm(saved,error.message);return;}
  }
  renderPublicTrialForm(saved);
}

function rememberPublicTrialDraft(){
  publicTrialDraft={club_name:val('trialClubName'),contact_name:val('trialContactName')};
  return publicTrialDraft;
}

async function switchPublicTrialAccount(){
  const button=document.getElementById('trialUseDifferentEmail');
  if(!button||button.disabled||authActionInFlight)return;
  const continueButton=document.getElementById('trialContinue'),status=document.getElementById('trialSwitchStatus');
  const draft=rememberPublicTrialDraft();
  button.disabled=true;continueButton.disabled=true;authActionInFlight=true;
  status.textContent='Signing out so you can choose another email…';
  try{
    const {error}=await supabase.auth.signOut({scope:'local'});
    if(error)throw error;
    session=null;platformRole=null;platformAccessError=false;canBootstrapPlatform=false;
    club=null;membership=null;allMemberships=[];userProfile=null;
    // A previous confirmation URL must not resume the next account's old trial.
    const target=new URL(location.href);target.hash='';
    for(const key of ['continue_trial','signin','code'])target.searchParams.delete(key);
    history.replaceState({},'',target);
    renderPublicTrialForm(draft,'Choose another email below, or sign in with your password if you already have an account.');
    document.getElementById('trialEmail').focus();
  }catch(error){
    status.textContent=error?.message||'Could not switch accounts. Please try again.';
  }finally{
    authActionInFlight=false;button.disabled=false;continueButton.disabled=false;
  }
}

function renderPublicTrialForm(saved={},message=''){
  const signedIn=!!session;
  app.innerHTML=`<style>.public-trial-entry .prospect-card>p,.public-trial-entry .help,.public-trial-entry .notice{font-size:14px;line-height:1.55}.public-trial-entry .field label{font-size:13px}.public-trial-entry .field input{font-size:16px;min-height:46px}.public-trial-entry .btn{font-size:14px;min-height:44px}.public-trial-entry .prospect-card h2{font-size:27px;margin-top:6px}.trial-account-choice{margin:18px 0;padding:16px;border:1px solid #c4cee6;border-left:4px solid #293780;border-radius:12px;background:#f4f6fc;overflow-wrap:anywhere}.trial-account-choice p{margin:8px 0;font-size:14px;line-height:1.55}.trial-account-choice .btnrow{margin-top:12px;align-items:center;gap:12px}.trial-account-choice .btn{background:#fff;border:1px solid #293780;color:#17245f}</style><div class="prospect-shell public-trial-entry">${prospectIntro({is_club_trial:true,entry_phase:'signup',club_name:saved.club_name||'your club'})}<section class="card prospect-card"><div class="section-label">Your full Club Trial</div>
    <h2>Try it free with your club.</h2><p>Bring your club’s philosophy, Player Plans and training together. Your full 60-day trial starts when you activate it.</p>
    <div class="notice">No upfront payment. No automatic charge. You choose whether to continue after the trial.</div>
    ${signedIn?`<section class="trial-account-choice" aria-label="Account for this club">
      <strong>Account for this club</strong>
      <p>Signed in as <strong>${esc(session.user.email||'')}</strong>.</p>
      <p>Setting up a different club? Keep this email and enter the new club below, or choose a different email.</p>
      <div class="btnrow"><button class="btn ghost" type="button" id="trialUseDifferentEmail">Use a different email</button><a href="./app.html">Back to my account</a></div>
      <p class="help">Choosing a different email signs you out in this browser. Your existing clubs stay as they are.</p>
      <div id="trialSwitchStatus" class="help" role="status" aria-live="polite"></div>
    </section>`:'<p>Already registered? <a href="./app.html?trial=1&signin=1" id="trialExistingSignIn">Sign in with your password</a>.</p>'}
    <form id="trialEntryForm">
      <div class="field"><label for="trialClubName">Club name</label><input id="trialClubName" autocomplete="organization" maxlength="160" minlength="3" required value="${esc(saved.club_name||'')}"></div>
      <div class="field"><label for="trialContactName">Your name</label><input id="trialContactName" autocomplete="name" maxlength="120" minlength="2" required value="${esc(saved.contact_name||session?.user?.user_metadata?.display_name||'')}"></div>
      ${signedIn?'':`<div class="field"><label for="trialEmail">Your email</label><input id="trialEmail" type="email" autocomplete="username" required></div>
      <div class="field"><label for="trialPassword">Choose a password</label><input id="trialPassword" type="password" minlength="10" autocomplete="new-password" required></div>
      <p class="help">Use at least 10 characters. Confirm your email once, then use your password for future visits.</p>`}
      <button class="btn secondary" type="submit" id="trialContinue">${signedIn?'Continue with this email':'Create account & continue'}</button>
    </form><div id="trialEntryStatus" class="help" role="status" aria-live="polite">${esc(message)}</div>
    <p class="help">Already invited by Club Batting? Use your invitation to continue the trial already prepared for you.</p>
    <p><a class="btn ghost" href="./demo.html?stage=help">Explore the tutorials</a></p>${authEntryLinks()}</section></div>`;
  if(signedIn)document.getElementById('trialUseDifferentEmail').onclick=switchPublicTrialAccount;
  else document.getElementById('trialExistingSignIn').onclick=event=>{
    event.preventDefault();
    if(authActionInFlight)return;
    rememberPublicTrialDraft();
    const target=new URL(location.href);target.searchParams.set('signin','1');target.searchParams.delete('continue_trial');
    history.replaceState({},'',target);renderLogin('Sign in with the email you want to use for this club.');
  };
  document.getElementById('trialEntryForm').onsubmit=async event=>{
    event.preventDefault();const button=document.getElementById('trialContinue'),status=document.getElementById('trialEntryStatus');
    if(button.disabled||authActionInFlight)return;
    const {club_name:clubName,contact_name:contactName}=rememberPublicTrialDraft();
    const switchButton=document.getElementById('trialUseDifferentEmail');
    if(switchButton)switchButton.disabled=true;
    const buttonLabel=button.textContent;
    button.disabled=true;button.textContent='Preparing…';status.textContent='';authActionInFlight=true;
    try{
      if(!session){
        const target=new URL('./app.html?trial=1&continue_trial=1',location.href);
        const {data,error}=await supabase.auth.signUp({email:val('trialEmail'),password:document.getElementById('trialPassword').value,
          options:{emailRedirectTo:target.href,data:{display_name:contactName,club_trial_request:{club_name:clubName,contact_name:contactName}}}});
        if(error)throw error;
        if(!data.session){
          document.getElementById('trialPassword').value='';
          status.textContent='Check your email to confirm your new account and continue. Your trial has not started. If you already have an account, use Sign in above instead.';
          return;
        }
        session=data.session;
      }
      await continueWebsiteTrial(clubName,contactName);
    }catch(error){status.textContent=error.message||'We couldn’t prepare the next step. Please try again.';}
    finally{authActionInFlight=false;button.disabled=false;button.textContent=buttonLabel;if(switchButton)switchButton.disabled=false;}
  };
}

function renderAppOpening(message){
 let status=document.getElementById('appStartStatus');
 if(!status){app.innerHTML='<section class="app-start" aria-label="Mirelion"><header><span class="app-start-mark" aria-hidden="true">M</span><span class="app-start-brand">Mirelion</span></header><main><p id="appStartStatus" role="status" aria-live="polite"></p><div class="app-start-placeholder" aria-hidden="true"></div><button id="appStartRetry" type="button" hidden>Try again</button></main></section>';status=document.getElementById('appStartStatus');}
 status.textContent=message;
}

async function loadContext({navigation=null,navigationRequest=null}={}){
  const requestingUser=session?.user?.id;
  const stillCurrent=()=>session?.user?.id===requestingUser&&(navigationRequest===null||navigationRequest===appNavigationRequest);
  renderAppOpening('Opening your club…');

  const {data:memberships,error}=await supabase
    .from('club_memberships')
    .select('club_id,role,involvement,permission_role,clubs(id,name,slug,join_code,player_join_token,player_signup_open,lead_admin_user_id,primary_colour,accent_colour,logo_data_url,website_url,branding_updated_at,subscription_calendar,season_start,season_end,archived_at)')
    .eq('user_id',session.user.id);

  if(!stillCurrent())return;
  if(error){
    app.innerHTML=`<div class="splash">${esc(error.message)}</div>`;
    return;
  }

  allMemberships=(memberships||[]).filter(m=>!m.clubs?.archived_at);

  if(navigation?.scope==='platform'&&platformRole){
    restorePlatformNavigationState(navigation);
    return renderPlatformConsole();
  }

  const launchParams=new URLSearchParams(location.search);
  capturePhoneLaunch(launchParams);
  const routeClub=launchParams.get('club');
  const routeTab=launchParams.get('tab');
  const assistLaunch=assistLaunchFromSearch(location.search);
  if(assistLaunch)pendingAssistLaunch=assistLaunch;
  if(routeClub && !allMemberships.some(m=>m.club_id===routeClub)){
    app.innerHTML=`<div class="login"><div class="section-label">Club Batting</div><h1>This club link is for a different account.</h1><p>Sign in with the email address that received the invitation. If you already use that address, ask your club to check your registration.</p><div class="btnrow"><button class="btn secondary" id="launchSignOut">Sign out</button><button class="btn ghost" id="launchMyClubs">Open my clubs</button></div></div>`;
    document.getElementById('launchSignOut').onclick=()=>signOutClubBatting();
    document.getElementById('launchMyClubs').onclick=()=>{
      clearClubLaunchRoute();
      localStorage.setItem('bdp-context','club');
      loadContext();
    };
    return;
  }

  if(!navigation && !routeClub && platformRole && (launchParams.has('platform') || (routeTab!=='assist'&&localStorage.getItem('bdp-context')==='platform'))){
    if(assistLaunch)platformView='guide_requests';
    if(launchParams.has('platform')){const target=new URL(location.href);target.searchParams.delete('platform');history.replaceState({},'',target);}
    return renderPlatformConsole();
  }

  if(!allMemberships.length){
    if(platformRole){if(assistLaunch)platformView='guide_requests';return renderPlatformConsole();}
    renderNoClub();
    return;
  }

  const savedClub=navigation?.clubId||routeClub||localStorage.getItem('bdp-club-id');
  membership=allMemberships.find(m=>m.club_id===savedClub)||allMemberships[0];
  club=membership.clubs;
  localStorage.setItem('bdp-club-id',club.id);
  localStorage.setItem('bdp-context','club');

  const savedTab=localStorage.getItem(`bdp-tab-${club.id}`);
  if(savedTab)currentTab=savedTab;

  renderAppOpening('Loading '+club.name+'…');
  const [{data:profileData}]=await Promise.all([supabase
    .from('user_profiles')
    .select('*')
    .eq('user_id',session.user.id)
    .maybeSingle(),loadSelectionsAccess(),loadScheduledTrialContext()]);

  if(!stillCurrent())return;
  userProfile=profileData||null;
  if(!userProfile || !hasPlayingChoice(membership.involvement)){
    renderFirstIdentitySetup();
    return;
  }

  try{await loadData({accessReady:true,trialsReady:true});}
  catch(error){
    app.innerHTML=`<div class="login"><h1>Your club’s plans could not be loaded.</h1><p>${esc(error.message||'Check your connection and try again.')}</p><button class="btn secondary" id="retryClubLoad">Try again</button></div>`;
    document.getElementById('retryClubLoad').onclick=()=>loadContext({navigation,navigationRequest});
    return;
  }
  if(!stillCurrent())return;
  // A fresh sign-in starts at Home; a reload restores its existing browser destination.
  currentTab=productTrialWaiting()?'products':selectionsStandalone()?'teams':canUseClubHome()?'dashboard':isPlayerUser()?'playerhome':savedTab||'howwetrain';
  if(joinedAvailabilityClub===club.id&&selectionsEnabled()){ensureSelections().view='availability';currentTab='teams';joinedAvailabilityClub=null;}
  if(routeClub===club.id || (!routeClub&&routeTab==='assist')){
    if(['products','playerhome','innings','make_your_call','myplan','howwebat','howwetrain','conversations','guide','messages','phone_app','teams','assist'].includes(routeTab) && canOpenClubTab(routeTab)){
      currentTab=routeTab;
      if(routeTab==='myplan')builderSection='core';
      if(routeTab==='teams'){const q=new URLSearchParams(location.search);ensureSelections().weekLaunch={view:q.get('team_view'),date:q.get('team_date'),fixture:q.get('fixture'),plan:q.get('replacement')};}
    }
    clearClubLaunchRoute();
  }
  if(navigation?.clubId===club.id){
    if(navigation.tab==='workshop_preview')await restoreWorkshopPreviewFromNavigation(navigation);
    if(!stillCurrent())return;
    restoreClubNavigationState(navigation);
  }
  await applyPhoneLaunch();
  return renderShell();
}

function clearClubLaunchRoute(){
  const url=new URL(location.href||`${location.origin}${location.pathname}${location.search}`);
  url.searchParams.delete('club');
  url.searchParams.delete('tab');
  for(const key of ['message','coaching','prepare','team_view','team_date','fixture','replacement','assist_thread'])url.searchParams.delete(key);
  history.replaceState({},'',url.pathname+url.search+url.hash);
}

function roleCards(prefix,selected=''){
  const roles=[
    ['player','Player',selectionsStandalone()?'I play for this club.':'I want to build and use my own Player Plan.'],
    ['coach_captain','Non-playing staff',selectionsStandalone()?'I help the club without playing.':'I do not need my own Player Plan.'],
    ['both','Player who also coaches or captains',selectionsStandalone()?'I play and help with the team. Selection permissions are set by Club Admin.':'I play and need my own Player Plan. Coaching duties and player access are set separately.']
  ];
  return `<div class="role-grid">${roles.map(([k,t,d])=>`
    <label class="role-card ${selected===k?'on':''}">
      <input type="radio" name="${prefix}" value="${k}" ${selected===k?'checked':''}>
      <strong>${t}</strong><p>${d}</p>
    </label>`).join('')}</div>`;
}

function wireRoleCards(){
  document.querySelectorAll('.role-card input').forEach(r=>r.onchange=()=>{
    document.querySelectorAll(`input[name="${r.name}"]`).forEach(x=>x.closest('.role-card').classList.toggle('on',x.checked));
  });
}

function renderNoClub(){
  app.innerHTML=`<div class="login" style="max-width:760px">
    <h1>Join your club.</h1>
    <p>If your club already uses the platform, enter its join code. If your club is being set up for the first time, use the activation or Admin invitation link sent by the platform.</p>
    <section class="card">
      <h2>Join an existing club</h2>
      <div class="field"><label>Your name</label><input id="joinName" placeholder="Full name"></div>
      <div class="field"><label>Club join code</label><input id="joinCode" placeholder="e.g. A1B2C3D4"></div>
      <h2>How are you involved?</h2>
      ${roleCards('joinRole','player')}
      <button class="btn secondary" id="joinClub">Join club</button>
      <div id="joinStatus" class="help"></div>
    </section>
    <p><a class="btn ghost" href="./app.html?enquiry=&enquiry_request=all">My product requests</a></p>
    <div class="notice" style="margin-top:14px"><strong>Setting up a new club?</strong><br>Choose either product or both and start a free trial. <a href="./app.html?trial_product=">Start free trial</a>.</div>
  </div>`;

  wireRoleCards();

  document.getElementById('joinClub').onclick=async()=>{
    const involvement=document.querySelector('input[name="joinRole"]:checked')?.value;
    const status=document.getElementById('joinStatus');
    status.textContent='Joining…';
    const {error}=await supabase.rpc('join_club_by_code',{
      p_join_code:val('joinCode'),
      p_display_name:val('joinName'),
      p_involvement:involvement
    });
    if(error){status.textContent=error.message;return;}
    await loadContext();
  };
}

function hasPlayingChoice(involvement){
  return ['player','coach_captain','both'].includes(involvement);
}

function renderFirstIdentitySetup(){
  app.innerHTML=`<div class="login" style="max-width:720px">
    <div class="section-label">${esc(club.name)}</div>
    <h1>How are you involved?</h1>
    <p>Choose whether you play for this club. Coaching duties and access to other players are set separately.</p>
    ${membership.involvement==='philosophy_contributor'?'<p>Your Workshop invitation is accepted. Before you continue, tell us whether you also play for this club. Your Workshop access and any assigned club roles stay with your account.</p>':''}
    <div class="field"><label>Your name</label><input id="myName" value="${esc(userProfile?.display_name||'')}"></div>
    ${roleCards('myRole',membership.involvement||'')}
    <div class="btnrow"><button class="btn secondary" id="saveIdentity">Continue</button></div>
    <div id="identitySetupStatus" class="help" role="status" aria-live="polite"></div>
  </div>`;
  wireRoleCards();
  const targetClubId=club.id,requestingUserId=session?.user?.id;
  const button=document.getElementById('saveIdentity');
  const stillCurrent=()=>club?.id===targetClubId&&session?.user?.id===requestingUserId&&document.getElementById('saveIdentity')===button;
  let saving=false;
  document.getElementById('saveIdentity').onclick=async()=>{
    if(saving||!stillCurrent())return;
    const status=document.getElementById('identitySetupStatus');
    const involvement=document.querySelector('input[name="myRole"]:checked')?.value;
    const displayName=val('myName');
    if(!['player','coach_captain','both'].includes(involvement)){status.textContent='Choose how you are involved.';return;}
    if(displayName.length<2||displayName.length>120){status.textContent='Enter your name (2–120 characters).';return;}
    saving=true;button.disabled=true;
    const controls=[document.getElementById('myName'),...document.querySelectorAll('input[name="myRole"]')].filter(Boolean);
    controls.forEach(control=>control.disabled=true);
    status.textContent='Saving…';
    try{
      const {error}=await supabase.rpc('setup_my_club_identity',{
        p_club_id:targetClubId,p_display_name:displayName,p_involvement:involvement
      });
      if(error)throw error;
      if(!stillCurrent())return;
      // A successful request must not silently reload a different involvement.
      const {data:saved,error:readError}=await supabase.from('club_memberships')
        .select('involvement').eq('club_id',targetClubId).eq('user_id',requestingUserId).maybeSingle();
      if(readError)throw readError;
      if(saved?.involvement!==involvement)throw new Error('Your involvement was not saved correctly. Please try again.');
      if(!stillCurrent())return;
      playersWorkspaceSelectedId=null;playersWorkspaceData=null;playersWorkspaceFeedbackData=null;
      await loadContext();
    }catch(error){
      if(stillCurrent())status.textContent=error?.message||'We couldn’t save your involvement. Please try again.';
    }finally{
      saving=false;if(stillCurrent()){button.disabled=false;controls.forEach(control=>control.disabled=false);}
    }
  };
}


async function loadData({accessReady=false,trialsReady=false}={}){
  await Promise.all([accessReady?null:loadSelectionsAccess(),trialsReady?null:loadScheduledTrialContext()]);
  if(selectionsStandalone()){
    myPlayer=null;workflow=null;workshop=null;myContributor=null;myContribution=null;
    philosophyVersions=[];howWeBatVersions=[];playerPlanStructureVersions=[];
    howWeBatDraft=null;playerPlanStructureDraft=null;publishedProfile={};clubProfile={};
    selectedDims=new Map();weights=new Map();dimensions=[];
    return;
  }
  const [pRes,dRes,sdRes,wRes,playerRes,workshopRes,myContributorRes,versionsRes,hwbDraftRes,hwbVersionsRes,planDraftRes,planVersionsRes]=await Promise.all([
    supabase.from('philosophy_profiles').select('*').eq('club_id',club.id).single(),
    supabase.from('philosophy_dimension_catalogue').select('*').order('sort_order'),
    supabase.from('club_philosophy_dimensions').select('*').eq('club_id',club.id),
    supabase.from('club_format_weights').select('*').eq('club_id',club.id),
    supabase.from('players').select('*').eq('club_id',club.id).eq('user_id',session.user.id).eq('active',true).maybeSingle(),
    supabase.from('philosophy_workshops').select('*').eq('club_id',club.id).maybeSingle(),
    supabase.from('philosophy_contributors').select('*').eq('club_id',club.id).eq('user_id',session.user.id).maybeSingle(),
    supabase.from('philosophy_versions').select('*').eq('club_id',club.id).order('version_number',{ascending:false}),
    supabase.from('how_we_bat_drafts').select('*').eq('club_id',club.id).maybeSingle(),
    supabase.from('how_we_bat_versions').select('*').eq('club_id',club.id).order('philosophy_version',{ascending:false}),
    supabase.from('player_plan_structure_drafts').select('*').eq('club_id',club.id).maybeSingle(),
    supabase.from('player_plan_structure_versions').select('*').eq('club_id',club.id).order('philosophy_version',{ascending:false})
  ]);

  // A failed read is not an empty draft. Keep the current work intact so the
  // interface cannot replace saved wording with generated defaults on a retry.
  const draftLoadError=workshopRes.error||versionsRes.error||hwbDraftRes.error||hwbVersionsRes.error||planDraftRes.error||planVersionsRes.error;
  if(draftLoadError)throw new Error(`The club’s saved plans could not be loaded. ${draftLoadError.message}`);

  publishedProfile=pRes.data||{};
  publishedProfile.identity_values=Array.isArray(publishedProfile.identity_values)?publishedProfile.identity_values:[];
  publishedProfile.formats_enabled=publishedProfile.formats_enabled||{t20:true,limited_overs:true,long_form:true};
  dimensions=dRes.data||[];
  publishedSelectedDims=new Map((sdRes.data||[]).map(x=>[x.dimension_key,x]));
  publishedWeights=new Map((wRes.data||[]).map(x=>[`${x.dimension_key}:${x.format_key}`,Number(x.weight)]));

  workshop=workshopRes.data||null;
  myContributor=myContributorRes.data||null;
  philosophyVersions=versionsRes.data||[];
  howWeBatDraft=upgradeLegacyHowWeBatWording(hwbDraftRes.data||null);
  howWeBatBuilderDirty=false;
  howWeBatVersions=hwbVersionsRes.data||[];
  playerPlanStructureDraft=planDraftRes.data||null;
  playerPlanStructureVersions=planVersionsRes.data||[];
  playerPlanStructureWorking=null;
  playerPlanStructureDirty=false;
  playerPlanStructureManualEdit=false;
  myContribution=null;

  if(myContributor){
    const {data:c}=await supabase
      .from('philosophy_contributions')
      .select('*')
      .eq('club_id',club.id)
      .eq('user_id',session.user.id)
      .maybeSingle();
    myContribution=c||null;
  }

  if(myContribution){
    clubProfile={
      identity_values:Array.isArray(myContribution.identity_values)?myContribution.identity_values:[],
      identity_note:myContribution.identity_note||'',
      formats_enabled:myContribution.formats_enabled||{t20:true,limited_overs:true,long_form:true}
    };

    const noteObj=myContribution.dimension_notes||{};
    selectedDims=new Map((myContribution.selected_dimensions||[]).map(k=>[
      k,
      {club_id:club.id,dimension_key:k,enabled:true,club_note:noteObj[k]||''}
    ]));
    weights=new Map(Object.entries(myContribution.format_weights||{}).map(([k,v])=>[k,Number(v)]));
  }else{
    clubProfile=structuredClone(publishedProfile);
    selectedDims=new Map([...publishedSelectedDims.entries()].map(([k,v])=>[k,{...v}]));
    weights=new Map(publishedWeights);
  }

  myPlayer=isPlayerUser()?(playerRes.data||null):null;

  if(myPlayer){
    const {data:w}=await supabase
      .from('player_plan_workflows')
      .select('*')
      .eq('player_id',myPlayer.id)
      .maybeSingle();
    workflow=w||null;
  }else{
    workflow=null;
  }
}

function isAdmin(){
  return membership.permission_role==='admin';
}
function isCoachCaptain(){
  return ['coach_captain','both'].includes(membership.involvement);
}
function isPlayerUser(){
  return ['player','both'].includes(membership.involvement);
}
function canUsePlayersWorkspace(){
  return isAdmin() || ['captain','coach','head_coach'].includes(membership.permission_role) || hasMatchCaptainAccess();
}
function isPhilosophyLead(){
  return !!workshop && workshop.philosophy_lead_user_id===session.user.id;
}
function canContributePhilosophy(){
  return !!myContributor;
}
function hasLockedHowWeBatForCurrentRound(){
  if(howWeBatDraft)return howWeBatDraft.status==='ready';
  if(workshop && workshop.status!=='published')return false;
  return howWeBatVersions.length>0;
}
// One persisted-state model drives the landing page, overview and route guards.
// A new workshop never borrows completion from the system players are still using.
function hasChosenWorkshopApproach(round=workshop,draft=howWeBatDraft){
  // Draft generation and contribution submission are not a club decision.
  // Preserve already-confirmed legacy work; new choices have an explicit marker.
  const activeRound=round?!!round.final_draft_ready:true;
  return activeRound&&(draft?.status==='ready'||!!round?.how_we_bat_selected_at);
}
function clubSetupProgress(state={club,workshop,howWeBatDraft,playerPlanStructureDraft,philosophyVersions,howWeBatVersions,playerPlanStructureVersions}){
  const c=state.club||{};
  const round=state.workshop||null;
  const hwbDraft=state.howWeBatDraft||null;
  const planDraft=state.playerPlanStructureDraft||null;
  const systemLive=publishedPlayerSystemReady(state);
  const published=systemLive&&(!round||round.status==='published');
  // Existing saved appearances and live systems retain their progress. Cricket
  // drafts alone never count as a confirmed club look for a first publication.
  const detailsReady=!!(c.branding_updated_at||c.logo_data_url||c.website_url||systemLive);
  // Older clubs can have a saved draft without a workshop row. An unfinished
  // current workshop cannot inherit a leftover draft from an earlier round.
  const workshopReady=published||hasChosenWorkshopApproach(round,hwbDraft);
  const howWeBatReady=workshopReady&&(published||hwbDraft?.status==='ready');
  const structureReady=howWeBatReady&&(published||planDraft?.status==='ready');
  const steps=[
    {key:'workshop',title:'Batting Philosophy Workshop',shortTitle:'Workshop',tab:'workshop',complete:workshopReady,owner:'Philosophy Lead and contributors',action:'Continue Batting Philosophy Workshop',description:'Choose a Philosophy Lead, gather the contributions you want and agree the approach your club will use.'},
    {key:'howwebat',title:'How We Bat',shortTitle:'How We Bat',tab:'howwebat',complete:howWeBatReady,owner:'Philosophy Lead',action:'Review How We Bat',description:'Review the club’s batting approach, check each format and confirm it for the season.'},
    {key:'structure',title:'Player Plan Structure',shortTitle:'Plan questions',tab:'plan',complete:structureReady,owner:'Philosophy Lead',action:'Review Player Plan questions',description:'Review the questions generated from How We Bat and confirm what players will complete.'},
    {key:'details',title:'Club look',shortTitle:'Club look',tab:'dashboard',complete:detailsReady,owner:'Club Admin',action:'Review club look',description:'Your batting work is ready. Add your club logo and colours, or keep the current look, before the final publication step. You can change the look later.'},
    {key:'publish',title:'Publish club setup',shortTitle:'Publish',tab:'plan',complete:published,owner:'Philosophy Lead',action:'Publish club setup',description:'Publish How We Bat and the Player Plan questions together. This opens Player Plans for registered players and queues their ready-to-start email.'}
  ];
  const firstIncomplete=steps.findIndex(step=>!step.complete);
  return {detailsReady,workshopReady,howWeBatReady,structureReady,published,systemLive,currentIndex:firstIncomplete<0?steps.length:firstIncomplete,steps};
}

function canUseClubHome(){
  return isAdmin()||isPhilosophyLead()||canContributePhilosophy()||canUsePlayersWorkspace();
}

function clubSetupUnavailableReason(tab){
  const p=clubSetupProgress();
  // Published reading remains available while a replacement round is prepared.
  if(tab==='howwebat'&&howWeBatVersions.length)return '';
  if(['howwebat','plan'].includes(tab)&&!p.workshopReady)return 'Complete Batting Philosophy Workshop first. The Philosophy Lead chooses the approach used to create How We Bat.';
  if(tab==='plan'&&!p.howWeBatReady)return 'Confirm How We Bat first. The Player Plan questions are built from that approach.';
  return '';
}

function canOpenClubTab(tab){
  if(productTrialWaiting()&&!['products','guide','club_settings','club_teams','permissions','messages','phone_app','assist','join_club'].includes(tab))return false;
  if(tab==='products')return !!(session&&membership&&club&&isAdmin());
  if(productTrialWaiting()&&!['products','guide','club_settings','club_teams','permissions','messages','phone_app','assist','join_club'].includes(tab))return false;
  if(tab==='products')return !!(session&&membership&&club&&isAdmin());
  if(productTrialWaiting()&&!['products','guide','club_settings','club_teams','permissions','messages','phone_app','assist','join_club'].includes(tab))return false;
  if(tab==='products')return !!(session&&membership&&club&&isAdmin());
  if(productTrialWaiting()&&!['products','guide','club_settings','club_teams','permissions','messages','phone_app','assist','join_club'].includes(tab))return false;
  if(tab==='products')return !!(session&&membership&&club&&isAdmin());
  if(tab==='club_teams')return !!(session&&membership&&club&&isAdmin());
  if(tab==='teams')return !!(session&&membership&&club);
  if(selectionsStandalone()&&!['teams','permissions','club_settings','messages','phone_app','guide','assist','join_club'].includes(tab))return false;
  if(['join_club','messages','phone_app','assist'].includes(tab))return !!(session&&membership&&club);
  if(tab==='dashboard')return canUseClubHome();
  if(['playerhome','innings'].includes(tab))return isPlayerUser();
  if(['permissions','groups','club_settings'].includes(tab))return !!(session&&membership&&club&&isAdmin());
  if(['players','feedback','training_preparation'].includes(tab))return canUsePlayersWorkspace();
  if(tab==='team_review')return canUseTeamReview();
  if(tab==='workshop_preview')return !!workshopPreview&&workshopPreview.clubId===club?.id&&workshopPreview.userId===session?.user?.id;
  if(tab==='workshop')return !clubSetupUnavailableReason(tab)&&(isAdmin()||isPhilosophyLead()||canContributePhilosophy());
  if(['identity','dimensions','formats','preview','submitted_response'].includes(tab))return !clubSetupUnavailableReason(tab)&&(isPhilosophyLead()||canContributePhilosophy());
  if(tab==='plan')return !clubSetupUnavailableReason(tab)&&(isAdmin()||isPhilosophyLead());
  if(tab==='howwebat')return howWeBatVersions.length>0||(!clubSetupUnavailableReason(tab)&&(isAdmin()||isPhilosophyLead()));
  if(tab==='myplan')return isPlayerUser();
  if(tab==='make_your_call')return !!(session&&membership&&club&&(isAdmin()||selectionAccess?.key===selectionsScopeKey()&&!selectionAccess.error&&selectionAccess.predictions_enabled===true));
  if(tab==='conversations')return !!(session&&membership&&club);
  if(tab==='howwetrain')return true;
  return tab==='guide';
}

function canActOnClubSetupStep(step){
  if(!step)return false;
  if(step.key==='details')return isAdmin();
  if(step.key==='workshop')return isAdmin()||isPhilosophyLead()||canContributePhilosophy();
  return isPhilosophyLead();
}

