function renderTrainMyPlan(raw,formats){
  const coreCards=coreTrainingCards(raw);
  const coreProgress=sectionProgress('core',raw);
  const coreReady=coreProgress.complete;
  const formatBlocks=formats.map(format=>{
    const cards=formatTrainingCards(raw,format);
    const progress=sectionProgress(format,raw);
    const ready=coreReady&&progress.complete;
    return `<div class="train-my-format">
      <div class="train-my-format-head"><div><div class="section-label">${esc(formatLabel(format))}</div><h3>Train my ${esc(formatLabel(format))} plan</h3></div></div>
      ${ready
        ?(cards.length?`<div class="train-personal-grid">${cards.map(c=>`<article class="train-personal-card"><small>${esc(c.label)}</small><strong>${esc(c.value)}</strong><p>${esc(c.cue)}</p></article>`).join('')}</div>`:`<div class="notice">Your ${esc(formatLabel(format))} plan is complete, but there are no training cues to display yet.</div>`)
        :`<div class="train-plan-gate"><div><strong>Complete your ${esc(formatLabel(format))} Player Plan to unlock targeted ${esc(formatLabel(format))} training.</strong><span>How We Train uses your Core batting identity plus your ${esc(formatLabel(format))} answers. Until both are complete, this section stays general rather than pretending to be personalised.</span></div><button class="btn secondary" data-go="myplan">Complete My Player Plan</button></div>`}
    </div>`;
  }).join('');

  return `<section class="card train-my-plan">
    <div class="train-my-plan-head">
      <div><div class="section-label">Train My Plan</div><h2>Practise the game you have actually chosen.</h2><div class="help">Practise executing your chosen shots, then mix the deliveries so you must recognise the right ball and commit. Train the decision as well as the shot.</div></div>
      <button class="btn ghost" data-go="myplan">Open My Player Plan</button>
    </div>
    ${coreReady
      ?(coreCards.length?`<div class="train-personal-grid core">${coreCards.map(c=>`<article class="train-personal-card"><small>${esc(c.label)}</small><h3>${esc(c.title)}</h3><strong>${esc(c.value)}</strong><p>${esc(c.cue)}</p></article>`).join('')}</div>`:`<div class="notice">Your Core Player Plan is complete. Complete a format section below to unlock its targeted training plan.</div>`)
      :`<div class="train-plan-gate core"><div><strong>Start with your Core Player Plan.</strong><span>Your training plan needs your batting identity, trusted options, Danger and Reset before format-specific practice can be genuinely targeted.</span></div><button class="btn secondary" data-go="myplan">Complete My Player Plan</button></div>`}
    ${formatBlocks}
  </section>`;
}

function coachingReviewDateDefault(){
  const date=new Date();date.setDate(date.getDate()+7);
  return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
}
// Shared conversation request and optional video controls.
function normaliseCoachingYouTubeUrl(raw){
  const text=String(raw||'').trim();if(!text)return '';
  if(text.length>2048||/[\s\x00-\x1f\x7f]/.test(text))throw new Error('Paste a valid YouTube video link.');
  let videoId,query='',match=text.match(/^https?:\/\/(?:www\.|m\.)?youtube\.com\/watch\?([^#]*)(?:#.*)?$/i);
  if(match){query=match[1];videoId=query.match(/(?:^|&)v=([A-Za-z0-9_-]{11})(?:&|$)/)?.[1];}
  else{
    match=text.match(/^https?:\/\/(?:www\.)?youtu\.be\/([A-Za-z0-9_-]{11})\/?(?:\?([^#]*))?(?:#.*)?$/i)||text.match(/^https?:\/\/(?:www\.|m\.)?youtube\.com\/(?:shorts|live|embed)\/([A-Za-z0-9_-]{11})\/?(?:\?([^#]*))?(?:#.*)?$/i);
    if(match){videoId=match[1];query=match[2]||'';}
  }
  if(!videoId)throw new Error('Use a YouTube watch, share, Shorts or live-video link.');
  const stamp=query.match(/(?:^|&)(?:t|start)=([^&]*)/)?.[1]??text.match(/#t=([^&]*)$/)?.[1];
  if(stamp!==undefined&&!/^([0-9]{1,7}|[0-9]{1,4}h([0-9]{1,4}m)?([0-9]{1,4}s)?|[0-9]{1,4}m([0-9]{1,4}s)?|[0-9]{1,7}s)$/.test(stamp))throw new Error('Use YouTube Share > Start at for a valid video start time.');
  return `https://www.youtube.com/watch?v=${videoId}${stamp===undefined?'':`&t=${stamp}`}`;
}
function coachingVideoFields(prefix,video=null,{playerRequest=false}={}){
  const example=playerRequest?'my footwork against the short ball':'let’s review your footwork against the short ball';
  return `<fieldset style="border:1px solid #dce1ed;border-radius:12px;padding:16px;margin:16px 0"><legend>YouTube link (optional)</legend><p class="help">Upload your video to YouTube first, then paste its link here. Club Batting does not upload or store video files.</p>
    <div class="field"><label for="${prefix}VideoUrl">YouTube video link</label><input type="url" id="${prefix}VideoUrl" maxlength="2048" placeholder="https://youtu.be/…" value="${esc(video?.url||'')}"><p class="help">Use YouTube’s Share link. “Start at” can take someone straight to the moment you want to discuss.</p></div>
    <div class="field"><label for="${prefix}VideoNote">What should we look at? (optional)</label><textarea id="${prefix}VideoNote" maxlength="500" rows="2" placeholder="e.g. Watch 0:35–0:45 — ${esc(example)}">${esc(video?.note||'')}</textarea></div>
<details style="margin:12px 0"><summary>How do I share just one ball or shot?</summary>
      <ol><li><strong>For a separate short video:</strong> trim a copy of your own footage on your phone or computer. Include a few seconds before the ball and just after the shot. Upload that short video to YouTube, choose Unlisted, then copy its Share link.</li>
      <li><strong>For a moment in a longer YouTube video:</strong> pause just before the ball, choose Share, turn on Start at (or the displayed time on your phone), then Copy link. Paste it above.</li>
      <li><strong>Tell us what to watch:</strong> for example, “Watch 2:14–2:24 — ${esc(example)}.”</li></ol>
      <p class="help">A start-time link starts at that moment; it does not stop after the shot or hide the rest of the video. To share only that ball, use a separately trimmed video. If Start at is unavailable, paste the normal link and put the start and finish times in your note.</p>
    </details>
    <p class="help">The video opens on YouTube. An unlisted video can be viewed and shared by anyone with its link. Only share footage you have permission to share.</p>
  </fieldset>`;
}
function coachingVideoValues(prefix){
  const video_url=normaliseCoachingYouTubeUrl(val(`${prefix}VideoUrl`)),video_note=val(`${prefix}VideoNote`);
  if(video_note&&!video_url)throw new Error('Add the YouTube link for your video note, or leave both blank.');
  return {video_url,video_note};
}
function renderCoachingVideo(video){
  if(!video?.url)return '';
  let url;try{url=normaliseCoachingYouTubeUrl(video.url);}catch{return '';}
  return `<div class="notice compact coaching-video" style="margin:12px 0"><strong>Video to discuss</strong>${video.note?`<p>${esc(video.note)}</p>`:''}<p><a class="btn ghost" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Open video on YouTube ↗</a></p><small>Opens in a new tab. Keep the conversation and agreed next steps here.</small></div>`;
}
function conversationRequestDetails(a){
  if(!a.is_player_request)return '';
  const who=a.preferred_user_id&&a.preferred_available!==false?a.preferred_name||'Club member':'Any coach';
  return `<div class="notice compact"><strong>${a.is_own_request?'Your request':`Request from ${esc(a.player_name||a.recorded_by_name||'a player')}`}</strong><p>Preferred person: ${esc(who)}${a.request_state==='accepted'?' · Picked up':a.preferred_user_id&&a.preferred_available!==false?' · Awaiting response':' · Open to the authorised coaching team'}</p></div>`;
}
function conversationRecipientButtons(a){
  if(!a.is_player_request||!a.is_preferred_person||a.status!=='open')return '';
  return `<div class="btnrow" style="margin:12px 0">${a.request_state==='pending'?`<button class="btn secondary" data-respond-coach-request="${esc(a.id)}" data-response="accept">I can help</button>`:''}<button class="btn ghost" data-respond-coach-request="${esc(a.id)}" data-response="unavailable">I’m unavailable</button><span role="status" data-request-response-status="${esc(a.id)}"></span></div>`;
}
function bindConversationRecipientControls(feedback,onSaved){
  document.querySelectorAll('[data-respond-coach-request]').forEach(button=>{
    let requestId=null;
    button.onclick=async()=>{
      if(coachingActionSavePending||!confirmLeaveFeedbackEntry())return;
      const action=feedback.coaching_actions.find(a=>a.id===button.dataset.respondCoachRequest&&a.is_preferred_person&&a.status==='open');if(!action)return;
      const response=button.dataset.response;
      if(response==='unavailable'&&!confirm('Let the player know you’re unavailable? This stays open for the authorised coaching team.'))return;
      const status=document.querySelector(`[data-request-response-status="${action.id}"]`);
      const targetClub=club.id,targetUser=session.user.id;
      requestId ||= globalThis.crypto.randomUUID();coachingActionSavePending=true;button.disabled=true;status.textContent='Saving…';
      try{
        const {error}=await supabase.rpc('respond_to_coach_request',{p_action_id:action.id,p_expected_revision:action.revision,p_request_id:requestId,p_response:response});if(error)throw error;
        coachingActionSavePending=false;status.textContent='Saved.';
        if(club?.id!==targetClub||session?.user?.id!==targetUser)return;
        await onSaved();await refreshMyCoachingUpdates();
      }catch(error){status.textContent=error?.message||'Could not confirm the save. Try again.';button.disabled=false;}
      finally{coachingActionSavePending=false;}
    };
  });
}
let conversationPageSequence=0;
async function openCoachConversationRequest(){
  if(!myPlayer||!isPlayerUser()||!await saveClubEditsBeforeNavigation()||!confirmLeaveFeedbackEntry())return;
  currentTab='conversations';await renderTab();
  if(currentTab==='conversations')await renderCoachConversationRequestForm();
}
async function renderCoachConversationRequestForm(){
  const host=document.getElementById('coachRequestFormHost');if(!host||!myPlayer||!isPlayerUser()||!confirmLeaveFeedbackEntry())return;
  const clubId=club.id,userId=session.user.id,playerId=myPlayer.id;
  const current=()=>club?.id===clubId&&session?.user?.id===userId&&myPlayer?.id===playerId&&document.getElementById('coachRequestFormHost')===host&&currentTab==='conversations';
  host.innerHTML='<p role="status">Loading people in your club…</p>';
  let people;
  try{
    const {data,error}=await supabase.rpc('get_conversation_people',{p_club_id:clubId});if(error)throw error;
    if(!current())return;people=Array.isArray(data?.people)?data.people:[];
  }catch(error){if(current()){host.innerHTML=`<div class="notice">The club’s people could not load. <button class="btn ghost" id="retryConversationPeople">Try again</button></div>`;document.getElementById('retryConversationPeople').onclick=renderCoachConversationRequestForm;}return;}
  host.innerHTML=`<section class="card development-entry-form" id="coachRequestForm"><h2>Request a Coach Conversation</h2>
        <div class="field"><label for="coachRequestMessage">What would you like to discuss?</label><textarea id="coachRequestMessage" rows="3" maxlength="500" placeholder="A short explanation is enough."></textarea></div>
    <div class="field"><label for="coachRequestSearch">Find someone in your club (optional)</label><input type="search" id="coachRequestSearch" placeholder="Search by name"></div>
    <div class="field"><label for="coachRequestPerson">Who would you like to speak with?</label><select id="coachRequestPerson"></select><p class="help" id="coachRequestPeopleStatus"></p></div>
    ${coachingVideoFields('coachRequest',null,{playerRequest:true})}
    <p class="help">Your chosen person and authorised coaching staff can read this. A teammate sees only this conversation. Choose Any coach if you have no preference.</p>
    <div class="btnrow"><button class="btn" id="saveCoachRequest">Request conversation</button><button class="btn ghost" id="cancelCoachRequest">Cancel</button><span id="coachRequestStatus" role="status"></span></div>
  </section>`;
  const picker=document.getElementById('coachRequestPerson');
  const drawPeople=()=>{
    const selected=picker.value||'',query=val('coachRequestSearch').toLowerCase();
    const matches=people.filter(p=>p.user_id===selected||!query||`${p.display_name} ${(p.coaching_titles||[]).join(' ')}`.toLowerCase().includes(query));
    picker.innerHTML=conversationPeopleOptions(people,selected,query);picker.value=selected;
    document.getElementById('coachRequestPeopleStatus').textContent=query?`${picker.options.length-1} people shown. Your selected person stays selected while searching.`:'';
  };
  drawPeople();document.getElementById('coachRequestSearch').oninput=drawPeople;
  const form=document.getElementById('coachRequestForm'),saveButton=form.querySelector('#saveCoachRequest'),saveLabel=saveButton.textContent;captureFeedbackEntryBaseline();form.scrollIntoView({behavior:'smooth',block:'start'});
  document.getElementById('cancelCoachRequest').onclick=()=>{if(confirmLeaveFeedbackEntry())host.innerHTML='';};
  let requestId=null,requestPayload=null;
  document.getElementById('saveCoachRequest').onclick=async()=>{
    if(coachingActionSavePending||!current())return;
    const status=document.getElementById('coachRequestStatus');
    let video;try{video=coachingVideoValues('coachRequest');}catch(error){status.textContent=error.message;return;}
    const message=val('coachRequestMessage');if(!message){status.textContent='Say what you would like to discuss.';return;}
    const args={p_club_id:clubId,p_message:message,p_preferred_user_id:picker.value||null,p_video_url:video.video_url,p_video_note:video.video_note};
    const payload=JSON.stringify(args);if(payload!==requestPayload){requestId=globalThis.crypto.randomUUID();requestPayload=payload;}
    coachingActionSavePending=true;const restore=freezeCoachingForm(form);status.textContent='Sending request…';saveButton.textContent='Sending…';saveButton.setAttribute('aria-busy','true');
    try{
      const {error}=await supabase.rpc('request_my_coach_conversation',{...args,p_request_id:requestId});if(error)throw error;
      feedbackEntryBaselines.set(form,feedbackEntryValues(form));status.textContent='Requested.';saveButton.textContent='Requested ✓';coachingActionSavePending=false;
      if(!current())return;
      try{await renderCoachConversations();await refreshMyCoachingUpdates();}catch{status.textContent='Request saved. Reload to see the latest conversation.';}
    }catch(error){status.textContent=error?.message||'Could not confirm the save. Your request is still here; try again.';saveButton.textContent=saveLabel;restore();}
    finally{coachingActionSavePending=false;saveButton.removeAttribute('aria-busy');}
  };
}
async function renderCoachConversations(){
  const page=document.getElementById('page'),clubId=club.id,userId=session.user.id,sequence=++conversationPageSequence;
  const current=()=>currentTab==='conversations'&&club?.id===clubId&&session?.user?.id===userId&&conversationPageSequence===sequence;
  page.innerHTML='<p class="splash">Loading Coach Conversations…</p>';
  try{
    const [inbox,own]=await Promise.all([supabase.rpc('get_my_coach_conversations',{p_club_id:clubId}),myPlayer&&isPlayerUser()?loadDevelopmentFeedback(myPlayer.id).catch(()=>null):Promise.resolve(null)]);
    if(!current())return;if(inbox.error)throw inbox.error;
    if(coachingUpdateScopeMatches()){
      myCoachingUpdates={...myCoachingUpdates,openRequestCount:(inbox.data?.actions||[]).filter(a=>a.is_player_request&&a.status==='open').length};
      renderCoachingUpdatesMenu();
    }
    const feedback={matches:own?.matches||[],training_observations:own?.training_observations||[],coaching_actions:inbox.data?.actions||[]};
    page.innerHTML=`<section class="card"><div class="section-label">Your club</div><h1>Coach Conversations</h1><p>Your conversations and requests to you appear here.${canUsePlayersWorkspace()?' Player requests also appear in the Players coaching filter.':''}</p><div class="btnrow">${myPlayer&&isPlayerUser()?'<button class="btn" id="newCoachRequest">Request a Coach Conversation</button>':''}<button class="btn ghost" id="refreshCoachConversations">Refresh conversations</button></div></section><div id="coachRequestFormHost"></div>${renderCoachingActions(feedback,{playerMode:true,includeObservations:true})}`;
    document.getElementById('newCoachRequest')?.addEventListener('click',renderCoachConversationRequestForm);
    document.getElementById('refreshCoachConversations').onclick=()=>{if(confirmLeaveFeedbackEntry())return renderCoachConversations();};
    bindCoachingActionControls(feedback,renderCoachConversations);
    document.querySelectorAll('[data-edit-my-reflection]').forEach(button=>button.onclick=()=>openMyInnings({matchId:button.dataset.editMyReflection,edit:true}));
    await revealPendingCoachingUpdate();watchVisibleCoachingNotes();
  }catch(error){if(current())page.innerHTML=`<section class="card notice"><h1>Coach Conversations</h1><p>${esc(error?.message||'Could not load conversations.')}</p><button class="btn ghost" id="retryCoachConversations">Try again</button></section>`;document.getElementById('retryCoachConversations')?.addEventListener('click',renderCoachConversations);}
}

let coachingActionSavePending=false;

function coachingSignalAction(signal,actions=[]){
  const coach=latestCoachFeedback(signal.match);
  const manualMatch=String(signal.key||'').startsWith('coach_note:match:')?signal.key.slice('coach_note:match:'.length):null;
  const manualTraining=String(signal.key||'').startsWith('coach_note:training:')?signal.key.slice('coach_note:training:'.length):null;
  return actions.find(a=>(!a.player_id||a.player_id===signal.player?.id)&&(
    (a.signal_key===signal.key&&(!a.source_at||!signal.sourceAt||Date.parse(a.source_at)>=Date.parse(signal.sourceAt)))||
    (a.match_feedback_id&&a.match_feedback_id===(manualMatch||coach?.id))||
    (a.training_observation_id&&a.training_observation_id===(manualTraining||signal.observation?.id))
  ))||null;
}
function coachingConversationItems(actions=[],signals=[]){
  const items=new Map();
  for(const action of actions){
    if(action.status&&action.status!=='open')continue;
    items.set(`action:${action.id}`,{key:`action:${action.id}`,playerId:action.player_id,action,signals:[],reviewOn:action.review_on||null});
  }
  for(const signal of signals){
    const linked=coachingSignalAction(signal,actions);
    if(linked&&linked.status&&linked.status!=='open')continue;
    const key=linked?`action:${linked.id}`:`signal:${signal.player.id}:${signal.key}`;
    if(!items.has(key))items.set(key,{key,playerId:signal.player.id,action:null,signals:[],reviewOn:null});
    const item=items.get(key);if(!item.signals.some(s=>s.key===signal.key))item.signals.push(signal);
  }
  return [...items.values()].sort((a,b)=>String(a.reviewOn||'9999').localeCompare(String(b.reviewOn||'9999'))||a.key.localeCompare(b.key));
}
function workspaceCoachConversations(playerId=null){
  const accessible=new Set((playersWorkspaceData?.players||playersWorkspaceFeedbackData?.players||[]).map(p=>p.id));
  return coachingConversationItems(playersWorkspaceFeedbackData?.action_alerts||[],workspaceDiscussionSignals())
    .filter(x=>accessible.has(x.playerId)&&(!playerId||x.playerId===playerId));
}
function renderConversationSignal(signal){
  return `<article class="training-observation-card" data-coach-signal-card="${esc(signal.key)}" style="margin-top:12px">
    <div class="section-label">Conversation needed</div><h3>${esc(signal.title)}</h3><p>${esc(signal.summary)}</p><p class="help">${esc(signal.suggestion)}</p>
    ${signal.match?`<details><summary>View the innings evidence</summary>${renderDevelopmentMatchCard(signal.match)}</details>`:''}
    ${signal.player?.can_edit?`<div class="btnrow"><button class="btn secondary" data-player-discussion="${esc(signal.key)}" data-outcome="no_action">Add note / mark Discussed or Actioned</button><button class="btn ghost" data-player-discussion="${esc(signal.key)}" data-outcome="adjust_training">Agree a next step</button></div>`:''}
    <div data-player-discussion-slot="${esc(signal.key)}"></div></article>`;
}

// BEGIN OUTSIDE PLAN REVIEW — structured preparation context in existing conversations.
function outsidePlanReviewContext(action){
  const value=action?.preparation_review;
  if(!value||value.kind!=='outside_plan_shots'||!Number.isInteger(value.shot_count)||value.shot_count<0||!Number.isInteger(value.no_training_count)||value.no_training_count<0||!Array.isArray(value.matchups))return null;
  return value;
}
function renderOutsidePlanReview(action,{compact=false,snapshot=false}={}){
  const context=outsidePlanReviewContext(action);if(!context)return '';
  const count=context.shot_count,noTraining=Number.isInteger(context.no_training_count)?Math.max(0,context.no_training_count):0;
  const concern=count>1?'multiple':count&&noTraining?'no_training':count?'outside_plan':'clear';
  const background=concern==='multiple'?'#fff0ec':concern==='no_training'?'#fff4d6':'#f4f5ff';
  const border=concern==='multiple'?'#a64225':concern==='no_training'?'#9b6600':'#475596';
  const title=count>1?'Several outside-plan shots':count?'Outside-plan shot':'No outside-plan shots in this saved context';
  const badges=count?`<span style="font-weight:700">${esc(title)} · ${count}</span>${noTraining?`<span style="display:block;margin-top:4px">No training focus selected · ${noTraining} ${noTraining===1?'shot':'shots'}</span>`:'<span style="display:block;margin-top:4px">Training focus selected</span>'}`:`<strong>${esc(title)}</strong>`;
  if(compact)return `<div data-outside-plan-review="compact" data-review-concern="${concern}" style="border-left:4px solid ${border};background:${background};border-radius:6px;padding:9px 10px;margin:8px 0;font-size:13px">${badges}</div>`;
  const meta=[context.match_date?formatDateShort(context.match_date):'',context.opposition||'',context.format_key?formatLabel(context.format_key):''].filter(Boolean);
  const matchups=context.matchups.filter(m=>m&&Array.isArray(m.shots)).map(m=>`<section style="margin-top:12px"><strong>${esc(m.bowler||'Bowler not named')}</strong><p class="help" style="margin:4px 0">${m.training_focus===true?'Training focus selected for this match-up':'No training focus selected for this match-up'}</p><ul style="margin:8px 0;padding-left:20px">${m.shots.filter(s=>s&&typeof s.shot==='string').map(s=>`<li style="margin:8px 0;overflow-wrap:anywhere"><strong>${esc(s.shot)}</strong><p style="margin:4px 0;white-space:pre-wrap">${typeof s.reason==='string'&&s.reason.trim()?`Player’s reason: ${esc(s.reason)}`:'No reason added.'}</p></li>`).join('')}</ul></section>`).join('');
  return `<section data-outside-plan-review="${snapshot?'snapshot':'current'}" data-review-concern="${concern}" style="border-left:4px solid ${border};background:${background};border-radius:8px;padding:12px 14px;margin:12px 0;overflow-wrap:anywhere"><h4>${snapshot?'Scoring context at this update':'Scoring context to discuss'}</h4>${badges}${meta.length?`<p class="help" style="margin:8px 0">${meta.map(esc).join(' · ')}</p>`:''}${count?`<p style="margin:8px 0">${count>1?'Check these scoring choices against the Player Plan and agree the approach together.':noTraining?'Read the player’s reason and discuss the shot and preparation.':'Discuss how this shot fits the player’s plan and practice.'}</p>${matchups}<p class="help">A training tick records a choice here, not completed practice. No tick does not mean the shot is unpractised; the player may practise elsewhere.</p>`:`<p class="help">Removing outside-plan shots does not automatically close this conversation.</p>`}</section>`;
}
// END OUTSIDE PLAN REVIEW

// BEGIN CONVERSATION DETAILS V66
// A conversation shows its source straight away. Wider innings history is separate.
function renderConversationObservation(action,match,note,training,{playerMode,staffCanEdit}){
  const hidden=playerMode&&match&&!match.player_reflection&&note?.plan_related!==false&&!(note?.batting_to_plan==='no_plan'&&note?.reflection_required===false);
  if(match){
    const meta=[matchMetaLine(match),Number(match.innings_number||1)>1?'Innings '+match.innings_number:''].filter(Boolean).join(' · ');
    const assessment=note?.batting_to_plan==='no_plan'?'Has no Player Plan':note?.plan_related!==false?[
      note?.batting_to_plan?'Batted to plan: '+(PLAN_ALIGNMENT_LABELS[note.batting_to_plan]||'—'):'',
      DISMISSAL_CLASSIFICATION_LABELS[note?.dismissal_classification]||'',
      DEVELOPMENT_ISSUE_LABELS[note?.main_issue]||''
    ].filter(Boolean).join(' · '):'';
    return `<div class="conversation-observation" data-coach-feedback-id="${esc(note?.id||'')}" data-coaching-note-updated-at="${esc(note?.updated_at||note?.created_at||'')}">
      <h3>Match observation <span>· ${esc(note?.author_name||'Coach / Captain')}</span></h3>
      <p class="conversation-match-meta">${esc(meta)}</p>
      ${hidden?'<p class="notice">Add your own innings reflection to see this coach’s observation.</p>':`
        ${note?.note?`<p class="conversation-observation-comment">${esc(note.note)}</p>`:''}
        ${note?.innings_note||match.dismissal_summary?`<p class="conversation-context"><strong>Dismissal / innings:</strong> ${esc(note?.innings_note||match.dismissal_summary)}</p>`:''}
        ${assessment?`<p class="conversation-context">${esc(assessment)}</p>`:''}
        ${note?.next_training_focus?`<p class="conversation-context"><strong>Train next:</strong> ${esc(note.next_training_focus)}</p>`:''}
        ${renderCoachingVideo(action.video)}
      `}
      <div class="btnrow conversation-source-links"><button type="button" class="btn ghost" data-staff-innings-source="${esc(match.id)}">View innings</button>${staffCanEdit&&note?.author_user_id===session?.user?.id?`<button type="button" class="btn ghost" data-edit-coach-feedback="${esc(note.id)}" data-edit-match="${esc(match.id)}">Edit my observation</button>`:''}</div>
    </div>`;
  }
  if(training)return `<div class="conversation-observation" data-training-observation-id="${esc(training.id)}" data-coaching-note-updated-at="${esc(training.updated_at||training.created_at||'')}">
    <h3>Training observation <span>· ${esc(training.observer_name||'Coach / Captain')}</span></h3>
    <p class="conversation-match-meta">${esc(formatDateShort(training.observed_on))} · ${esc((training.format_keys||[]).map(formatLabel).join(' + ')||'Core')}</p>
    ${training.note?`<p class="conversation-observation-comment">${esc(training.note)}</p>`:''}
    ${training.plan_related!==false?`<p class="conversation-context">Training to plan: ${esc(PLAN_ALIGNMENT_LABELS[training.training_to_plan]||'—')}${TRAINING_OBSERVATION_LABELS[training.observation_type]?` · ${esc(TRAINING_OBSERVATION_LABELS[training.observation_type])}`:''}</p>`:''}
    ${training.next_training_focus?`<p class="conversation-context"><strong>Train next:</strong> ${esc(training.next_training_focus)}</p>`:''}
    ${renderCoachingVideo(action.video)}
    ${staffCanEdit&&training.observer_user_id===session?.user?.id?`<button type="button" class="btn ghost" data-edit-training-observation="${esc(training.id)}">Edit my observation</button>`:''}
  </div>`;
  return '';
}
