  document.getElementById('prepDate').addEventListener('change',()=>syncPreparationCall(record));
  document.getElementById('prepStatus').onchange=()=>{refreshPreparationScoringChoices(form);syncPreparationCall(record);};
  syncPreparationCall(record);
