async function mountMatchTrainingFocus(host,{playerId=myPlayer?.id,isOwner=true,compact=false,canStillView=()=>true}={}){
  matchTrainingFocusMount?.dispose();
  if(!host||!playerId)return;
  const hasAccess=()=>canStillView()&&(isOwner?myPlayer?.id===playerId&&isPlayerUser():canUsePlayersWorkspace());
  if(!hasAccess()){host.innerHTML='';return;}
  const clubId=club?.id,userId=session?.user?.id,tab=currentTab;
  let records=null,errorText='',sequence=0,timer=null,disposed=false;
  const current=()=>!disposed&&club?.id===clubId&&session?.user?.id===userId&&currentTab===tab&&document.getElementById(host.id)===host&&hasAccess();
  const dispose=()=>{disposed=true;++sequence;clearTimeout(timer);window.removeEventListener('focus',foreground);document.removeEventListener?.('visibilitychange',foreground);if(document.getElementById(host.id)===host)host.innerHTML='';if(matchTrainingFocusMount?.host===host)matchTrainingFocusMount=null;};
  const render=()=>{
    if(!current()){dispose();return;}
    const body=records?renderMatchTrainingFocus(records,{isOwner,compact}):'';
    host.innerHTML=body+(errorText?`<section class="card notice" role="status"><strong>Match training focuses could not be refreshed.</strong><p>Saved match preparation is unchanged.${records?' The last loaded choices are shown above if their match dates are still current.':''}</p><p class="help">${esc(errorText)}</p><button type="button" class="btn secondary" data-match-training-retry>Try again</button></section>`:records?'':'<section class="card" role="status"><p>Loading match training focuses…</p></section>');
    host.querySelectorAll('[data-match-training-view]').forEach(button=>button.onclick=()=>openMyInnings({matchId:button.dataset.matchTrainingView}));
    host.querySelector('[data-match-training-prepare]')?.addEventListener('click',()=>openMyInnings({prepare:true}));
    host.querySelector('[data-match-training-retry]')?.addEventListener('click',load);
  };
  const schedule=()=>{
    clearTimeout(timer);if(!current()){dispose();return;}
    const now=new Date(),next=new Date(now.getFullYear(),now.getMonth(),now.getDate()+1);
    timer=setTimeout(()=>{if(!current()){dispose();return;}render();schedule();},Math.max(1,next.getTime()-now.getTime()+50));
  };
  const load=async()=>{
    if(!current()){dispose();return;}
    const request=++sequence;errorText='';render();
    try{
      const {data,error}=await supabase.rpc(isOwner?'get_my_match_preparations':'get_player_match_training_focus',isOwner?{p_club_id:clubId}:{p_player_id:playerId});
      if(!current()){dispose();return;}if(request!==sequence)return;
      if(error)throw error;
      if(data?.player_id!==playerId||!Array.isArray(data?.preparations))throw new Error('Saved match training focuses could not be confirmed.');
      records=data.preparations;
    }catch(error){if(!current()){dispose();return;}if(request!==sequence)return;if(!isOwner||String(error?.code||'')==='42501')records=null;errorText=error?.message||'Check your connection and try again.';}
    if(current()&&request===sequence){render();schedule();}
  };
  function foreground(){if(document.visibilityState==='hidden'||document.hidden)return;if(!current()){dispose();return;}render();schedule();return load();}
  matchTrainingFocusMount={host,dispose};
  window.addEventListener('focus',foreground);document.addEventListener('visibilitychange',foreground);
  schedule();await load();
}
