    matchReviewImportState().dirty=false;matchReviewImportState().selected={};const saved=pending.values.rows.map(row=>row.player_id);for(const id of saved)delete s.drafts[id];s.saved=[...new Set([...s.saved,...saved])];s.fixtureId=data.review?.fixture_id||s.fixtureId;s.opposition=data.review?.opposition||s.opposition;s.loaded=teamReviewIdentity(s);s.sessionId=data.review_id||s.sessionId;s.sessionRevision=data.revision??s.sessionRevision;s.sessionGroupScope=data.review?.group_scope||pending.values.group_scope;s.sessionGroupId=data.review?.group_id??pending.values.group_id??null;s.reviewCanEdit=data.review?.can_edit!==false;s.reviewCanDelete=!!data.review?.can_delete;s.editReview=s.reviewCanEdit;s.removed=[];s.pending=null;s.saving=false;s.message=`Saved match review · ${saved.length} ${saved.length===1?'observation updated':'observations updated'}${requestedRemoved.length?` · ${requestedRemoved.length} removed`:''}${submittedScores.length?` · ${submittedScores.length} scores confirmed`:''}.`;
    // A confirmed write stays confirmed even if the follow-up read fails.
    try{const {data,error:readError}=await (s.sessionId?supabase.rpc('get_shared_team_review',{p_club_id:club.id,p_review_id:s.sessionId}):supabase.rpc('get_team_match_review',{p_club_id:club.id,p_match_date:s.loaded.match_date,p_format_key:s.loaded.format_key,p_opposition:s.loaded.opposition,p_innings_number:s.loaded.innings_number,p_group_id:null}));if(readError)throw readError;if(ensureTeamReviewState().scope!==scope)return;teamReviewReconcile(data);if(data.review){s.sessionRevision=data.review.revision;s.sessionGroupScope=data.review.group_scope;s.sessionGroupId=data.review.group_id||null;s.group=data.review.group_scope==='legacy'?'__legacy__':data.review.group_scope==='unassigned'?'__unassigned__':data.review.group_id||'__all__';s.saved=data.players.filter(p=>p.included_in_review).map(p=>p.player_id);}}catch(error){if(ensureTeamReviewState().scope!==scope)return;teamReviewCache=null;s.message+=' Saved successfully; reload current observations to see the updated rows.';}
