function wirePreparationScoringAdoption(form){
  form.querySelectorAll('[data-prep-matchup]').forEach(card=>{
    const button=card.querySelector('[data-prep-use-shot]'),input=card.querySelector('[data-prep-new-shot]');if(!button||!input)return;
    const syncAdd=()=>{const empty=!String(input.value||'').trim();button.hidden=empty;button.disabled=empty||coachingActionSavePending;};
    input.oninput=syncAdd;syncAdd();
    button.onclick=()=>{
      if(coachingActionSavePending||document.getElementById('myReflectionForm')!==form)return;
      const shot=String(input.value||'').trim(),status=form.querySelector('#myReflectionStatus');
      if(!syncPreparationEarlierNote(card)){status.textContent='Shorten the earlier scoring note before adding another shot.';return;}
      if(!shot){syncAdd();return;}
      if(shot.length>80||/[\r\n]/.test(shot)){status.textContent='Add one short shot name, up to 80 characters.';input.focus();return;}
      const extras=preparationExtraShots(card),existing=extras.find(s=>scoringShotKey(s)===scoringShotKey(shot)),label=existing||shot;
      if(!existing&&extras.length>=8){status.textContent='Use at most eight additional shots in one match-up.';return;}
      const chosen=card.querySelector('[data-prep-field="options"]'),next=preparationShotSelected(chosen.value,label)?chosen.value:preparationToggleExtraShot(chosen.value,label);
      if(next.length>240){status.textContent='Keep selected scoring options within 240 characters. Remove an option before adding another.';return;}
      if(!existing){extras.push(shot);card.querySelector('[data-prep-extra-shots]').value=JSON.stringify(extras);}
      chosen.value=next;input.value='';syncAdd();status.textContent='';refreshPreparationScoringChoices(form);
      const details=input.closest('details');if(details)details.open=false;
      const added=card.querySelector('[data-prep-draft-status]');if(added)added.textContent=label+' added to this draft. Changes save with Save preparation.';
      revealPreparationAddedShot(card,label,form);
    };
    input.onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();button.onclick();}};
  });
}
async function persistPreparationShot(shot,current){
  await playerPlanSaveQueue;
  if(!current())throw new Error('The player account changed. Reopen this preparation before trying again.');
  if(localRaw||playerPlanAutosaveTimer){if(await savePlayerPlanProgressSilently()===false)throw new Error('Your earlier Player Plan changes could not save. Retry those changes before adding this shot.');}
  if(!current())throw new Error('The player account changed. Reopen this preparation before trying again.');
  const playerId=myPlayer.id;
  const task=playerPlanSaveQueue.then(async()=>{
    for(let attempt=0;attempt<2;attempt++){
      if(!current())throw new Error('The player account changed. Reopen this preparation before trying again.');
      if(!preparationAdoptionCoreQuestion())throw new Error('The current Player Plan no longer offers this Core choice. Open My Player Plan to review it.');
      const catalogue=await supabase.from('player_plan_structure_versions').select('snapshot,philosophy_version').eq('club_id',club.id).order('philosophy_version',{ascending:false}).limit(1).maybeSingle();
      if(catalogue.error)throw catalogue.error;
      if(!current())throw new Error('The player account changed. Reopen this preparation before trying again.');
      if(!catalogue.data?.snapshot||JSON.stringify(catalogue.data.snapshot)!==JSON.stringify(playerPlanStructureVersions?.[0]?.snapshot))throw new Error('The club’s Player Plan questions changed. Save this preparation, then refresh before adding the shot.');
      const latest=await supabase.from('player_plan_workflows').select().eq('player_id',playerId).maybeSingle();if(latest.error)throw latest.error;
      if(!current())throw new Error('The player account changed. Reopen this preparation before trying again.');
      const row=latest.data;
      if(row&&row.player_id!==playerId)throw new Error('The current Player Plan could not be confirmed.');
      const raw=structuredClone(row?.raw_answers||{core:{},formats:{}});raw.core??={};raw.formats??={};
      const answer=raw.core.core_strengths||{choices:[],comment:''},choices=Array.isArray(answer.choices)?[...answer.choices]:[];
      if(choices.some(value=>scoringShotKey(value)===scoringShotKey(shot)))return {row,alreadySaved:true};
      raw.core.core_strengths={...answer,choices:[...choices,shot]};
      const timestamp=new Date(Math.max(Date.now(),(Date.parse(row?.updated_at)||0)+1)).toISOString();
      const fields={raw_answers:raw,curated_draft:curate(raw),section_status:automaticSectionStatusForRaw(raw,row?.section_status||{}),updated_at:timestamp};
      let saved;
      if(row){
        if(!row.id)throw new Error('The saved Player Plan could not be identified. Reopen My Player Plan and try again.');
        let query=supabase.from('player_plan_workflows').update(fields).eq('id',row.id);
        query=row.updated_at?query.eq('updated_at',row.updated_at):query.is('updated_at',null);
        saved=await query.select().maybeSingle();
      }else saved=await supabase.from('player_plan_workflows').insert({player_id:playerId,...fields,status:'in_progress',submitted_at:null}).select().single();
      if(!row&&saved.error?.code==='23505'&&attempt===0)continue;
      if(saved.error)throw saved.error;
      if(!saved.data)throw new Error('Your Player Plan changed or is currently read-only. Nothing was overwritten. Try again to check the latest plan.');
      if(saved.data.player_id!==playerId||!saved.data.raw_answers?.core?.core_strengths?.choices?.some(value=>scoringShotKey(value)===scoringShotKey(shot)))throw new Error('The shot addition could not be confirmed. Try Add to My Player Plan again to check the saved plan.');
      return {row:saved.data,alreadySaved:false};
    }
    throw new Error('Your Player Plan changed. Try again to check the latest plan.');
  });
  playerPlanSaveQueue=task.then(()=>undefined,()=>undefined);
  return await task;
}
async function adoptPreparationShot(shot,form){
  if(coachingActionSavePending||document.getElementById('myReflectionForm')!==form||!myPlayer||!isPlayerUser())return;
  const state=preparationScoringState.get(form);if(state?.status!=='ready'||!preparationAdoptionCoreQuestion())return;
  const playerId=myPlayer.id,clubId=club?.id,userId=session?.user?.id;
  const current=()=>club?.id===clubId&&myPlayer?.id===playerId&&session?.user?.id===userId&&isPlayerUser()&&document.getElementById('myReflectionForm')===form;
  const status=form.querySelector('#myReflectionStatus');try{validatePreparationEarlierNotes(form);}catch(error){status.textContent=error.message;return;}coachingActionSavePending=true;const restore=freezeCoachingForm(form);status.textContent='Adding the shot to your Player Plan…';
  try{
    const saved=await persistPreparationShot(shot,current);if(!current())return;
    workflow=saved.row;localRaw=null;
    state.candidates=[...(state.candidates||[]).filter(c=>c.source_kind!=='plan'),...preparationPlanCandidatesForRaw(saved.row.raw_answers)];
    status.textContent=saved.alreadySaved?'This shot is already in your Player Plan. Your preparation is still here; save it when ready.':'Added to My Player Plan. Your preparation is still here; save it when ready.';
  }catch(error){if(current())status.textContent=(error?.message||'Could not confirm the Player Plan change.')+' Your preparation is still here. Retry Add to My Player Plan to check before adding again.';}
  finally{coachingActionSavePending=false;if(current()){restore();refreshPreparationScoringChoices(form);flushPreparationLoadedData(form);}}
}
