// BEGIN WEEKLY ENGAGEMENT — saved actions, never clicks or time online.
const engagementMounts=new Set();
let engagementMountNumber=0;
function engagementScope(){return `${club?.id||''}:${session?.user?.id||''}`;}
function engagementCurrent(s){return s.scope===engagementScope()&&document.documentElement.contains(s.host)&&s.host.dataset.engagementMount===String(s.id);}
function engagementSavePending(){return [...engagementMounts].some(s=>engagementCurrent(s)&&(s.busy||s.uncertain));}
function engagementFormValue(form){return form?JSON.stringify([...form.querySelectorAll('input,select,textarea')].map(x=>[x.name,x.value,x.checked])):'';}
function engagementHasUnsavedChanges(){return [...engagementMounts].some(s=>engagementCurrent(s)&&s.form&&s.baseline!==engagementFormValue(s.form));}
function confirmLeaveEngagement(){if(engagementSavePending()){alert('Your check-in is still saving. Please wait.');return false;}return !engagementHasUnsavedChanges()||confirm('Leave without saving your training check-in?');}
function renderEngagementShell(id){return `<div id="${esc(id)}" class="engagement-host" aria-live="polite"></div>`;}
function engagementRequestId(){return typeof crypto?.randomUUID==='function'?crypto.randomUUID():newRequestId();}
function engagementCandidateKey(c){return `${c.kind}:${c.id||''}:${c.key||''}`;}
function engagementStyles(){return `<style>.engagement-card{margin:16px 0;padding:18px;border:1px solid #dce1ed;border-radius:14px;background:#fff}.engagement-card h2{margin:3px 0 8px}.engagement-credit-list{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.engagement-credit{padding:7px 10px;border-radius:18px;background:#f0f2f8;font-size:13px}.engagement-credit.done{background:#e4f5ed;color:#126448;font-weight:700}.engagement-checkin{border-top:1px solid #e4e7ef;margin-top:16px;padding-top:14px}.engagement-checkin select,.engagement-checkin textarea{display:block;width:100%;max-width:100%;margin:7px 0 14px}.engagement-checkin fieldset{border:0;padding:0;margin:12px 0}.engagement-checkin legend{font-weight:700}.engagement-radios{display:flex;flex-wrap:wrap;gap:8px}.engagement-radios label{display:flex;align-items:center;gap:7px;padding:10px;border:1px solid #dce1ed;border-radius:9px;cursor:pointer}.engagement-radios label:has(input:checked){background:#e9edff;border-color:#283785}.engagement-status{margin:8px 0}.engagement-card .btn{min-height:44px}.engagement-card summary{cursor:pointer;font-weight:700}.engagement-card>details>summary{display:flex;align-items:center;gap:10px;min-height:44px;list-style:none}.engagement-card>details>summary::-webkit-details-marker{display:none}.engagement-card>details>summary:after{content:'+';margin-left:auto;font-size:22px;font-weight:400}.engagement-card>details[open]>summary:after{content:'−'}.engagement-card>details>summary>span{font-size:12px;font-weight:400}.engagement-progress-details{border-top:1px solid #e4e7ef;margin-top:14px;padding-top:10px}.engagement-card .engagement-checkin h3{display:none}.engagement-saved{color:#176448;font-weight:700}.engagement-training-priority{margin:10px 0;padding:14px;border-left:4px solid var(--primary,#26327c);background:#f4f5ff}.engagement-training-heading{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}.engagement-training-heading h2{font-size:18px;margin:0}.engagement-training-heading .engagement-saved{font-size:12px}.engagement-training-priority .engagement-checkin{margin-top:8px;padding-top:0;border-top:0}.engagement-training-priority .engagement-checkin>p:first-of-type{margin:0 0 10px}.engagement-training-priority .engagement-radios label{background:#fff}.engagement-training-priority .engagement-radios label:has(input:checked){background:#e9edff;border-color:#283785}.engagement-training-priority .engagement-checkin select,.engagement-training-priority .engagement-checkin textarea{background:#fff}.engagement-training-priority .engagement-status:empty{display:none}.engagement-training-priority .engagement-radios{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;max-width:640px}.engagement-training-priority .engagement-radios label{flex-direction:column;align-items:flex-start;gap:5px;padding:10px 7px;min-height:44px;font-size:14px;overflow-wrap:anywhere}.engagement-training-priority .engagement-radios input{margin:0;width:auto}.engagement-training-priority .engagement-checkin select,.engagement-training-priority .engagement-checkin textarea{border:1px solid #dce1ed;border-radius:8px;padding:9px;font:inherit;min-height:44px}</style>`;}
function engagementAwardDetails(b){
 const a=b.award;
 if(a&&['weekly','monthly'].includes(a.cadence))return a;
 return {cadence:'weekly',period_start:b.week_start,earned:!!b.earned,qualifying_weeks:b.earned?1:0,required_weeks:1,reward_text:b.reward_text||'Recognition only',claim_text:b.claim_text||''};
}
function engagementAwardLastDay(value){
 if(!/^\d{4}-\d{2}-\d{2}$/.test(String(value||'')))return '';
 const d=new Date(value+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-1);return d.toISOString().slice(0,10);
}
function engagementProgressComplete(b){return typeof b.progress_complete==='boolean'?b.progress_complete:!!b.earned;}
function engagementAwardProgress(b){
 const a=engagementAwardDetails(b),weekComplete=engagementProgressComplete(b);
 if(a.released===false){const progress=engagementProgressComplete(b);return `<p>${progress?'<strong>Two different personal activities recorded this week.</strong>':`<strong>${Number(b.count)||0} of 3 personal activities this week.</strong>`}</p>${a.cadence==='monthly'?`<p>${Number(a.qualifying_weeks)||0} of ${Number(a.required_weeks)||2} activity weeks recorded in this four-week period. ${esc(a.period_start||'')} to ${esc(engagementAwardLastDay(a.period_end))}.</p>`:''}<p class="help">Award results will be announced by your club.</p>`;}
 if(a.cadence!=='monthly')return `<p>${a.earned?'<strong>Award earned.</strong>':weekComplete?`<strong>This week’s activities are recorded.</strong> ${a.released===true?'Award results reflect your club’s latest release.':'They do not qualify for another award in this period.'}`:`<strong>${Number(b.count)||0} of 3 activities.</strong>`} ${weekComplete&&!a.earned?'':'Two different activities earn this week’s award.'}</p>`;
 return `<p>${weekComplete?'<strong>This week qualifies.</strong>':`<strong>${Number(b.count)||0} of 3 activities this week.</strong>`} Two different activities make a qualifying week.</p><p><strong>${a.earned?'Four-week award earned.':`${Number(a.qualifying_weeks)||0} of ${Number(a.required_weeks)||2} qualifying weeks in this four-week period.`}</strong> ${esc(a.period_start||'')} to ${esc(engagementAwardLastDay(a.period_end))}.</p>`;
}
function notifyEngagementStatus(s,status='ready'){
 if(engagementCurrent(s)&&typeof s.options.onStatus==='function')s.options.onStatus({status,configured:!!s.bundle?.configured,saved:!!s.bundle?.training_checkin,dirty:!!s.form&&s.baseline!==engagementFormValue(s.form)});
}
function engagementRender(s){
 const b=s.bundle,categories=b.categories||[],training=b.training_checkin,candidates=b.candidates||[],award=engagementAwardDetails(b);
 if(!b.configured){s.host.innerHTML=s.options.training?'<p class="help">Training Check-in is not available for this club yet.</p>':'';s.form=null;s.baseline='';notifyEngagementStatus(s);return;}
 const chosen=candidates.findIndex(c=>c.kind===training?.source_kind&&(c.id||null)===(training?.source_id||null)&&(c.key||null)===(training?.source_key||null));
 const radios=(name,values,selected)=>`<div class="engagement-radios">${values.map(([v,label])=>`<label><input type="radio" name="${name}" value="${v}" ${v===selected?'checked':''} required>${label}</label>`).join('')}</div>`;
 const trainingHtml=s.options.training?`<form class="engagement-checkin"><h3>Training check-in</h3>${candidates.length?`<label>Choose a current focus or saved plan answer<select name="source" required><option value="">Choose…</option>${candidates.map((c,i)=>`<option value="${i}" ${chosen===i?'selected':''}>${esc(c.kind==='focus'?'Current focus: ':'Player Plan: ')}${esc(c.text)}</option>`).join('')}</select></label><fieldset><legend>What happened?</legend>${radios('status',[['worked','Worked on it'],['changed','Changed my approach'],['couldnt','Couldn’t this week']],training?.status)}</fieldset><fieldset><legend>What next?</legend>${radios('next_step',[['keep','Keep working on this'],['adjust','Revisit my focus'],['discuss','Speak with someone']],training?.next_step)}</fieldset><label>Optional note<textarea name="note" maxlength="300" rows="2" placeholder="A useful detail, if needed">${esc(training?.note||'')}</textarea></label><p class="help">To change your focus or ask a coach, use those sections above.</p><button class="btn ${training?'secondary':'primary'}" type="submit">${training?'Saved ✓':'Save check-in'}</button><span data-engagement-form-state class="help"></span>`:'<p>Choose a current focus or save a Player Plan answer first. Your existing focus controls are on this page.</p>'}</form>`:'';
 const compact=!!s.options.compact,awardEnabled=b.award_enabled!==false;
 s.host.innerHTML=engagementStyles()+`<section class="engagement-card${compact?' engagement-training-priority':''}">${compact?`<div class="engagement-training-heading"><h2>Training Check-in</h2>${training?'<span class="engagement-saved">Saved this week ✓</span>':''}</div>${trainingHtml}<details class="engagement-progress-details"><summary>My engagement progress</summary>`:''}<div class="eyebrow">YOUR WEEK</div><h2>${award.cadence==='monthly'?'Engagement progress':'Weekly engagement'} ${award.earned&&award.released!==false?'✓':''}</h2>${b.configured?`${engagementAwardProgress(b)}<div class="engagement-credit-list">${[['prepare','Prepare'],['training','Training check-in'],['review','Review and continue']].map(([k,l])=>`<span class="engagement-credit ${categories.includes(k)?'done':''}">${categories.includes(k)?'✓ ':''}${l}</span>`).join('')}</div><p class="help">Week beginning ${esc(b.week_start)} · ${esc(b.timezone)}. ${Number(b.season_awards)||0} ${typeof award.released==='boolean'?'released awards':'qualifying weeks'} this season.</p>${b.can_view_prizes===true&&String(award.reward_text||'').trim()&&award.reward_text!=='Recognition only'?`<p><strong>Club prize:</strong> ${esc(award.reward_text)}</p>${award.claim_text?`<p class="help"><strong>To claim:</strong> ${esc(award.claim_text)}</p>`:''}`:''}<details><summary>What counts?</summary><p>This award is for your own activities as a player. Admin and coaching duties do not count. Playing admins, coaches and captains can earn it through their own preparation, training check-in and independent reflection.</p><p>Prepare: save a bowler match-up and a scoring option from your plan, or an explained additional shot, before the match day and within the next two weeks.</p><p>Training: check in on a saved focus or plan answer and choose a next step. This is your report, not proof of practice. “Couldn’t this week” can count as thoughtful engagement.</p><p>Review: save your independent innings reflection and choose Keep, Adjust or Discuss within two weeks of the innings.</p><p>Each activity counts once per week. Re-saving the same preparation or innings does not earn it again. Everyone’s qualifying player activity counts automatically. Votes, comments, page opens and time online do not count. A missed week never removes an earlier award.</p>${award.cadence==='monthly'?'<p>For four-week awards, complete two different activities in each of two club weeks within the displayed four-week period. The club sets the first award week; periods run in fixed blocks of four weeks.</p>':''}</details>${s.options.compact?'':trainingHtml}`:'<p class="help">Your club can enable engagement and choose weekly or four-week rewards from Make your prediction settings. Your normal plans, preparation and coaching remain available.</p>'}${compact?'</details>':''}<div class="engagement-status" role="status" data-engagement-status></div></section>`;
 if(!awardEnabled){
  s.host.innerHTML=s.options.training?engagementStyles()+`<section class="engagement-card engagement-training-priority"><div class="engagement-training-heading"><h2>Training Check-in</h2>${training?'<span class="engagement-saved">Saved this week ✓</span>':''}</div>${trainingHtml}<div class="engagement-status" role="status" data-engagement-status></div></section>`:'';
 }
 s.form=s.host.querySelector('form');s.baseline=engagementFormValue(s.form);
 if(s.form){s.form.addEventListener('submit',e=>{e.preventDefault();const source=s.form.elements.source;if(!source||source.value==='')return;const c=candidates[Number(source.value)];if(!c)return;engagementSave(s,'training',{source_kind:c.kind,source_id:c.id||null,source_key:c.key||null,status:s.form.elements.status.value,next_step:s.form.elements.next_step.value,note:s.form.elements.note.value.trim()});});s.form.addEventListener('input',()=>{const button=s.form.querySelector('button[type="submit"]');if(button){const dirty=s.baseline!==engagementFormValue(s.form);button.textContent=dirty?'Save check-in':training?'Saved ✓':'Save check-in';button.classList.toggle('primary',dirty||!training);button.classList.toggle('secondary',!dirty&&!!training);}notifyEngagementStatus(s);});s.form.addEventListener('change',()=>notifyEngagementStatus(s));}
 notifyEngagementStatus(s);
}
async function mountEngagement(host,options={}){
 if(typeof host==='string')host=document.getElementById(host);if(!host)return;
 const s={host,options,scope:engagementScope(),id:++engagementMountNumber,busy:false,bundle:null,form:null,request:null};host.dataset.engagementMount=String(s.id);engagementMounts.add(s);
 for(const old of engagementMounts)if(!engagementCurrent(old))engagementMounts.delete(old);
 host.innerHTML='<p class="help">Loading your weekly engagement…</p>';notifyEngagementStatus(s,'loading');
 try{const {data,error}=await supabase.rpc('get_my_engagement',{p_club_id:options.clubId||club?.id});if(error)throw error;if(!engagementCurrent(s))return;s.bundle=data;engagementRender(s);}catch(e){if(!engagementCurrent(s))return;host.innerHTML=`<p class="help">${esc(e.message||'Weekly engagement could not load.')}</p><button class="btn secondary" data-engagement-retry>Try again</button>`;host.querySelector('button').onclick=()=>mountEngagement(host,options);notifyEngagementStatus(s,'error');}
}
async function engagementSave(s,op,values){
 if(!engagementCurrent(s)||s.busy)return;
 const saveButton=s.uncertain?s.host.querySelector('[data-engagement-status] button'):s.form?.querySelector('button[type="submit"]'),saveLabel=saveButton?.textContent;
 if(s.uncertain){op=s.request.op;values=s.request.values;}
 const key=JSON.stringify({op,values,revision:s.bundle.training_checkin?.revision||0});if(s.request?.key!==key)s.request={key,id:engagementRequestId(),op,values};
 s.busy=true;const controls=[...s.host.querySelectorAll('input,select,textarea,button')],states=controls.map(c=>s.controlStates?.has(c)?s.controlStates.get(c):c.disabled);if(!s.controlStates)s.controlStates=new Map();controls.forEach((c,i)=>{s.controlStates.set(c,states[i]);c.disabled=true;});const status=s.host.querySelector('[data-engagement-status]');if(status)status.textContent='Saving…';if(saveButton){saveButton.textContent='Saving…';saveButton.setAttribute('aria-busy','true');}
 try{
 const args={p_club_id:s.options.clubId||club?.id,p_expected_revision:s.bundle.training_checkin?.revision||0,p_request_id:s.request.id};
 const {data,error}=await supabase.rpc('save_my_training_checkin',{...args,p_values:values});if(error)throw error;
 if(!data||data.player_id!==s.bundle.player_id||!Array.isArray(data.categories))throw new Error('The save could not be confirmed.');
 if(!engagementCurrent(s))return;s.bundle=data;s.request=null;s.uncertain=false;engagementRender(s);
 const savedStatus=s.host.querySelector('[data-engagement-status]');if(savedStatus)savedStatus.textContent='Training check-in saved. This records your engagement, not verified practice.';
 if(typeof s.options.onSaved==='function')s.options.onSaved(data);
 }catch(e){if(!engagementCurrent(s))return;const definite=typeof e.code==='string'&&(/^[0-9A-Z]{5}$/.test(e.code)||e.code.startsWith('PGRST'));s.uncertain=!definite;if(definite)s.request=null;if(status){status.textContent=s.uncertain?'The save could not be confirmed. Keep this page open and retry the same save.':e.message||'Could not save. Your entries remain here; try again.';if(s.uncertain){const retry=document.createElement('button');retry.type='button';retry.className='btn secondary';retry.textContent='Retry save';retry.onclick=()=>engagementSave(s,op,values);status.appendChild(retry);}}}
 finally{s.busy=false;if(saveButton){saveButton.removeAttribute('aria-busy');if(saveButton.isConnected)saveButton.textContent=s.uncertain?'Save unconfirmed':saveLabel;}if(engagementCurrent(s)&&!s.uncertain){controls.forEach((c,i)=>c.disabled=states[i]);s.controlStates=null;}}
}
// END WEEKLY ENGAGEMENT


