/* BEGIN PLAYER PLAN REMINDERS — maintained source */
let workspaceReminderSelection=null;
function planReminderSelection(){
 const key=`${club?.id}:${session?.user?.id}`;
 if(workspaceReminderSelection?.key!==key)workspaceReminderSelection={key,ids:new Set()};
 return workspaceReminderSelection;
}
function workspaceCanRemind(player){
 const due=playerPlanDeadlineState(player).overdue;
 return isAdmin()&&due.length>0&&!workspaceReminderState(player.id).inCooldown;
}
function renderPlanReminderSelection(players){
 const state=planReminderSelection(),eligible=players.filter(workspaceCanRemind),ids=new Set(eligible.map(p=>p.id));
 state.ids=new Set([...state.ids].filter(id=>ids.has(id)));
 return `<div class="plan-reminder-selection"><label><input type="checkbox" id="selectAllOverdue" ${eligible.length?'':'disabled'}>Select all</label><button class="btn" id="remindSelectedPlans" ${state.ids.size?'':'disabled'}>Remind selected${state.ids.size?` (${state.ids.size})`:''}</button></div>`;
}
function bindPlanReminderSelection(page,players){
 if(!isAdmin()||playersWorkspaceGroupFilter!=='__overdue__')return;
 const state=planReminderSelection(),eligible=players.filter(workspaceCanRemind),all=page.querySelector('#selectAllOverdue');
 if(!all)return;
 const sync=()=>{
  all.checked=eligible.length>0&&state.ids.size===eligible.length;all.indeterminate=state.ids.size>0&&state.ids.size<eligible.length;
  page.querySelectorAll('[data-select-overdue]').forEach(x=>x.checked=state.ids.has(x.dataset.selectOverdue));
  const button=page.querySelector('#remindSelectedPlans');button.disabled=!state.ids.size;button.textContent=`Remind selected${state.ids.size?` (${state.ids.size})`:''}`;
 };
 all.onchange=()=>{state.ids=new Set(all.checked?eligible.map(p=>p.id):[]);sync();};
 page.querySelectorAll('[data-select-overdue]').forEach(x=>x.onchange=()=>{x.checked?state.ids.add(x.dataset.selectOverdue):state.ids.delete(x.dataset.selectOverdue);sync();});
 page.querySelector('#remindSelectedPlans').onclick=()=>openPlanReminders([...state.ids]);sync();
}
async function openPlanReminders(ids){
 if(!isAdmin()||!ids.length||!await saveClubEditsBeforeNavigation())return;
 const state=ensureClubMessages();
 if(state.draft&&clubMessageDirty()&&!confirm('Replace your unsent message with this Player Plan reminder?'))return;
 state.draft={...newClubMessageDraft(),kind:'plan_reminder',player_ids:[...new Set(ids)],reminder_candidate_ids:[...new Set(ids)],include_staff:false,staff_initialised:true,
  title:'Player Plan reminder',body:'Please finish the overdue sections of your Player Plan. Open your plan to see what needs attention.',target:'myplan'};
 state.mode='compose';state.notice='';state.openId=null;currentTab='messages';await renderTab();
}
function clubMessageEmailPeople(state){
 const d=state.draft,people=new Map();
 for(const p of state.context.players||[])if(d.player_ids.includes(p.id))people.set(p.user_id,{...p,user_id:p.user_id});
 if(d.include_staff)for(const p of state.context.staff||[])if(d.staff_user_ids.includes(p.user_id))people.set(p.user_id,p);
 return [...people.values()].filter(p=>p.user_id);
}
function messageEmailChoices(state){
 const d=state.draft,people=clubMessageEmailPeople(state);
 return people.map(p=>`<label class="message-check message-email-person"><span>${esc(p.name)}<small>${p.phone_ready?'Phone alerts enabled':'Email fallback'}</small></span><input type="checkbox" data-message-email="${esc(p.user_id)}" aria-label="Email also for ${esc(p.name)}" ${!p.phone_ready||d.email||d.email_user_ids.includes(p.user_id)?'checked':''} ${!p.phone_ready||d.email?'disabled':''}></label>`).join('')||'<p class="help">Choose recipients first.</p>';
}
function refreshMessageEmailChoices(state){
 const host=document.getElementById('messageEmailPeople');if(host)host.innerHTML=messageEmailChoices(state);
}
/* END PLAYER PLAN REMINDERS */

/* BEGIN CLUB MESSAGES — maintained source: tools/club_messages_ui.js */
let clubMessageState=null,clubMessageUnread=0,clubMessageRefreshSequence=0;
const clubMessageTargets=[['','No app link'],['myplan','My Player Plan'],['howwetrain','How We Train'],['prepare','Prepare for a Match'],['innings','My Innings'],['make_your_call','Make your prediction']];
function ensureClubMessages(){
 const key=`${session?.user?.id}:${club?.id}`;
 if(clubMessageState?.key!==key)clubMessageState={key,mode:'inbox',openId:null,context:null,data:null,draft:null,sending:false,deleting:false,selectedIds:[],selectedMode:'inbox',notice:''};
 return clubMessageState;
}
function newClubMessageDraft(){return {request_id:crypto.randomUUID(),player_ids:[],staff_user_ids:[],include_staff:true,staff_initialised:false,recipients_changed:false,title:'',body:'',target:'',email:false,email_user_ids:[],kind:'general'};}
function initialiseMessageStaff(state){
 const d=state.draft;if(!d||d.staff_initialised||!state.context)return;
 d.staff_user_ids=(state.context.staff||[]).filter(p=>p.default_included).map(p=>p.user_id);d.staff_initialised=true;
}
function clubMessageRecipientCount(state){
 const d=state.draft,people=new Set((state.context.players||[]).filter(p=>d.player_ids.includes(p.id)).map(p=>p.user_id||p.id));
 if(d.include_staff)for(const p of state.context.staff||[])if(d.staff_user_ids.includes(p.user_id))people.add(p.user_id);
 return people.size;
}
function messagePeople(count){return `${count} ${count===1?'person':'people'}`;}
function canOpenMessageTarget(target){if(target==='teams')return canOpenClubTab('teams');if(target==='workshop')return canOpenClubTab('workshop');return target==='make_your_call'||(isPlayerUser()&&clubMessageTargets.some(([key])=>key===target)&&!!target);}
function messageStaffRole(role){return ({admin:'Admin',head_coach:'Head Coach',coach:'Coach',captain:'Captain'})[role]||'Staff';}
function clubMessageDirty(){const d=clubMessageState?.draft;return !!(d&&(d.title||d.body||d.player_ids.length||d.recipients_changed||d.target||d.email));}
function confirmLeaveClubMessages(){
 if(clubMessageState?.sending){alert('Your message is sending. Wait for the result before leaving.');return false;}
 if(currentTab==='messages'&&clubMessageState?.mode==='compose'&&clubMessageDirty()&&!confirm('Leave this unsent message? Your draft will stay here while you remain signed in.'))return false;
 return true;
}
function clubMessageStyles(){return `<style>
 .message-list-item{display:flex;align-items:flex-start;gap:4px}.message-list-item .message-row{flex:1;min-width:0}.message-select{display:flex;align-items:center;justify-content:center;min-width:36px;min-height:48px;cursor:pointer}.message-select input,.message-delete-tools input{width:18px;height:18px;margin:0;flex-shrink:0}.message-delete-tools{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:8px 0 12px}.message-delete-tools label{display:flex;gap:8px;align-items:center;min-height:44px;cursor:pointer}.message-delete-tools .btn{min-height:44px;padding:8px 12px}.message-row summary>span{min-width:0;overflow-wrap:anywhere}
 .message-recipient-row{display:flex;align-items:center;gap:4px}.message-recipient-row .message-check{flex:1;min-width:0}.message-recipient-row .message-check span{overflow-wrap:anywhere}
 .messages-page{max-width:840px;margin:0 auto}.messages-head{display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap}.messages-head h1{font-size:24px;margin:0}.messages-head .btn{padding:8px 12px;min-height:44px}.messages-tabs{display:flex;gap:8px;margin:12px 0}.messages-tabs button[aria-pressed=true]{background:var(--navy,#17245f);color:#fff}
 .messages-page .message-row{padding:0;border:1px solid #dce2ee;border-radius:10px;background:white;margin-bottom:8px}.messages-page .message-row>summary{margin:0;display:flex;align-items:center;gap:8px;padding:12px;min-height:44px;box-sizing:border-box;cursor:pointer;list-style:none}.message-row>summary::after{content:'View ⌄';font-size:12px;margin-left:auto;white-space:nowrap}.message-row[open]>summary::after{content:'Close ⌃'}.message-row strong{font-size:15px}.message-row small{display:block;font-size:12px;color:#59657c}.message-content{padding:0 12px 12px;border-top:1px solid #eef0f7}.message-content p{white-space:pre-wrap;overflow-wrap:anywhere;font-size:15px;line-height:1.5;margin:12px 0}.message-unread{width:8px;height:8px;background:#d8232a;border-radius:50%;flex-shrink:0}.message-form{margin-top:12px}.message-form .field{margin-bottom:12px}.message-form input,.message-form textarea,.message-form select{font-size:16px}.message-form label{font-size:13px}.message-form .message-check{display:flex;align-items:center;gap:9px;min-height:44px;margin:0}.message-check input{width:18px;height:18px;margin:0;flex-shrink:0}.message-recipients{max-height:230px;overflow:auto;border:1px solid #dce2ee;border-radius:8px;padding:4px 10px}.message-recipient-tools{display:flex;gap:8px;align-items:center;margin:8px 0}.message-recipient-tools select{min-width:0;flex:1}.message-form fieldset{min-width:0;border:0;padding:0;margin:0}.message-form fieldset:disabled{opacity:.7}.message-form .btn{min-height:44px;padding:8px 10px}.message-form input,.message-form textarea,.message-form select{box-sizing:border-box;max-width:100%}.message-form .help{margin:5px 0;font-size:12px}.message-email-person{justify-content:space-between}.message-email-person small{display:block;color:var(--muted);font-size:12px}.message-form summary{cursor:pointer;min-height:44px;align-content:center;font-size:13px}.se-inbox-followup{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;padding:12px!important}.se-inbox-followup .btn{min-height:44px}.messages-status:empty{display:none}.messages-status{margin:8px 0;font-size:14px}.messages-empty{padding:16px;border:1px solid #dce2ee;border-radius:10px}.message-body-count{float:right;font-weight:400;color:#59657c}
 </style>`;}
async function openClubMessages({compose=false,id=null}={}){
 if(!await saveClubEditsBeforeNavigation())return;
 const state=ensureClubMessages();state.mode=compose?'compose':'inbox';state.openId=id;
 if(compose&&!state.draft)state.draft=newClubMessageDraft();currentTab='messages';await renderTab();
}
async function refreshClubMessageBadge(){
 if(!session?.user||!club||!membership)return;
 const key=`${session.user.id}:${club.id}`,seq=++clubMessageRefreshSequence;
 const [{data,error},followup]=await Promise.all([supabase.rpc('club_messages_api',{p_club_id:club.id,p_action:'badge'}),seFetchSignupFollowup(club.id)]);
 if(key!==`${session?.user?.id}:${club?.id}`||seq!==clubMessageRefreshSequence||error)return;
 clubMessageUnread=Number(data?.unread||0);
 const followupCount=followup.can_view?followup.players.length:0,host=document.getElementById('clubMessagesHost');if(host){host.hidden=!clubMessageUnread&&!followupCount;host.innerHTML=clubMessageUnread||followupCount?`<button class="btn ghost" id="unreadClubMessages" aria-label="${clubMessageUnread} unread club messages; ${followupCount} players to follow up">Messages ${clubMessageUnread?`<span class="coaching-unread-badge">${clubMessageUnread}</span>`:''}${followupCount?`<small> · ${followupCount} to follow up</small>`:''}</button>`:'';document.getElementById('unreadClubMessages')?.addEventListener('click',()=>openClubMessages());}
 void updatePhoneAppBadge();
}
async function openClubMessageTarget(target){
 if(!canOpenMessageTarget(target))return;
 if(!await saveClubEditsBeforeNavigation())return;
 if(target==='prepare')return openMyInnings({prepare:true});
 if(!canOpenClubTab(target))return;currentTab=target;await renderTab();
}
async function copyClubMessage(message,button){
 if(button.disabled)return;const label=button.textContent;button.disabled=true;button.textContent='Copying…';
 const tab=message.target==='prepare'?'innings':message.target;
 const link=tab?new URL(`./app.html?club=${encodeURIComponent(club.id)}&tab=${tab}${message.target==='prepare'?'&prepare=1':''}`,location.href).href:'';
 const text=`${message.title}\n\n${message.body}${link?'\n\n'+link:''}`;
 try{await navigator.clipboard.writeText(text);button.textContent='Copied ✓';}catch{button.textContent='Select and copy below';if(button.nextElementSibling?.matches('[data-message-copy-fallback]'))button.nextElementSibling.remove();const box=document.createElement('textarea');box.dataset.messageCopyFallback='';box.value=text;box.readOnly=true;box.setAttribute('aria-label','Message to copy');button.after(box);box.focus();box.select();}finally{button.disabled=false;}
 setTimeout(()=>{if(button.isConnected)button.textContent=label;},2500);
}
async function renderClubMessages(){
 const page=document.getElementById('page'),state=ensureClubMessages();
 const here=()=>state===clubMessageState&&currentTab==='messages'&&page===document.getElementById('page');
 page.innerHTML=clubMessageStyles()+'<section class="card messages-page"><div class="messages-head"><h1>Messages</h1></div><p role="status">Loading messages…</p></section>';
 try{
  const [list,context,followup]=await Promise.all([supabase.rpc('club_messages_api',{p_club_id:club.id,p_action:'list'}),supabase.rpc('club_messages_api',{p_club_id:club.id,p_action:'context'}),seFetchSignupFollowup(club.id)]);
  if(list.error||context.error)throw list.error||context.error;if(!here())return;
  // A Workshop invitation can arrive while this session is already open.
  // Refresh that permission before drawing its link instead of using stale sign-in data.
  if(list.data.inbox?.some(row=>row.target==='workshop')){
   const [workshopResult,contributorResult]=await Promise.all([
    supabase.from('philosophy_workshops').select('*').eq('club_id',club.id).maybeSingle(),
    supabase.from('philosophy_contributors').select('*').eq('club_id',club.id).eq('user_id',session.user.id).maybeSingle()
   ]);
   if(workshopResult.error||contributorResult.error)throw workshopResult.error||contributorResult.error;if(!here())return;
   workshop=workshopResult.data||null;myContributor=contributorResult.data||null;
  }
  state.data=list.data;state.context=context.data;state.signupFollowup=followup;if(!context.data.can_send&&state.mode!=='inbox'){state.mode='inbox';state.draft=null;}
  drawClubMessages(page,state);void refreshClubMessageBadge();
 }catch(error){if(here()){page.innerHTML=clubMessageStyles()+`<section class="card messages-page"><h1>Messages</h1><p>${esc(error.message||'Messages could not load.')}</p><button class="btn" id="retryClubMessages">Try again</button></section>`;document.getElementById('retryClubMessages').onclick=renderClubMessages;}}
}
function clubWeekMessageLink(row){
 if(row.target!=='teams')return '';const found=String(row.body||'').match(/https:\/\/clubbatting\.com\/app\.html\?[^\s<>]+/);if(!found)return '';
 try{const u=new URL(found[0]);if(!['https://mirelionhq.com','https://clubbatting.com'].includes(u.origin)||u.pathname!=='/app.html'||u.searchParams.get('club')!==club.id||u.searchParams.get('tab')!=='teams')return '';return u.href;}catch{return '';}
}
function drawClubMessages(page,state){
 initialiseMessageStaff(state);
 const data=state.data,staff=!!state.context.can_send,rows=state.mode==='sent'?data.sent:data.inbox;
 if(state.selectedMode!==state.mode){state.selectedIds=[];state.selectedMode=state.mode;}
 state.selectedIds=(state.selectedIds||[]).filter(id=>rows.some(r=>r.id===id));
 page.innerHTML=clubMessageStyles()+`<section class="card messages-page"><div class="messages-head"><h1>${state.mode==='compose'?(state.draft?.kind==='plan_reminder'?'Player Plan reminder':'New message'):'Messages'}</h1>${staff&&state.mode!=='compose'?'<button class="btn" id="newClubMessage">New message</button>':''}</div>
 ${staff?`<div class="messages-tabs"><button class="btn ghost" data-message-mode="inbox" aria-pressed="${state.mode==='inbox'}">Inbox</button><button class="btn ghost" data-message-mode="sent" aria-pressed="${state.mode==='sent'}">Sent</button></div>`:''}
 <p class="messages-status" id="clubMessageNotice" role="status">${esc(state.notice)}</p>
 ${state.mode==='inbox'?seInboxFollowup(state.signupFollowup):''}
 ${state.mode==='compose'?clubMessageComposer(state):rows.length?`<div class="message-delete-tools"><label><input type="checkbox" id="messageSelectAll">Select all</label><button type="button" class="btn ghost" id="deleteClubMessages" disabled>Delete selected</button></div>`+rows.map(row=>`<div class="message-list-item"><label class="message-select"><input type="checkbox" data-message-select="${esc(row.id)}" aria-label="Select message: ${esc(row.title)}" ${state.selectedIds.includes(row.id)?'checked':''}></label><details class="message-row" data-message-id="${esc(row.id)}" ${state.openId===row.id?'open':''}><summary>${state.mode==='inbox'&&!row.opened_at?'<span class="message-unread" aria-label="Unread"></span>':''}<span><strong>${esc(row.title)}</strong><small>${esc(state.mode==='sent'?messagePeople(row.recipients):row.sender)} · ${esc(formatDateShort(row.created_at))}</small></span></summary><div class="message-content"><p>${esc(row.body)}</p>${row.target&&state.mode==='inbox'&&canOpenMessageTarget(row.target)?`<button class="btn" data-message-target="${esc(row.target)}" data-message-link="${esc(clubWeekMessageLink(row))}">${esc(row.target==='teams'?(clubWeekMessageLink(row).includes('team_view=availability')?'Set my availability':'Open Teams'):row.target==='workshop'?'Batting Philosophy Workshop':clubMessageTargets.find(([k])=>k===row.target)?.[1]||'Open')}</button>`:''}${state.mode==='sent'?`<small>${row.opened||0} opened · ${row.push_sent||0} phone deliveries${row.email_total||row.email_requested?` · ${row.email_sent||0} emails sent${row.email_failed?` · ${row.email_failed} email failures`:''}`:''}</small><button class="btn ghost" data-message-copy="${esc(row.id)}">Copy for WhatsApp</button>`:''}</div></details></div>`).join(''):state.mode==='inbox'&&state.signupFollowup?.can_view&&state.signupFollowup.players.length?'':`<div class="messages-empty">${state.mode==='sent'?'Your sent messages will appear here.':'No club messages yet. Coaching discussions stay in Coach Conversations.'}</div>`}</section>`;
 bindMessageDeletion(page,state,rows);
 document.getElementById('viewSignupFollowup')?.addEventListener('click',seOpenSignupFollowup);document.getElementById('retrySignupFollowup')?.addEventListener('click',renderClubMessages);
 document.getElementById('newClubMessage')?.addEventListener('click',()=>{state.mode='compose';state.draft??=newClubMessageDraft();drawClubMessages(page,state);});
 page.querySelectorAll('[data-message-mode]').forEach(b=>b.onclick=()=>{if(!confirmLeaveClubMessages())return;state.mode=b.dataset.messageMode;drawClubMessages(page,state);});
 page.querySelectorAll('[data-message-target]').forEach(b=>b.onclick=()=>{if(b.dataset.messageLink){if(confirmLeaveClubMessages()&&confirmLeaveSelections())location.assign(b.dataset.messageLink);}else openClubMessageTarget(b.dataset.messageTarget);});
 page.querySelectorAll('[data-message-copy]').forEach(b=>b.onclick=()=>copyClubMessage(rows.find(r=>r.id===b.dataset.messageCopy),b));
 const markOpened=async el=>{
  if(!el.open||state.mode!=='inbox')return;const row=data.inbox.find(r=>r.id===el.dataset.messageId);if(!row||row.opened_at)return;
  const {error}=await supabase.rpc('club_messages_api',{p_club_id:club.id,p_action:'open',p_data:{id:row.id}});
  if(error||state!==clubMessageState)return;row.opened_at=new Date().toISOString();el.querySelector('.message-unread')?.remove();void refreshClubMessageBadge();
 };
 page.querySelectorAll('[data-message-id]').forEach(el=>{el.addEventListener('toggle',()=>{
  if(!el.isConnected||state!==clubMessageState||currentTab!=='messages')return;
  const next=el.open?el.dataset.messageId:state.openId===el.dataset.messageId?null:state.openId;
  if(next!==state.openId){state.openId=next;recordAppNavigation(clubNavigationRoute());}
  if(el.open)page.querySelectorAll('[data-message-id]').forEach(other=>{if(other!==el)other.open=false;});
  void markOpened(el);
 });if(el.open)void markOpened(el);});
 if(state.openId&&state.mode==='inbox'&&!data.inbox.some(r=>r.id===state.openId))document.getElementById('clubMessageNotice').textContent='That message is unavailable in this account. Recent messages are shown below.';
 if(state.mode==='compose')bindClubMessageComposer(page,state);
 if(currentTab==='messages')recordAppNavigation(clubNavigationRoute());
}
function bindMessageDeletion(page,state,rows){
 const all=page.querySelector('#messageSelectAll'),button=page.querySelector('#deleteClubMessages');if(!button)return;
 const boxes=[...page.querySelectorAll('[data-message-select]')];
 const sync=()=>{const count=state.selectedIds.length;all.checked=count===rows.length;all.indeterminate=count>0&&count<rows.length;all.disabled=state.deleting;button.disabled=state.deleting||!count;button.textContent=state.deleting?'Deleting…':`Delete selected${count?` (${count})`:''}`;for(const box of boxes){box.checked=state.selectedIds.includes(box.dataset.messageSelect);box.disabled=state.deleting;}page.querySelectorAll('[data-message-mode],#newClubMessage').forEach(b=>b.disabled=state.deleting);};
 all.onchange=()=>{state.selectedIds=all.checked?rows.map(r=>r.id):[];sync();};
 for(const box of boxes)box.onchange=()=>{const id=box.dataset.messageSelect;state.selectedIds=box.checked?[...new Set([...state.selectedIds,id])]:state.selectedIds.filter(x=>x!==id);sync();};
 button.onclick=async()=>{
  if(state.deleting||!state.selectedIds.length)return;
  const ids=[...state.selectedIds],folder=state.mode==='sent'?'Sent':'Inbox',mode=state.mode,clubId=club.id;
  if(!confirm(`Delete ${ids.length} ${ids.length===1?'message':'messages'} from your ${folder}? This removes your copy only.`))return;
  state.deleting=true;state.notice='';sync();
  const here=()=>state===clubMessageState&&state.key===`${session?.user?.id}:${club?.id}`&&currentTab==='messages'&&page===document.getElementById('page');
  try{const {data,error}=await supabase.rpc('club_messages_api',{p_club_id:clubId,p_action:'delete',p_data:{box:mode,ids}});if(error)throw error;if(!data?.deleted)throw Error('Deletion could not be confirmed. Try again.');
   if(!here())return;state.data[mode]=state.data[mode].filter(r=>!ids.includes(r.id));state.selectedIds=[];if(ids.includes(state.openId))state.openId=null;state.notice=`${ids.length} ${ids.length===1?'message deleted':'messages deleted'} from your ${folder}.`;
  }catch(error){if(here())state.notice=error.message||'Messages could not be deleted. Try again.';}
  finally{state.deleting=false;if(here()){drawClubMessages(page,state);void refreshClubMessageBadge();}}
 };sync();
}
function clubMessageComposer(state){
 const d=state.draft??=newClubMessageDraft();initialiseMessageStaff(state);const reminder=d.kind==='plan_reminder',players=(state.context.players||[]).filter(p=>!reminder||d.reminder_candidate_ids.includes(p.id)),staff=reminder?[]:state.context.staff||[],count=clubMessageRecipientCount(state),groups=new Map(players.flatMap(p=>p.groups||[]).map(g=>[g.id,g.name]));
 return `<form class="message-form" id="clubMessageForm"><fieldset ${state.sending?'disabled':''}>
 <details id="messageRecipientPicker" ${d.player_ids.length?'':'open'}><summary>To: <strong id="messageRecipientCount">${messagePeople(count)}</strong> · choose recipients</summary>
 ${reminder?'':`<div class="message-recipient-tools"><select id="messageGroup" aria-label="Choose a Playing Group"><option value="">All players in my access</option><option value="unassigned">Currently unassigned</option>${[...groups].map(([id,name])=>`<option value="${esc(id)}">${esc(name)}</option>`).join('')}</select><button type="button" class="btn ghost" id="messageSelectGroup">Select</button><button type="button" class="btn ghost" id="messageClearRecipients">Clear</button></div>`}
 <div class="message-recipients">${players.length?players.map(p=>`<div class="message-recipient-row"><label class="message-check"><input type="checkbox" data-message-player="${esc(p.id)}" ${d.player_ids.includes(p.id)?'checked':''}><span>${esc(p.name)}</span></label>${phoneStatusBadge(p.phone_ready)}</div>`).join(''):'No players with messaging access. Ask your Club Admin to check your player access.'}</div></details>
 ${staff.length?`<label class="message-check"><input id="messageIncludeStaff" type="checkbox" ${d.include_staff?'checked':''}>Include coaching staff</label>
 <details id="messageStaffPicker" ${d.include_staff?'':'hidden'}><summary><span id="messageStaffCount">${d.staff_user_ids.length} staff included</span> · choose staff</summary>
 <div class="message-recipients">${staff.map(p=>`<div class="message-recipient-row"><label class="message-check"><input type="checkbox" data-message-staff="${esc(p.user_id)}" ${d.staff_user_ids.includes(p.user_id)?'checked':''}><span>${esc(p.name)} <small>· ${esc(messageStaffRole(p.role))}</small></span></label>${phoneStatusBadge(p.phone_ready)}</div>`).join('')}</div></details>`:''}
 <div class="field" style="margin-top:12px"><label for="clubMessageTitle">Title</label><input id="clubMessageTitle" required maxlength="80" value="${esc(d.title)}" placeholder="e.g. Thursday training"></div>
 <div class="field"><label for="clubMessageBody">Message <span class="message-body-count" id="messageBodyCount">${d.body.length}/1500</span></label><textarea id="clubMessageBody" required maxlength="1500" rows="4" placeholder="What does everyone need to know or do?">${esc(d.body)}</textarea></div>
 <div class="field" ${reminder?'hidden':''}><label for="clubMessageTarget">Link to</label><select id="clubMessageTarget">${clubMessageTargets.map(([key,label])=>`<option value="${key}" ${d.target===key?'selected':''}>${label}</option>`).join('')}</select></div>
 <label class="message-check"><input id="clubMessageEmail" type="checkbox" ${d.email?'checked':''}>Also email everyone</label>
 <details id="messageEmailPicker"><summary>Also email selected people</summary><div id="messageEmailPeople">${messageEmailChoices(state)}</div></details>
 <p class="help">Everyone receives this in Messages. Phone alerts where enabled; an email link otherwise.</p>
 ${reminder?'<p class="help">Players who have finished or were reminded within 48 hours are skipped.</p>':''}
 ${state.context.email_mode==='prototype'?'<p class="notice">Email delivery is in Prototype mode. In-app messages work; emails will not be delivered yet.</p>':''}
 <div class="btnrow"><button type="submit" class="btn" id="sendClubMessage">Send to ${messagePeople(count)}</button><button type="button" class="btn ghost" id="copyClubMessageDraft">Copy for WhatsApp</button><button type="button" class="btn ghost" id="discardClubMessageDraft">Discard draft</button></div>
 <p class="messages-status" id="clubMessageSendStatus" role="status"></p></fieldset></form>`;
}
function bindClubMessageComposer(page,state){
 const d=state.draft,form=document.getElementById('clubMessageForm'),status=document.getElementById('clubMessageSendStatus');
 const sync=()=>{
  d.title=form.querySelector('#clubMessageTitle').value;d.body=form.querySelector('#clubMessageBody').value;d.target=form.querySelector('#clubMessageTarget').value;d.email=form.querySelector('#clubMessageEmail').checked;
  d.player_ids=[...form.querySelectorAll('[data-message-player]:checked')].map(x=>x.dataset.messagePlayer);
  d.include_staff=!!form.querySelector('#messageIncludeStaff')?.checked;
  d.staff_user_ids=[...form.querySelectorAll('[data-message-staff]:checked')].map(x=>x.dataset.messageStaff);
  const picker=form.querySelector('#messageStaffPicker');if(picker)picker.hidden=!d.include_staff;
  const staffCount=form.querySelector('#messageStaffCount');if(staffCount)staffCount.textContent=`${d.staff_user_ids.length} staff included`;
  const count=clubMessageRecipientCount(state);form.querySelector('#messageRecipientCount').textContent=messagePeople(count);form.querySelector('#sendClubMessage').textContent=`Send to ${messagePeople(count)}`;form.querySelector('#messageBodyCount').textContent=`${d.body.length}/1500`;
 };
 form.addEventListener('input',sync);form.addEventListener('change',event=>{if(event.target.matches('[data-message-player],[data-message-staff],#messageIncludeStaff'))d.recipients_changed=true;if(event.target.matches('[data-message-email]')){const uid=event.target.dataset.messageEmail;d.email_user_ids=event.target.checked?[...new Set([...d.email_user_ids,uid])]:d.email_user_ids.filter(x=>x!==uid);}sync();if(!event.target.matches('[data-message-email]'))refreshMessageEmailChoices(state);});
 document.getElementById('messageSelectGroup')?.addEventListener('click',()=>{d.recipients_changed=true;const group=form.querySelector('#messageGroup').value;form.querySelectorAll('[data-message-player]').forEach(x=>{const p=state.context.players.find(p=>p.id===x.dataset.messagePlayer);if(!group||(group==='unassigned'?!p.groups.length:p.groups.some(g=>g.id===group)))x.checked=true;});sync();refreshMessageEmailChoices(state);});
 document.getElementById('messageClearRecipients')?.addEventListener('click',()=>{d.recipients_changed=true;form.querySelectorAll('[data-message-player],[data-message-staff],#messageIncludeStaff').forEach(x=>x.checked=false);sync();refreshMessageEmailChoices(state);});
 document.getElementById('discardClubMessageDraft').onclick=()=>{if(clubMessageDirty()&&!confirm('Discard this unsent draft?'))return;state.draft=null;state.mode='inbox';drawClubMessages(page,state);};
 document.getElementById('copyClubMessageDraft').onclick=e=>{sync();void copyClubMessage(d,e.currentTarget);};
 form.onsubmit=async event=>{
  event.preventDefault();if(state.sending)return;sync();if(!clubMessageRecipientCount(state)){status.textContent='Choose at least one person.';form.querySelector('#messageRecipientPicker').open=true;return;}
  if(!d.title.trim()||!d.body.trim()){status.textContent='Add a title and a message.';return;}
  const clubId=club.id;state.sending=true;form.querySelector('fieldset').disabled=true;form.querySelector('#sendClubMessage').textContent='Sending…';status.textContent='Sending…';
  try{const {data,error}=await supabase.rpc('club_messages_api',{p_club_id:clubId,p_action:'send',p_data:{request_id:d.request_id,player_ids:[...d.player_ids],staff_user_ids:d.include_staff?[...d.staff_user_ids]:[],title:d.title,body:d.body,target:d.target,email:d.email,kind:d.kind,email_user_ids:d.email_user_ids.filter(id=>clubMessageEmailPeople(state).some(p=>p.user_id===id))}});if(error)throw error;
   if(state!==clubMessageState||clubId!==club?.id)return;
   state.draft=null;state.mode='sent';const skipped=Number(data.skipped?.cooldown||0)+Number(data.skipped?.no_longer_overdue||0);state.notice=`In Messages for ${messagePeople(data.recipients)} ✓${data.email_queued?` · ${data.email_queued} email${data.email_queued===1?'':'s'} queued`:''}${skipped?` · ${skipped} no longer due or recently reminded`:''}`;state.openId=data.id;state.sending=false;await renderClubMessages();
  }catch(error){if(state===clubMessageState&&form.isConnected){status.textContent=`Send not confirmed. Your draft is kept; retrying will not send it twice. ${error.message||''}`;form.querySelector('fieldset').disabled=false;form.querySelector('#sendClubMessage').textContent='Retry send';}}
  finally{state.sending=false;}
 };
}
/* END CLUB MESSAGES */

/* BEGIN PHONE APP — maintained source: tools/phone_app_ui.js */
let phoneInstallPrompt=null,phoneRegistration=null,phoneStarted=false,phoneSettingsBusy=false;
let phoneRegistrationTask=null,phoneRegistrationError='';
let pendingPhoneLaunch=null;
const phoneIsDemo=()=>typeof window.__fixtureDb!=='undefined'||location.pathname.endsWith('/demo.html');
const phoneIsInstalled=()=>matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
const phoneIsIOS=()=>/iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
const phoneIsAndroid=()=>/Android/i.test(navigator.userAgent);
const phonePushSupported=()=>window.isSecureContext&&'serviceWorker'in navigator&&'PushManager'in window&&'Notification'in window;
function playerSignupWhatsAppMessage(clubName,playerJoinLink,plansReady){
 return `🏏 ${clubName} players — get started with Club Batting

1. Sign up
Open this Player link in Safari on iPhone or Chrome on Android:
${playerJoinLink}

Register with your email and confirm your name. Check your inbox and junk folder for the sign-in email. Playing coaches and captains use this link too.

2. Put Club Batting on your phone
Once you’ve finished registering:

🍎 iPhone: Tap Safari’s three dots (…) at the bottom right → Share → View More if shown → Add to Home Screen. Keep Open as Web App switched on if shown, then tap Add. If you see the Share icon directly, start there.

🤖 Android: In Chrome, tap three dots (⋮) → Install and create shortcut → Install. Some versions say Install app or Add to Home screen.

3. Turn on notifications
Open the new Mirelion icon on your phone. Sign in if asked, then go to Account → App & notifications. Choose Club messages and Coaching updates, tap Enable notifications, then Allow.

${plansReady?'Your Player Plan, training ideas and match preparation are now one tap away.':'Register now while the club prepares How We Bat and the Player Plan questions. We’ll notify you when your plan is ready; anyone assigned a setup role can help with preparation now.'}`;
}
function phoneIOSInstallSteps(){
 return `<ol><li>Tap Safari’s <strong>three dots (…)</strong> at the bottom-right of your screen.</li><li>Tap <strong>Share</strong> — the square with an arrow pointing upwards.</li><li>Tap <strong>View More</strong> if shown, then <strong>Add to Home Screen</strong>. You may need to scroll down.</li><li>Keep <strong>Open as Web App</strong> switched on if shown, then tap <strong>Add</strong>.</li><li>Go to your phone’s Home Screen and open the <strong>Mirelion icon</strong>. Sign in with your existing account if asked.</li></ol>`;
}
function phoneAndroidInstallSteps(){
 return `<ol><li>Tap Chrome’s <strong>three dots (⋮)</strong>, usually at the top-right.</li><li>Tap <strong>Install and create shortcut → Install</strong>. Some versions say <strong>Install app</strong> or <strong>Add to Home screen</strong>.</li><li>Open the new <strong>Mirelion icon</strong> on your phone. Sign in with your existing account if asked.</li></ol>`;
}
function phoneInstallHelp(ios,android){
 const next='<p class="phone-next"><strong>Then turn on alerts:</strong> open <strong>Account → App &amp; notifications</strong> from the new app.</p>';
 if(ios)return `<p>Add the app icon, then open your club straight from your phone.</p>${phoneIOSInstallSteps()}${next}<details><summary>Can’t find it?</summary><p>If Safari shows the <strong>Share icon</strong> directly, tap it and continue from step 3. If <strong>Add to Home Screen</strong> is missing, scroll to <strong>Edit Actions</strong> and add it. On iPad, Share may be at the top.</p><p>If you opened Mirelion inside WhatsApp or another browser, open this page in <strong>Safari</strong> first. Already added the icon? Open that icon instead of adding it again.</p></details>`;
 if(android)return `<p>Add the app icon, then open your club straight from your phone.</p>${phoneInstallPrompt?'<button class="btn" id="installClubBatting">Install Mirelion</button><details><summary>Or use Chrome’s menu</summary>'+phoneAndroidInstallSteps()+'</details>':phoneAndroidInstallSteps()}${next}<details><summary>Can’t find it?</summary><p>If you opened Mirelion inside WhatsApp, use its menu to open this page in <strong>Chrome</strong>. Already added the icon? Open that icon instead of adding it again.</p></details>`;
 return `<details class="phone-other-devices" data-phone-device="iphone"><summary>iPhone or iPad</summary><p>On your phone, open Mirelion in <strong>Safari</strong>.</p>${phoneIOSInstallSteps()}<p class="help">If Share is visible directly, start there. If Add to Home Screen is missing, scroll down or use Edit Actions. On iPad, Share may be at the top.</p>${next}</details><details class="phone-other-devices" data-phone-device="android"><summary>Android</summary><p>On your phone, open Mirelion in <strong>Chrome</strong>.</p>${phoneAndroidInstallSteps()}${next}</details>`;
}
async function phoneWorkerMessage(type,binding=null){
 if(phoneIsDemo()||!('serviceWorker'in navigator))return;
 const reg=phoneRegistration||await navigator.serviceWorker.getRegistration('./');if(!reg?.active)return;
 await new Promise(resolve=>{const channel=new MessageChannel(),timer=setTimeout(resolve,2500);channel.port1.onmessage=()=>{clearTimeout(timer);resolve();};reg.active.postMessage({type,binding},[channel.port2]);});
}
async function updatePhoneAppBadge(){
 if(phoneIsDemo()||!navigator.setAppBadge)return;
 try{const n=clubMessageUnread+(coachingUpdateScopeMatches()?myCoachingUpdates.updates.length:0);if(n)await navigator.setAppBadge(n);else await navigator.clearAppBadge();}catch{}
}
async function initialisePhoneApp(){
 if(phoneIsDemo()||!location.pathname.endsWith('/app.html')||!('serviceWorker'in navigator)||!window.isSecureContext)return;
 if(!phoneStarted){
  phoneStarted=true;
  window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();phoneInstallPrompt=event;if(currentTab==='phone_app')void renderPhoneApp();});
  window.addEventListener('appinstalled',()=>{phoneInstallPrompt=null;if(currentTab==='phone_app')void renderPhoneApp();});
  navigator.serviceWorker.addEventListener('message',event=>{if(event.data?.type==='CB_OPEN')void openPhoneNotification(event.data.url);});
  // Setup never asks for notification permission; only the explicit Enable click does.
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&session&&club&&!(currentTab==='teams'&&selectionState?.view==='board')){void refreshClubMessageBadge();void refreshMyCoachingUpdates();if(phoneSetupPromptState)phoneSetupPromptState.checkedAt=0;void refreshPhoneSetupPrompt();}});
  setInterval(()=>{if(document.visibilityState==='visible'&&session&&club&&!(currentTab==='teams'&&selectionState?.view==='board')){void refreshClubMessageBadge();void refreshMyCoachingUpdates();}},60000);
 }
 if(phoneRegistrationTask)return phoneRegistrationTask;
 if([phoneRegistration?.active,phoneRegistration?.installing,phoneRegistration?.waiting].some(worker=>worker&&worker.state!=='redundant'))return phoneRegistration;
 phoneRegistrationTask=(async()=>{
  try{
   phoneRegistration=await navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'});
   phoneRegistrationError='';return phoneRegistration;
  }catch{
   phoneRegistration=null;
   phoneRegistrationError=navigator.onLine===false?'You’re offline. Reconnect, then try again.':'Phone notification setup couldn’t finish. Please try again.';
   return null;
  }
 })();
 try{return await phoneRegistrationTask;}finally{phoneRegistrationTask=null;}
}
function waitForPhoneWorker(reg){
 if(reg.active?.state==='activated')return Promise.resolve(reg);
 return new Promise((resolve,reject)=>{
  const watched=new Set();let timer;
  const finish=error=>{clearTimeout(timer);reg.removeEventListener('updatefound',check);for(const worker of watched)worker.removeEventListener('statechange',check);error?reject(error):resolve(reg);};
  const check=()=>{
   if(reg.active?.state==='activated'){finish();return;}
   for(const worker of [reg.installing,reg.waiting,reg.active].filter(Boolean))if(!watched.has(worker)){watched.add(worker);worker.addEventListener('statechange',check);}
   if(![reg.installing,reg.waiting,reg.active].some(worker=>worker&&worker.state!=='redundant'))finish(new Error('Phone notification setup couldn’t finish. Please try again.'));
  };
  timer=setTimeout(()=>finish(new Error(navigator.onLine===false?'You’re offline. Reconnect, then try again.':'Phone notification setup hasn’t finished. Please try again.')),10000);
  reg.addEventListener('updatefound',check);check();
 });
}
async function signOutClubBatting(){
 if(phoneIsDemo())return supabase.auth.signOut({scope:'local'});
 try{const reg=phoneRegistration||await navigator.serviceWorker?.getRegistration('./'),sub=await reg?.pushManager.getSubscription();if(sub&&session?.user){await Promise.race([supabase.rpc('phone_app_api',{p_club_id:club?.id||null,p_action:'disable',p_data:{endpoint:sub.endpoint}}),new Promise(resolve=>setTimeout(resolve,3000))]);}}catch{}
 await phoneWorkerMessage('CB_SIGN_OUT');mirelionAssist.reset();clubMessageState=null;clubMessageUnread=0;return supabase.auth.signOut({scope:'local'});
}
async function openPhoneApp(){if(!await saveClubEditsBeforeNavigation())return;currentTab='phone_app';await renderTab();}
function phoneAppPrompt(){
 if(phoneIsInstalled()||phoneIsDemo()||localStorage.getItem('cb-hide-install')==='yes')return '';
 return `<div class="phone-install-prompt"><button class="btn ghost" data-phone-open>Get Mirelion on your phone ↗</button><button type="button" class="btn ghost" data-phone-dismiss aria-label="Dismiss phone installation suggestion">×</button></div>`;
}
function bindPhoneAppControls(){
 void refreshPhoneSetupPrompt();
 document.querySelectorAll('[data-phone-open]').forEach(b=>b.onclick=openPhoneApp);
 document.querySelector('[data-phone-dismiss]')?.addEventListener('click',e=>{localStorage.setItem('cb-hide-install','yes');e.currentTarget.closest('.phone-install-prompt').remove();});
 document.querySelectorAll('[data-club-messages]').forEach(b=>b.onclick=()=>openClubMessages());

}
async function renderPhoneApp(){
 const page=document.getElementById('page'),clubId=club?.id,userId=session?.user?.id;
 const here=()=>currentTab==='phone_app'&&club?.id===clubId&&session?.user?.id===userId&&document.getElementById('page')===page;
 const installed=phoneIsInstalled(),ios=phoneIsIOS(),android=phoneIsAndroid(),demo=phoneIsDemo(),mobile=ios||android,installFirst=!installed&&mobile;
 const phoneStyle=`<style>.phone-settings{max-width:640px;margin:0 auto}.phone-settings h1{font-size:24px;margin:0 0 12px}.phone-settings h2{font-size:19px;margin:16px 0 8px}.phone-settings p,.phone-settings li{font-size:15px;line-height:1.5}.phone-settings ol{padding-left:24px}.phone-settings li{padding-left:3px;margin-bottom:10px}.phone-settings label{display:flex;gap:10px;align-items:center;min-height:44px}.phone-settings input{width:18px;height:18px;margin:0}.phone-settings .help{font-size:12px}.phone-settings details{margin:12px 0}.phone-settings summary{cursor:pointer;min-height:44px;align-content:center;font-weight:700}.phone-settings .phone-next{padding:12px;border-radius:10px;background:#eef0ff}.phone-settings .phone-installed{color:#08766a}.phone-settings [hidden]{display:none!important}.phone-settings #phoneActionStatus:empty{display:none}</style>`;
 // Desktop is an instruction page only, including an installed desktop PWA.
 if(!mobile){
  page.innerHTML=`${phoneStyle}<section class="card phone-settings"><h1>Get Mirelion on your phone</h1><p>Open your club from an icon on your phone.</p>${phoneInstallHelp(false,false)}${demo?'<p class="help">Demo only — no installation or real notifications.</p>':''}</section>`;
  return;
 }
 page.innerHTML=`${phoneStyle}
 <section class="card phone-settings"><h1>${installFirst?'Get the Mirelion app on your phone':'App &amp; notifications'}</h1>
 ${installed?'<p class="phone-installed">✓ You’re using the Mirelion app.</p>':phoneInstallHelp(ios,android)}
 <div id="phoneNotificationPanel" ${installFirst?'hidden':''}>
 <p id="phoneNotificationStatus" role="status">${demo?'Demo only — no installation or real notifications.':'Checking this device…'}</p>
 <p class="phone-next">Choose phone alerts below. Without them, updates arrive by email.</p>
 <div id="phoneNotificationChoices" hidden><label><input type="checkbox" id="phoneMessages" checked>Club messages</label><label><input type="checkbox" id="phoneCoaching" checked>Coaching updates</label></div>
 <div class="btnrow"><button class="btn" id="enablePhoneNotifications" hidden>Enable notifications</button><button class="btn ghost" id="disablePhoneNotifications" hidden>Turn off on this device</button><button class="btn" id="retryPhoneSetup" hidden>Try again</button></div>
 <p id="phoneAllowHint" class="help" hidden>Tap <strong>Allow</strong> when your phone asks.</p>
 <details><summary>About notifications</summary><p class="help">Choices apply to ${esc(club?.name||'this club')} on this device. Alerts show no message details. iPhone/iPad needs iOS/iPadOS 16.4 or later. Find messages in Account → Messages and coaching updates in Coach Conversations.</p></details>
 <p id="phoneActionStatus" role="status" class="help"></p></div>${demo&&installFirst?'<p class="help">Demo only — no installation or real notifications.</p>':''}</section>`;
 document.getElementById('installClubBatting')?.addEventListener('click',async event=>{const button=event.currentTarget;if(button.disabled)return;const prompt=phoneInstallPrompt;phoneInstallPrompt=null;button.disabled=true;button.textContent='Opening install…';try{if(prompt){await prompt.prompt();await prompt.userChoice;}if(here())await renderPhoneApp();}catch{if(here()&&button.isConnected){const menu=button.nextElementSibling;if(menu?.tagName==='DETAILS')menu.open=true;const message=document.createElement('p');message.setAttribute('role','status');message.textContent='Installation could not open. Use Chrome’s menu below.';button.replaceWith(message);}}});
 if(demo)return;
 if(installFirst)return;
 if(!phonePushSupported()){document.getElementById('phoneNotificationStatus').textContent='This browser cannot receive notifications. Open Mirelion in a supported, up-to-date browser.';return;}
 try{
  const reg=await initialisePhoneApp();if(!reg)throw new Error(phoneRegistrationError||'Phone notification setup couldn’t finish. Please try again.');
  await waitForPhoneWorker(reg);if(!here())return;
  let sub=await reg.pushManager.getSubscription();
  const {data,error}=await supabase.rpc('phone_app_api',{p_club_id:clubId,p_action:'get',p_data:{endpoint:sub?.endpoint||null}});if(error)throw error;if(!here())return;
  const status=document.getElementById('phoneNotificationStatus'),button=document.getElementById('enablePhoneNotifications'),off=document.getElementById('disablePhoneNotifications'),choices=document.getElementById('phoneNotificationChoices');
  if(!data.configured){status.textContent='Notifications are not configured yet. Your inbox is available.';return;}
  if(Notification.permission==='denied'){status.textContent='Notifications are blocked. Allow them in your phone or browser notification settings, then return here.';if(sub){off.hidden=false;off.onclick=async()=>{if(phoneSettingsBusy)return;phoneSettingsBusy=true;off.disabled=true;const label=off.textContent;off.textContent='Turning off…';try{const r=await supabase.rpc('phone_app_api',{p_club_id:clubId,p_action:'disable',p_data:{endpoint:sub.endpoint}});if(r.error)throw r.error;if(!here())return;await phoneWorkerMessage('CB_SIGN_OUT');if(here()){await renderPhoneApp();if(here())document.getElementById('phoneActionStatus').textContent='Notifications turned off.';}}catch(error){if(here())document.getElementById('phoneActionStatus').textContent=error.message||'Could not turn off notifications. Try again.';}finally{phoneSettingsBusy=false;if(off.isConnected){off.disabled=false;off.textContent=label;}}};}return;}
  const enabled=!!(sub&&data.subscription_id&&data.club_enabled);
  const anyUpdates=data.preferences.messages||data.preferences.coaching;
  const choicePrompt='Which updates would you like?';
  status.textContent=enabled&&!anyUpdates?'Both types of update are off. Tick either to turn it on.':choicePrompt;
  choices.hidden=false;document.getElementById('phoneMessages').checked=data.preferences.messages;document.getElementById('phoneCoaching').checked=data.preferences.coaching;
  button.hidden=false;button.textContent=enabled?(anyUpdates?'Notifications on ✓':'Notifications off ✓'):'Enable notifications';button.disabled=enabled;
  document.getElementById('phoneAllowHint').hidden=enabled||Notification.permission==='granted';
  off.hidden=!sub;
  if(enabled)await phoneWorkerMessage('CB_BIND',data.binding);
  choices.onchange=()=>{button.textContent=enabled?'Save notification choices':'Enable notifications';button.disabled=false;};
  const disable=async()=>{
   if(phoneSettingsBusy)return;phoneSettingsBusy=true;const label=off.textContent,buttonWasDisabled=button.disabled;off.disabled=true;off.textContent='Turning off…';button.disabled=true;choices.querySelectorAll('input').forEach(input=>input.disabled=true);document.getElementById('phoneActionStatus').textContent='';
   try{if(sub){const {error}=await supabase.rpc('phone_app_api',{p_club_id:clubId,p_action:'disable',p_data:{endpoint:sub.endpoint}});if(error)throw error;await sub.unsubscribe();}await phoneWorkerMessage('CB_SIGN_OUT');if(here()){await renderPhoneApp();if(here())document.getElementById('phoneActionStatus').textContent='Notifications turned off.';}}
   catch(e){if(here())document.getElementById('phoneActionStatus').textContent=e.message||'Could not turn off notifications. Try again.';}
   finally{phoneSettingsBusy=false;if(off.isConnected){off.disabled=false;off.textContent=label;button.disabled=buttonWasDisabled;choices.querySelectorAll('input').forEach(input=>input.disabled=false);}}
  };
  off.onclick=disable;
  button.onclick=async()=>{
   if(phoneSettingsBusy)return;phoneSettingsBusy=true;const label=button.textContent,offWasDisabled=off.disabled;button.disabled=true;button.textContent=enabled?'Saving…':'Enabling…';off.disabled=true;choices.querySelectorAll('input').forEach(input=>input.disabled=true);const result=document.getElementById('phoneActionStatus');result.textContent='';
   try{
    // Keep the browser permission request directly within this user click (required on iOS).
    const permission=Notification.permission==='granted'?'granted':await Notification.requestPermission();
    if(permission!=='granted'){if(here()){result.textContent=permission==='denied'?'Notifications were not allowed. You can change this in your phone settings.':'No change made. Your inbox still works.';button.disabled=false;}return;}
    if(sub&&!data.subscription_id){await sub.unsubscribe();sub=null;}
    if(!sub){const padded=data.public_key.replace(/-/g,'+').replace(/_/g,'/');const key=Uint8Array.from(atob(padded+'='.repeat((4-padded.length%4)%4)),c=>c.charCodeAt(0));sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});}
    if(!here())return;
    const json=sub.toJSON(),saved=await supabase.rpc('phone_app_api',{p_club_id:clubId,p_action:'register',p_data:{endpoint:sub.endpoint,p256dh:json.keys.p256dh,auth:json.keys.auth,messages:document.getElementById('phoneMessages').checked,coaching:document.getElementById('phoneCoaching').checked}});
    if(saved.error)throw saved.error;if(!here())return;await phoneWorkerMessage('CB_BIND',saved.data.binding);await renderPhoneApp();invalidatePhoneSetupPrompt();
   }catch(e){if(here()){result.textContent=`Notifications could not be saved. ${e.message||'Please try again.'}`;button.disabled=false;}}
   finally{phoneSettingsBusy=false;if(button.isConnected){button.textContent=label;button.disabled=false;off.disabled=offWasDisabled;choices.querySelectorAll('input').forEach(input=>input.disabled=false);}}
  };
 }catch(error){if(here()){
  document.getElementById('phoneNotificationStatus').textContent=error.message||'Could not check notifications. Please try again.';
  const retry=document.getElementById('retryPhoneSetup');retry.hidden=false;retry.onclick=()=>renderPhoneApp();
 }}
}
function capturePhoneLaunch(params){
 if(params.get('message')||params.get('coaching')||params.get('prepare')==='1')pendingPhoneLaunch={clubId:params.get('club'),message:params.get('message'),coaching:params.get('coaching'),prepare:params.get('prepare')==='1'};
}
async function applyPhoneLaunch(){
 const launch=pendingPhoneLaunch;if(!launch||launch.clubId!==club?.id)return;pendingPhoneLaunch=null;
 if(launch.message){const s=ensureClubMessages();s.mode='inbox';s.openId=launch.message;currentTab='messages';return;}
 if(launch.prepare&&isPlayerUser()){const s=ensureMyInningsState();s.editId='prepare:new';s.openId=null;currentTab='innings';return;}
 if(launch.coaching){
  const requestedUser=session?.user?.id;
  const {data,error}=await supabase.rpc('get_my_coaching_updates',{p_club_id:club.id});
  if(launch.clubId!==club?.id||requestedUser!==session?.user?.id)return;
  const update=!error&&(data?.updates||[]).find(u=>u.source_key===launch.coaching);
  if(!update){currentTab='conversations';return;}
  pendingCoachingUpdate={...update,clubId:club.id,userId:session.user.id};
  currentTab=update.source_kind==='conversation'?'conversations':update.source_kind==='match'?'innings':'howwetrain';
  if(currentTab==='innings'){const state=ensureMyInningsState();state.season='all';state.format='';state.openId=update.match_id;state.editId=update.can_open?null:update.match_id;}
 }
}
async function openPhoneNotification(raw){
 let url;try{url=new URL(raw);if(url.origin!==location.origin||url.pathname!==location.pathname)return;}catch{return;}
 if(!await saveClubEditsBeforeNavigation())return;
 capturePhoneLaunch(url.searchParams);
 if(!session?.user){history.replaceState({},'',url);return routeAuth();}
 const clubId=url.searchParams.get('club');if(!allMemberships.some(m=>m.club_id===clubId)){alert('This notification belongs to another account or a club you no longer belong to.');return;}
 if(club?.id!==clubId||!document.getElementById('page')){localStorage.setItem('bdp-club-id',clubId);localStorage.setItem('bdp-context','club');history.replaceState({},'',url);await loadContext();}
 else{await applyPhoneLaunch();await renderTab();}
}
let phoneSessionSync='';
async function syncPhoneDeviceSession(){
 if(phoneIsDemo()||!phonePushSupported()||!session?.user||!club)return;
 const key=session.user.id+':'+club.id;if(phoneSessionSync===key)return;phoneSessionSync=key;
 try{
  await initialisePhoneApp();const reg=phoneRegistration||await navigator.serviceWorker.getRegistration('./');const sub=await reg?.pushManager.getSubscription();if(!sub||key!==session?.user?.id+':'+club?.id)return;
  if(Notification.permission==='denied'){
   await supabase.rpc('phone_app_api',{p_club_id:club.id,p_action:'disable',p_data:{endpoint:sub.endpoint}});
   if(key===session?.user?.id+':'+club?.id)await phoneWorkerMessage('CB_SIGN_OUT');return;
  }
  const {data,error}=await supabase.rpc('phone_app_api',{p_club_id:club.id,p_action:'get',p_data:{endpoint:sub.endpoint}});
  if(error){phoneSessionSync='';return;}
  if(key!==session?.user?.id+':'+club?.id)return;
  await phoneWorkerMessage(data.subscription_id?'CB_BIND':'CB_SIGN_OUT',data.binding);
 }catch{phoneSessionSync='';}
}
/* END PHONE APP */

/* BEGIN SELECTIONS MODEL — selections-owned attributes; no batting workflow dependency. */
const SE_FORMATS=[['t20','T20'],['limited_overs','Limited overs'],['long_form','Long-form']];
function seFormatLabel(d){return [SE_FORMATS.find(([key])=>key===d.format)?.[1],d.overs?d.overs+' overs':''].filter(Boolean).join(' · ');}
const SE_BATTING=[['unknown','Not coded'],['top','Top order'],['middle','Middle order'],['lower','Lower order']];
const SE_BOWLING=[['unknown','Not coded'],['pace','Quick'],['spin','Spinner'],['none','Does not bowl']];
const SE_FIELDING=FIELDING_RATINGS;
const SE_LOAD=[['unknown','Not coded'],['frontline','Frontline'],['part_time','Part time']];
function seImportMatch(row,roster){
 const key=v=>String(v||'').trim().toLowerCase().replace(/\s+/g,' '),old=roster.find(p=>p.external_id===row.external_id);
 if(old)return old;
 const matches=roster.filter(p=>key(p.name)===key(row.name));
 if(matches.length>1)throw Error(row.name+' has more than one possible match. Check the playing list.');
 if(matches.length){const p=matches[0];if(p.external_id||(row.account_email&&p.account_email&&key(row.account_email)!==key(p.account_email)))throw Error(row.name+' has different registration details. Check the existing player.');return p;}
 if(row.account_email&&roster.some(p=>!p.external_id&&p.user_id&&key(p.account_email)===key(row.account_email)))throw Error(row.name+' shares an email with another playing-list entry. Check the name.');
 return null;
}
function seValidateRosterNames(rows,roster,importing=false){
 const key=v=>String(v||'').trim().toLowerCase().replace(/\s+/g,' '),working=roster.map(p=>({...p})),seen=new Set();
 for(const [index,row] of rows.entries()){
  const old=importing?seImportMatch(row,working):working.find(p=>row.id&&p.id===row.id),name=key(row.name);
  if((!old||key(old.name)!==name)&&working.some(p=>p!==old&&key(p.name)===name))throw Error(row.name+' is already on the playing list. Edit the existing entry.');
  if(old){if(seen.has(old.id))throw Error('Duplicate player in import.');seen.add(old.id);old.name=row.name;if(importing)old.external_id=row.external_id;}
  else working.push({...row,id:row.id||'new:'+index});
 }
}
function seCSVAccountEmail(row,headers,column){
 if(column<0||column===undefined)return {};
 const key=value=>String(value||'').toLowerCase().replace(/[^a-z]/g,''),heading=key(headers[column]);
 if(/parent|guardian|emergency/.test(heading))return {};
 if(heading==='accountholderemail'){
  const owner=headers.findIndex(h=>key(h)==='accountholder');
  if(owner<0||!['yes','true','1'].includes(String(row[owner]||'').trim().toLowerCase()))return {};
 }
 const email=String(row[column]||'').trim().toLowerCase();if(!email)return {};
 if(email.length>254||! /^[^\s@]+@[^\s@]+$/.test(email))throw Error('Use the player’s own valid email, or leave it blank.');
 return {account_email:email};
}
function seDayStatus(p,d){return (p?.availability?.unavailable_dates||[]).includes(d.date)?'unavailable':(p?.availability?.available_dates||[]).includes(d.date)?'available':'unknown';}
function seCanPick(p,f,index,both=false){return !!p?.active&&f.details.days.filter((_,i)=>both||i===index).every(d=>seDayStatus(p,d)==='available');}
function seRole(p){if(!p)return '';return [SE_BATTING.find(([v])=>v===p.batting)?.[1],p.bowling==='pace'?'Quick':p.bowling==='spin'?spinLabel(p):p.bowling==='unknown'?'Bowling not coded':'',p.bowling_load==='part_time'?'Part time':'',p.keeper?'Keeper':''].filter(Boolean).join(' · ');}
function seClockMinutes(value){
 const match=/^([01]?\d|2[0-3]):([0-5]\d)$/.exec(String(value||'').trim());
 return match?Number(match[1])*60+Number(match[2]):null;
}
function seMatchDuration(details){
 if(details?.format==='t20')return 180;
 const overs=Number(details?.overs);
 if(details?.format==='limited_overs'&&Number.isInteger(overs)&&overs>0)return Math.max(180,Math.min(600,overs*8+45));
 return 480;
}
function seDayWindow(day,details){
 const start=seClockMinutes(day?.start);if(start===null)return null;
 const suppliedEnd=String(day?.end||'').trim(),parsedEnd=seClockMinutes(suppliedEnd);
 if(suppliedEnd&&(parsedEnd===null||parsedEnd<=start))return null;
 return {start,end:suppliedEnd?parsedEnd:start+seMatchDuration(details)};
}
function seOverlap(a,b,detailsA,detailsB){
 if(a?.date!==b?.date)return false;
 const first=seDayWindow(a,detailsA),second=seDayWindow(b,detailsB);
 return !first||!second||first.start<second.end&&second.start<first.end;
}
function seDayTime(day){return seDate(day.date)+(day.start?' · '+day.start:' · time not set');}
function seUnselectedAvailable(roster,fixtures,date){const used=new Set();for(const f of fixtures){if(!f.details||f.details.cancelled)continue;f.details.days.forEach((day,j)=>{if(day.date===date)for(const slot of f.slots)if(slot['d'+(j+1)])used.add(slot['d'+(j+1)]);});}return roster.filter(p=>p.active&&seDayStatus(p,{date})==='available'&&!used.has(p.id)).sort((a,b)=>a.name.localeCompare(b.name));}
function seCounts(f,roster,index){const ps=f.slots.map(s=>roster.find(p=>p.id===s['d'+(index+1)])).filter(Boolean);return {players:ps.length,batters:ps.filter(p=>['top','middle'].includes(p.batting)).length,quicks:ps.filter(p=>p.bowling==='pace'&&p.bowling_load==='frontline').length,spinners:ps.filter(p=>p.bowling==='spin'&&p.bowling_load==='frontline').length,spinProfile:spinProfile(ps),keepers:ps.filter(p=>p.keeper).length};}
function seUsed(p,day,fixtures,exclude={},details={}){return fixtures.some(f=>!f.details.cancelled&&f.details.days.some((d,j)=>seOverlap(d,day,f.details,details)&&f.slots.some((s,i)=>!(f.id===exclude.id&&i===exclude.slot)&&s['d'+(j+1)]===p.id)));}
function sePairs(roster,fixture,fixtures,slot,fixed=null){if(fixture.details.days.length!==2)return [];const [d1,d2]=fixture.details.days,exclude={id:fixture.id,slot};
 const first=roster.filter(p=>p.active&&(!fixed||p.id===fixed)&&seDayStatus(p,d1)==='available'&&!seUsed(p,d1,fixtures,exclude,fixture.details)&&(fixed||seDayStatus(p,d2)!=='available'));
 const second=roster.filter(p=>p.active&&seDayStatus(p,d2)==='available'&&seDayStatus(p,d1)!=='available'&&!seUsed(p,d2,fixtures,exclude,fixture.details));
 return first.flatMap(a=>second.filter(b=>b.id!==a.id).map(b=>{const differences=[];let rank=0;for(const [key,weight,label] of [['batting',3,'batting order'],['bowling',5,'bowling type'],['bowling_load',2,'bowling workload'],['keeper',4,'keeping cover']]){if(a[key]==='unknown'||b[key]==='unknown'){rank+=3;differences.push(label+' not fully coded');}else if(a[key]!==b[key]){rank+=weight;differences.push('Different '+label);}}return {a,b,rank,reason:differences.length?differences.join(' · '):'Same batting role, bowling role and keeping cover'};})).sort((a,b)=>a.rank-b.rank||a.a.name.localeCompare(b.a.name)||a.b.name.localeCompare(b.b.name));
}
function seCSV(text){text=String(text).replace(/^\uFEFF/,'');const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('Unclosed quote in CSV. Export the file again.');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);if(!rows.length)throw Error('The CSV is empty.');return rows;}
function seBlankSlots(){return Array.from({length:11},()=>({d1:null,d2:null}));}
function seDate(date){return new Intl.DateTimeFormat('en-AU',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(date+'T12:00:00Z'));}
function seTeamText(f,clubName){const s=f.published;if(!s)return '';const d=s.details,name=id=>s.players.find(p=>p.id===id)?.name||'Vacant';return [clubName+' — '+d.grade,d.competition,seFormatLabel(d),d.opposition?'v '+d.opposition:'',d.days.map((day,i)=>(d.days.length>1?'Day '+(i+1)+': ':'')+seDate(day.date)+(day.start?' · '+day.start:'' )).join('\n'),d.ground,d.meeting,d.cancelled?'MATCH CANCELLED':s.slots.map((slot,i)=>(i+1)+'. '+seSnapshotName(s,slot.d1,0,true)+(seSnapshotSplit(s,slot)?' (Day 1) / '+seSnapshotName(s,slot.d2,1,true)+' (Day 2)':'')).join('\n'),'Published version '+f.publication].filter(Boolean).join('\n');}
/* END SELECTIONS MODEL */

/* Selections terms editor, shared by the club subscription screen and direct setup. */
async function openSelectionsSubscription(clubId,clubName,{onSaved,onCancel,host,mode}={}){
 const call=async(action,data={})=>{
  const {data:result,error}=await supabase.rpc('club_selections_api',{p_club_id:clubId,p_action:action,p_data:data});
  if(error){const failure=Error(error.message);failure.code=error.code;throw failure;}return result;
 };
 let context;
 if(host){host.__canLeave=()=>false;host.innerHTML='<p role="status">Loading…</p>';}
 try{context=await call('subscription_context');}catch(e){
  if(host){host.__canLeave=()=>true;host.innerHTML=`<button class="btn ghost" id="seBillingClose">Back</button><p role="alert">${seEsc(e.message)}</p>`;host.querySelector('#seBillingClose').onclick=()=>onCancel?.();}
  else alert(e.message);return;
 }
 const p=context.pricing,s=context.subscription||{},a=context.access||{},calendars=context.calendars||[],history=context.history||[],readOnly=context.can_manage===false;
 const trialDays=s.status==='trial'&&s.trial_started&&s.trial_ends?Math.round((new Date(s.trial_ends+'T12:00:00Z')-new Date(s.trial_started+'T12:00:00Z'))/86400000)+1:context.default_trial_days||context.inherited_trial_days||60;
 const today=new Date().toLocaleDateString('en-CA',{timeZone:a.timezone||'Australia/Sydney'});
 const annualPrice=productMode=>s.annual_price_cents??(productMode==='bundle'&&p.bundle_annual_price_cents!=null&&context.batting_annual_price_cents!=null?p.bundle_annual_price_cents-context.batting_annual_price_cents:p.annual_price_cents);
 const priceMissing='Set the price in Platform Settings.';
 const freeTerms=terms=>terms.special_rate_never_ends&&Number(terms.adjustment_percent)===100;
 const initial={access_kind:s.status==='disabled'?'ended':s.status==='active'?'paid':'trial',mode:mode||a.mode||'bundle',calendar:s.calendar||calendars.find(x=>x.code==='australia')?.code||calendars[0]?.code||'',active_from:s.active_from||today,active_until:s.active_until||'',adjustment_percent:s.adjustment_percent??0,adjustment_end:s.adjustment_end||'',special_rate_never_ends:!!s.special_rate_never_ends,expiry_action:s.expiry_action||'renewal_approval',amount_paid_cents:s.amount_paid_cents||0,timezone:a.timezone||'Australia/Sydney',continuation_agreed:!!s.continuation_agreed};
 const dialog=host?null:document.createElement('dialog'),view=host||dialog,pricingDialog=dialog||host?.closest('dialog');
 const canOpenPricing=!readOnly&&pricingDialog&&typeof seCanManageSubscriptions==='function'&&seCanManageSubscriptions()&&typeof renderPlatformConsole==='function';
 if(dialog){dialog.style.maxWidth='700px';dialog.style.width='calc(100% - 32px)';dialog.style.maxHeight='90vh';dialog.style.overflow='auto';}
 view.innerHTML=seStyles()+`<section class="se-page"><div class="se-top"><h2>${host?'Selections':`Selections · ${seEsc(clubName)}`}</h2><button class="btn ghost" id="seBillingClose">${host?'Back':'Close'}</button></div><form id="seSubscriptionForm"><input name="status" type="hidden"><div class="se-form-grid"><label>Access<select name="access_kind">${seOpt([['trial','Free trial'],['paid','Subscription'],['ended','Ended']],initial.access_kind)}</select></label><label>Starts<input name="active_from" type="date" value="${initial.active_from}" required></label></div><p class="se-form-note" id="seTrialTerms"></p><div id="sePaidTerms" hidden><p class="se-form-note" id="seAnnualPrice"></p><button class="btn ghost" type="button" id="seOpenPricing" hidden>Platform Settings</button><label class="se-check" id="seAgreementLabel"><input name="continuation_agreed" type="checkbox" ${initial.continuation_agreed?'checked':''}>Club agreement confirmed</label><details id="seTermDetails"><summary>Term details</summary><div class="se-form-grid"><label>Access ends<input name="active_until" type="date" value="${initial.active_until}"></label><label>Rate reduction (%)<input name="adjustment_percent" type="number" min="0" max="100" step="0.01" value="${initial.adjustment_percent}"></label><label>Special rate ends<select name="special_rate_never_ends">${seOpt([['false','On a date'],['true','Never']],String(initial.special_rate_never_ends))}</select><input name="adjustment_end" type="date" aria-label="Special rate end date" value="${initial.adjustment_end}"></label><label>Payment recorded (${seEsc(s.currency||p.currency)})<input name="amount_paid" type="number" min="0" step="0.01" value="${(initial.amount_paid_cents/100).toFixed(2)}"></label><label>At expiry<select name="expiry_action">${seOpt([['renewal_approval','Require renewal approval'],['return_standard','Return to standard rate'],['end_subscription','End access']],initial.expiry_action)}</select></label></div>${s.club_id?'<button class="btn ghost" type="button" id="seRenewTerms">Prepare renewal</button>':''}</details><button class="btn ghost" type="button" id="sePreviewTerms">Preview amount</button><p id="seQuote" class="se-form-note"></p></div><details id="seMoreSettings"><summary>More settings</summary><div class="se-form-grid">${host?`<input name="mode" type="hidden" value="${seEsc(initial.mode)}">`:`<label>Products<select name="mode">${seOpt([['bundle','Club Batting + Selections'],['standalone','Selections only']],initial.mode)}</select></label>`}<label>Club year<select name="calendar">${seOpt(calendars.map(x=>[x.code,x.label]),initial.calendar)}</select></label><label>Fixture time zone<input name="timezone" value="${seEsc(initial.timezone)}" required></label></div></details><div class="se-actions se-editor-actions"><button class="btn" type="submit" id="seSaveSubscription">Save</button></div></form><p id="seBillingStatus" role="status"></p>${history.length?`<details><summary>History</summary>${history.map(h=>`<p class="se-muted">${seEsc(new Date(h.created_at).toLocaleDateString('en-AU'))} · ${seEsc(h.snapshot.status)} · ${seEsc(h.snapshot.active_from)}${h.snapshot.active_until?' to '+seEsc(h.snapshot.active_until):' · ongoing'}</p>`).join('')}</details>`:''}</section>`;
 if(dialog){document.body.append(dialog);dialog.showModal();dialog.onclose=()=>dialog.remove();}
 let dirty=false,busy=false,pending=null,previousKind=initial.access_kind;
 const status=view.querySelector('#seBillingStatus'),form=view.querySelector('#seSubscriptionForm'),save=view.querySelector('#seSaveSubscription'),field=name=>form.elements.namedItem(name);
 const canLeave=()=>{
  if(busy){status.textContent='Saving…';return false;}
  if(pending){status.textContent='Retry the unconfirmed save before leaving.';return false;}
  return !dirty||confirm('Discard unsaved changes?');
 };
 if(host)host.__canLeave=canLeave;
 const cancel=()=>{if(!canLeave())return;if(dialog)dialog.close();onCancel?.();};
 view.querySelector('#seBillingClose').onclick=cancel;
 dialog?.addEventListener('cancel',e=>{e.preventDefault();cancel();});
 const values=()=>{
  const kind=field('access_kind').value;
  const result={status:kind==='trial'?'trial':kind==='ended'?'disabled':'active',mode:field('mode').value,calendar:field('calendar').value,active_from:field('active_from').value,active_until:field('active_until').value,timezone:field('timezone').value,revision:s.revision||0,access_revision:a.revision||0,annual_price_cents:annualPrice(field('mode').value)??null,adjustment_percent:Number(field('adjustment_percent').value||0),adjustment_end:field('adjustment_end').value,special_rate_never_ends:field('special_rate_never_ends').value==='true',expiry_action:field('expiry_action').value,amount_paid_cents:Math.round(Number(field('amount_paid').value||0)*100),continuation_agreed:field('continuation_agreed').checked};
  if(kind==='paid'&&freeTerms(result))Object.assign(result,{active_until:'',adjustment_end:'',continuation_agreed:false});
  if(kind==='trial')Object.assign(result,{active_until:'',adjustment_percent:0,adjustment_end:'',special_rate_never_ends:false,amount_paid_cents:0,continuation_agreed:false});
  if(kind==='ended')Object.assign(result,{annual_price_cents:annualPrice(field('mode').value)??null,adjustment_percent:s.adjustment_percent??0,adjustment_end:s.adjustment_end||'',special_rate_never_ends:!!s.special_rate_never_ends,amount_paid_cents:s.amount_paid_cents||0,continuation_agreed:!!s.continuation_agreed});
  return result;
 };
 const sync=()=>{
  const kind=field('access_kind').value,d=values(),paid=kind==='paid',free=freeTerms(d);
  field('status').value=d.status;
  view.querySelector('#sePaidTerms').hidden=!paid;
  const missing=d.annual_price_cents==null;
  view.querySelector('#seAnnualPrice').textContent=missing?priceMissing:`${s.annual_price_cents==null?'Annual price':'Agreed annual price'} · ${money(d.annual_price_cents,s.currency||p.currency)}`;
  view.querySelector('#seAnnualPrice').hidden=free;
  view.querySelector('#seOpenPricing').hidden=!missing||!canOpenPricing||free;
  view.querySelector('#sePreviewTerms').disabled=busy||!!pending||readOnly||paid&&missing&&!free;
  save.disabled=busy||readOnly||paid&&missing&&!free&&!pending;
  field('continuation_agreed').required=paid&&!free;
  view.querySelector('#seAgreementLabel').hidden=!paid||free;
  field('active_until').disabled=!paid||free||readOnly;
  field('active_until').closest('label').hidden=free;
  field('adjustment_end').hidden=field('special_rate_never_ends').value==='true';
  field('active_from').readOnly=kind==='trial'&&!!s.trial_started;
  save.textContent=pending?'Retry save':!s.club_id&&kind==='trial'?'Start trial':'Save';
  let hint='';
  if(kind==='trial'){
   const date=new Date(field('active_from').value+'T12:00:00Z');
   if(Number.isFinite(+date)){date.setUTCDate(date.getUTCDate()+trialDays-1);hint=`${trialDays}-day trial · ends ${s.status==='trial'&&s.trial_ends?s.trial_ends:date.toISOString().slice(0,10)}`;}
  }else if(paid&&free)hint='$0 · no expiry';
  view.querySelector('#seTrialTerms').textContent=hint;
 };
 if(s.trial_started&&s.status!=='trial')field('access_kind').querySelector('option[value="trial"]').disabled=true;
 const changed=()=>{
  dirty=true;const kind=field('access_kind').value;view.querySelector('#seQuote').textContent='';
  if(kind!==previousKind){
   if(kind==='trial'&&s.trial_started)field('active_from').value=s.trial_started;
   if(kind==='paid'&&previousKind!=='paid'){field('continuation_agreed').checked=false;field('active_until').value='';}
   previousKind=kind;view.querySelector('#seQuote').textContent='';
  }
  sync();
 };
 form.addEventListener('input',changed);form.addEventListener('change',changed);sync();
 view.querySelector('#seOpenPricing').onclick=async()=>{
  if(!canOpenPricing||!canLeave())return;
  pricingDialog.close();platformView='settings';await renderPlatformConsole();
 };
 const preview=async()=>{
  if(busy||pending)return;
  const data=values();
  if(field('access_kind').value==='paid'&&data.annual_price_cents==null&&!freeTerms(data)){status.textContent=priceMissing;return null;}
  status.textContent='Calculating…';
  try{
   const q=await call('preview_subscription',data);
   view.querySelector('#seQuote').textContent=q.ongoing_complimentary?'Free · no expiry':`${money(q.amount_due_cents,q.currency)} · through ${q.active_until}`;
   status.textContent='';return q;
  }catch(e){status.textContent=e.message;return null;}
 };
 view.querySelector('#sePreviewTerms').onclick=preview;
 view.querySelector('#seRenewTerms')?.addEventListener('click',()=>{
  field('access_kind').value='paid';previousKind='paid';const next=new Date((s.active_until||today)+'T12:00:00Z');
  if(s.active_until)next.setUTCDate(next.getUTCDate()+1);
  field('active_from').value=next.toISOString().slice(0,10)>today?next.toISOString().slice(0,10):today;
  field('active_until').value='';field('amount_paid').value='0.00';field('continuation_agreed').checked=false;
  if(s.expiry_action==='return_standard'&&!s.special_rate_never_ends){field('adjustment_percent').value='0';field('adjustment_end').value='';}
  dirty=true;sync();void preview();
 });
 const lock=()=>{
  form.querySelectorAll('input,select,button').forEach(el=>el.disabled=busy||!!pending||readOnly);
  save.disabled=busy||readOnly;
  view.querySelector('#seBillingClose').disabled=busy;
  if(!busy&&!pending)sync();
 };
 form.onsubmit=async e=>{
  e.preventDefault();if(busy||readOnly)return;
  const data=values();
  if(!pending&&field('access_kind').value==='paid'&&data.annual_price_cents==null&&!freeTerms(data)){status.textContent=priceMissing;return;}
  pending??={...data,request_id:crypto.randomUUID()};busy=true;lock();status.textContent='Saving…';
  try{
   const saved=await call('save_subscription',pending);pending=null;dirty=false;busy=false;
   if(host)host.__canLeave=()=>true;
   if(dialog)dialog.close();
   if(onSaved){
    try{await onSaved(saved);}catch(refreshError){
     const message='Saved. Refresh to see the updated status. '+refreshError.message;
     if(view.isConnected)status.textContent=message;else alert(message);
    }
   }else await openSelectionsSubscription(clubId,clubName,{onCancel,host,mode});
  }catch(e){
   if(e.code)pending=null;
   status.textContent=e.code?e.message:'Save not confirmed. Retry save.';
  }finally{busy=false;if(form.isConnected){lock();if(pending)save.textContent='Retry save';}}
 };
 if(readOnly){form.querySelectorAll('input,select').forEach(el=>el.disabled=true);form.querySelectorAll('button').forEach(el=>el.hidden=true);status.textContent='View only';}
}

/* Selections product administration. Uses the existing guarded billing RPC. */
function seCanManageSubscriptions(){return ['owner','commercial_admin'].includes(platformRole);}
function seCanReadSubscriptions(){return ['owner','commercial_admin','support_admin'].includes(platformRole);}
function openPlatformSelections(){return openPlatformClubs();}
function seSubscriptionSummary(context){
 const a=context.access||{},s=context.subscription||{},today=new Date().toLocaleDateString('en-CA',{timeZone:a.timezone||'Australia/Sydney'}),starts=a.active_from||s.active_from,ends=a.valid_until||s.active_until;
 if(!a.status)return {label:'Not activated',detail:'Choose a free trial or agree subscription terms to get started.'};
 if(a.status==='disabled')return {label:s.club_id?'Access ended':'Not activated',detail:'Access is disabled. Open the subscription to review the next step.'};
 if(starts&&starts>today)return {label:'Scheduled',detail:`Access starts ${niceDate(starts)}${ends?` and ends ${niceDate(ends)}`:''}.`};
 if(ends&&ends<today)return {label:'Expired',detail:`Access ended ${niceDate(ends)}. Review continuation or renewal terms.`};
 if(s.status==='trial')return {label:'Free trial',detail:`Trial through ${niceDate(s.trial_ends||ends)}. Continuation needs approval.`};
 if(s.special_rate_never_ends&&Number(s.adjustment_percent)===100)return {label:'Complimentary',detail:'Ongoing free access, with no expiry or renewal.'};
 if(a.status==='pilot')return {label:'Pilot access',detail:ends?`Access through ${niceDate(ends)}.`:'Pilot access is enabled.'};
 return {label:'Active',detail:ends?`Access through ${niceDate(ends)}.`:'Access is enabled.'};
}
async function renderPlatformSelections(){return openPlatformClubs();}

/* One club workspace, independently recorded product terms. */
let platformClubsLoad=0;
function openPlatformClubs(){platformView='clubs';platformSelectedProspectId=null;platformSelectedOnboardingId=null;return renderPlatformConsole();}
async function clubProductContext(id){
 const call=async(name)=>{const {data,error}=await supabase.rpc(name,{p_club_id:id,p_action:'context'});if(error)throw Error(error.message);return data;};
 const [batting,selections]=await Promise.allSettled([call('platform_club_batting_api'),(async()=>{const {data,error}=await supabase.rpc('club_selections_api',{p_club_id:id,p_action:'subscription_context'});if(error)throw Error(error.message);return data;})()]);
 return {batting:batting.status==='fulfilled'?batting.value:null,battingError:batting.status==='rejected'?batting.reason.message:'',selections:selections.status==='fulfilled'?selections.value:null,selectionsError:selections.status==='rejected'?selections.reason.message:''};
}
function clubBattingSummary(context){
 const s=context?.subscription,t=context?.trial;
 if(!s||context.can_activate)return {label:'No subscription',detail:''};
 const today=context.starts_on||new Date().toISOString().slice(0,10);
 if(s.active_until&&s.active_until!=='infinity'&&s.active_until<today)return {label:'Expired',detail:`Ended ${niceDate(s.active_until)}`};
 if(s.special_rate_never_ends&&Number(s.adjustment_percent)===100)return {label:'Complimentary',detail:'$0 · no expiry'};
 if(context.status==='trial')return {label:'Free trial',detail:`Until ${niceDate(t?.ends_on||s.active_until)}`};
 return {label:'Active',detail:s.active_until==='infinity'?'Ongoing':`Until ${niceDate(s.active_until)}`};
}
function clubSelectionSummary(context){
 const summary=seSubscriptionSummary(context);const s=context?.subscription,a=context?.access;
 if(summary.label==='Not activated')return {label:'Not added',detail:''};
 if(summary.label==='Complimentary')return {label:'Complimentary',detail:'$0 · no expiry'};
 const end=summary.label==='Free trial'?s?.trial_ends||a?.valid_until:a?.valid_until||s?.active_until;
 return {label:summary.label,detail:summary.label==='Scheduled'?`From ${niceDate(a?.active_from||s?.active_from)}`:end?`${summary.label==='Expired'?'Ended':'Until'} ${niceDate(end)}`:summary.label==='Complimentary'?'$0 · no expiry':''};
}
function clubProductsStyles(){return seStyles()+`<style>.cp-list{display:grid;gap:10px;margin-top:16px}.cp-row{display:grid;grid-template-columns:minmax(180px,1.4fr) minmax(160px,1fr) minmax(150px,1fr) auto;gap:16px;align-items:center;padding:16px;border:1px solid #dce2ee;border-radius:12px;background:white}.cp-product-label{display:block;font-size:12px;color:#64748b;margin-bottom:4px}.cp-row strong{font-size:16px}.cp-detail{font-size:13px;color:#64748b;margin:4px 0 0}.cp-products{display:grid;gap:12px;margin-top:18px}.cp-product{display:flex;gap:16px;align-items:center;justify-content:space-between;border:1px solid #dce2ee;padding:16px;border-radius:10px}.cp-product h3{margin:0 0 6px}.cp-product p{margin:0}.cp-dialog{border:1px solid #cbd5e1;border-radius:14px;width:calc(100% - 32px);max-width:680px;max-height:90vh;overflow:auto;padding:20px}.cp-dialog::backdrop{background:#0b173766}.cp-dialog details{margin:16px 0}.cp-dialog summary{cursor:pointer;min-height:36px}.cp-dialog [hidden]{display:none!important}.cp-dialog input,.cp-dialog select{font:inherit}.cp-search{max-width:440px;margin-top:16px}@media(max-width:700px){.cp-row{grid-template-columns:1fr 1fr;gap:12px}.cp-row>strong{grid-column:1/-1}.cp-row>.btn{grid-column:1/-1}.cp-dialog{padding:14px}.cp-product{padding:12px;gap:8px}}</style>`;}
async function renderPlatformActiveClubs(message=''){
 const page=document.getElementById('platformPage'),sequence=++platformClubsLoad,userId=session?.user?.id;
 const current=()=>sequence===platformClubsLoad&&platformView==='clubs'&&userId===session?.user?.id&&page===document.getElementById('platformPage');
 page.innerHTML='<div class="splash">Loading clubs…</div>';
 const [clubsRes,removedRes]=await Promise.all([supabase.from('clubs').select('id,name,archived_at').is('archived_at',null).order('name'),supabase.from('platform_club_removals').select('club_id,club_name,contact_name,contact_email,removed_at').order('removed_at',{ascending:false})]);
 if(!current())return;
 if(clubsRes.error||removedRes.error){page.innerHTML=`<section class="admin-card"><p>${seEsc(clubsRes.error?.message||removedRes.error?.message)}</p><button class="btn" id="cpRetry">Retry</button></section>`;page.querySelector('#cpRetry').onclick=()=>renderPlatformActiveClubs();return;}
 const rows=(clubsRes.data||[]).map(club=>({club})),removed=removedRes.data||[];let next=0;
 if(seCanReadSubscriptions())await Promise.all(Array.from({length:Math.min(4,rows.length)},async()=>{while(next<rows.length){const row=rows[next++];row.products=await clubProductContext(row.club.id);}}));
 if(!current())return;
 page.innerHTML=clubProductsStyles()+`<section class="se-page"><div class="se-top"><h1>Clubs</h1><button class="btn ghost" id="cpRefresh">Refresh</button></div><label class="cp-search">Find a club<input id="cpSearch" type="search" placeholder="Club name"></label>${message?`<p role="status">${seEsc(message)}</p>`:''}<div class="cp-list" id="cpClubs"></div><p id="cpEmpty" hidden>No matching clubs.</p>${removed.length?`<details class="se-card" style="margin-top:16px"><summary>Archived clubs · ${removed.length}</summary>${removed.map(row=>`<div class="message-row"><strong>${seEsc(row.club_name)}</strong><button class="btn ghost" data-removed-promo="${seEsc(row.club_id)}">Add to pipeline</button></div>`).join('')}</details>`:''}</section>`;
 const render=()=>{const q=page.querySelector('#cpSearch').value.trim().toLowerCase(),visible=rows.filter(row=>row.club.name.toLowerCase().includes(q));page.querySelector('#cpEmpty').hidden=!!visible.length;page.querySelector('#cpClubs').innerHTML=visible.map(({club:c,products:p})=>{
  const batting=p?.batting?clubBattingSummary(p.batting):null,selections=p?.selections?clubSelectionSummary(p.selections):null;
  const status=(label,summary,error)=>`<div><span class="cp-product-label">${label}</span>${error?'Status unavailable':seEsc(summary?.label||'Restricted')}<div class="cp-detail">${seEsc(summary?.detail||'')}</div></div>`;
  return `<article class="cp-row"><strong>${seEsc(c.name)}</strong>${status('Club Batting',batting,p?.battingError)}${status('Selections',selections,p?.selectionsError)}${seCanReadSubscriptions()?`<button class="btn" data-club-manage="${seEsc(c.id)}">${seCanManageSubscriptions()?'Manage':'View'}</button>`:''}</article>`;
 }).join('');page.querySelectorAll('[data-club-manage]').forEach(button=>button.onclick=()=>{const row=rows.find(r=>r.club.id===button.dataset.clubManage);return openClubSubscriptions(row.club.id,row.club.name);});};
 page.querySelector('#cpSearch').oninput=render;page.querySelector('#cpRefresh').onclick=()=>renderPlatformActiveClubs();page.querySelectorAll('[data-removed-promo]').forEach(button=>button.onclick=()=>openPlatformLeadEntry(removed.find(r=>r.club_id===button.dataset.removedPromo)));render();
}
async function openClubSubscriptions(clubId,clubName,{onSelectionsSaved}={}){
 const dialog=document.createElement('dialog');dialog.id='clubSubscriptionDialog';dialog.className='cp-dialog';dialog.innerHTML=clubProductsStyles()+`<section class="se-page"><div class="se-top"><h2>${seEsc(clubName)}</h2><button class="btn ghost" id="cpClose">Close</button></div><div id="clubProductEditor"><p>Loading…</p></div></section>`;document.body.append(dialog);dialog.showModal();
 const host=dialog.querySelector('#clubProductEditor'),userId=session?.user?.id;let products,busy=false;
 const current=()=>dialog.isConnected&&userId===session?.user?.id;
 const canLeave=()=>!busy&&(!host.__canLeave||host.__canLeave());
 dialog.querySelector('#cpClose').onclick=()=>{if(canLeave())dialog.close();};dialog.addEventListener('cancel',event=>{if(!canLeave())event.preventDefault();});dialog.onclose=()=>dialog.remove();
 const refresh=async()=>{busy=true;products=await clubProductContext(clubId);busy=false;if(current())overview();};
 const saved=async(product)=>{await refresh();if(!current())return;if(platformView==='clubs'&&document.getElementById('platformPage'))await renderPlatformActiveClubs();if(product==='selections'&&onSelectionsSaved){dialog.close();await onSelectionsSaved();}};
 const overview=()=>{
  delete host.__canLeave;
  host.innerHTML=`<div class="cp-products">${[['batting','Club Batting'],['selections','Selections']].map(([key,label])=>{
   const context=products[key],error=products[key+'Error'],summary=context?(key==='batting'?clubBattingSummary(context):clubSelectionSummary(context)):null,has=context&&(key==='batting'?!context.can_activate:!!context.subscription||context.access?.status&&context.access.status!=='disabled');
   return `<section class="cp-product"><div><h3>${label}</h3><p>${error?'Status unavailable':seEsc(summary?.label||'Unavailable')}</p>${summary?.detail?`<p class="cp-detail">${seEsc(summary.detail)}</p>`:''}</div>${error?'<button class="btn ghost" data-cp-retry>Retry</button>':`<button class="btn ${has?'ghost':''}" data-club-product="${key}" ${key==='selections'&&products.battingError?'disabled':''}>${context.can_manage===false?'View':has?'Change':'Add'}</button>`}</section>`;
  }).join('')}</div>${platformRole==='owner'?'<details><summary>Club settings</summary><button class="btn ghost danger-lite" id="cpArchive">End &amp; remove club</button></details>':''}`;
  host.querySelectorAll('[data-cp-retry]').forEach(button=>button.onclick=refresh);
  host.querySelectorAll('[data-club-product]').forEach(button=>button.onclick=()=>{
   if(button.dataset.clubProduct==='selections')return openSelectionsSubscription(clubId,clubName,{host,mode:products.batting?.subscription&&['active','grace'].includes(products.batting.subscription.status)?'bundle':'standalone',onCancel:overview,onSaved:()=>saved('selections')});
   return renderClubBattingEditor(host,clubId,products.batting,{onCancel:overview,onSaved:()=>saved('batting')});
  });host.querySelector('#cpArchive')?.addEventListener('click',()=>{dialog.close();openEndClubDialog(clubId);});
 };
 await refresh();
}
function renderClubBattingEditor(host,clubId,context,{onCancel,onSaved}){
 const s=context.can_activate?null:context.subscription,canManage=context.can_manage!==false,initialFree=s?.special_rate_never_ends&&Number(s.adjustment_percent)===100,existingTrial=context.status==='trial';let busy=false,dirty=false,pending=null,previousKind=initialFree?'complimentary':existingTrial?'trial':'paid';
 host.__canLeave=()=>{if(busy||pending){alert('Retry the unconfirmed save before leaving.');return false;}return !dirty||confirm('Discard these changes?');};
 host.innerHTML=`<form id="cpBattingForm"><div class="se-top" style="margin:18px 0"><h3>Club Batting</h3><button class="btn ghost" type="button" id="cpBattingBack">Back</button></div><div class="se-form-grid"><label>Access<select name="access_kind">${seOpt(s?[...(existingTrial?[['trial','Free trial']]:[]),['complimentary','Complimentary'],['paid','Paid subscription']]:[...(context.trial_available?[['trial','Free trial']]:[]),['complimentary','Complimentary']],s?initialFree?'complimentary':existingTrial?'trial':'paid':context.trial_available?'trial':'complimentary')}</select></label>${s?`<label id="cpBattingEndLabel">Until<input name="active_until" type="date" value="${s.active_until==='infinity'?'':seEsc(s.active_until)}"></label>`:''}</div><p id="cpBattingHint" class="cp-detail"></p>${s?`<details id="cpBattingMore"><summary>More settings</summary><div class="se-form-grid"><label>Rate reduction %<input name="adjustment_percent" type="number" min="0" max="100" value="${Number(s.adjustment_percent)||0}"></label><label>Special rate ends<select name="never_ends">${seOpt([['false','On a date'],['true','Never']],String(!!s.special_rate_never_ends))}</select><input name="adjustment_end" type="date" aria-label="Special rate ends" value="${seEsc(s.adjustment_end||'')}"></label><label>At expiry<select name="expiry_action">${seOpt([['renewal_approval','Review renewal'],['return_standard','Return to standard price'],['end_subscription','End access']],s.expiry_action||'renewal_approval')}</select></label></div></details><label class="se-check" id="cpBattingAgreement"><input name="agreed" type="checkbox">Club has agreed to these terms</label>`:`<details><summary>More settings</summary><label>Club year<select name="calendar">${seOpt((context.calendars||[]).map(c=>[c.code,c.label]),context.calendar)}</select></label></details>`}<div class="se-actions" style="margin-top:16px"><button class="btn" type="submit" id="cpBattingSave">${s?'Save':'Start trial'}</button></div><p id="cpBattingStatus" role="status"></p></form>`;
 const form=host.querySelector('form'),field=name=>form.elements.namedItem(name),status=host.querySelector('#cpBattingStatus');
 const sync=()=>{const kind=field('access_kind').value;if(s&&kind==='paid'&&previousKind!=='paid'){field('adjustment_percent').value='0';field('never_ends').value='false';field('adjustment_end').value='';field('agreed').checked=false;if(s.active_until==='infinity')field('active_until').value='';}previousKind=kind;host.querySelector('#cpBattingHint').textContent=kind==='trial'?(s?`Until ${niceDate(s.active_until)}`:`${context.default_trial_days}-day trial`):kind==='complimentary'?'$0 · no expiry':'';if(s){host.querySelector('#cpBattingEndLabel').hidden=kind!=='paid';host.querySelector('#cpBattingMore').hidden=kind!=='paid';host.querySelector('#cpBattingAgreement').hidden=kind!=='paid';field('active_until').required=kind==='paid';}host.querySelector('#cpBattingSave').textContent=s?'Save':kind==='trial'?'Start trial':'Add Club Batting';};sync();
 form.addEventListener('input',()=>{dirty=true;sync();});form.addEventListener('change',()=>{dirty=true;sync();});host.querySelector('#cpBattingBack').onclick=()=>{if(host.__canLeave())onCancel();};
 if(!canManage){form.querySelectorAll('input,select').forEach(x=>x.disabled=true);host.querySelector('#cpBattingSave').hidden=true;}
 form.onsubmit=async(event)=>{
  event.preventDefault();if(busy||!canManage)return;
  const kind=field('access_kind').value;
  if(!pending&&s&&kind==='paid'&&!field('agreed').checked){status.textContent='Confirm the club agreement.';return;}
  let name,data;
  if(s){const free=kind==='complimentary';name='platform_club_batting_api';data={p_club_id:clubId,p_action:'update_terms',p_data:{kind,state_token:context.state_token,request_id:crypto.randomUUID(),adjustment_percent:free?100:Number(field('adjustment_percent').value),never_ends:free||field('never_ends').value==='true',adjustment_end:free||field('never_ends').value==='true'?null:field('adjustment_end').value||null,active_until:free?null:field('active_until').value,expiry_action:field('expiry_action').value,continuation_agreed:field('agreed').checked}};}
  else{name='platform_club_batting_api';data={p_club_id:clubId,p_action:'activate',p_data:{kind,calendar:field('calendar').value,timezone:context.timezone||'Australia/Sydney',state_token:context.state_token,request_id:crypto.randomUUID()}};}
  pending??={name,data};busy=true;status.textContent='Saving…';form.querySelectorAll('input,select,button').forEach(x=>x.disabled=true);
  try{const result=await supabase.rpc(pending.name,pending.data);if(result.error){if(result.error.code)pending=null;throw Error(result.error.message);}pending=null;dirty=false;busy=false;delete host.__canLeave;try{await onSaved();}catch(e){status.textContent='Saved. Refresh to see the change.';}}
  catch(e){status.textContent=(pending?'Save not confirmed. Retry. ':'')+e.message;}
  finally{busy=false;if(form.isConnected){form.querySelectorAll('input,select,button').forEach(x=>x.disabled=!!pending);host.querySelector('#cpBattingSave').disabled=false;host.querySelector('#cpBattingSave').textContent=pending?'Retry save':s?'Save':kind==='trial'?'Start trial':'Add Club Batting';}}
 };
}
function clubPlatformSettingsStyles(){return `<style>
 #productPriceSettings,.cp-settings-disclosure{max-width:980px;margin:0 auto 14px;min-width:0;box-sizing:border-box}
 .cp-price-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:18px 0}
 .cp-price-product{min-width:0;margin:0;padding:16px;border:1px solid var(--line,#d8deea);border-radius:12px;background:#fafbfd}
 .cp-price-product h3{font-size:16px;margin:0 0 16px;color:var(--navy2,#172544)}
 .cp-price-product h3 small{display:inline;margin-left:4px;font-size:12px;font-weight:400;color:var(--muted,#667085)}
 .cp-price-product label{display:grid;gap:7px;font-size:13px}
 .cp-price-product label+label{margin-top:16px}
 .cp-price-product input{min-width:0;width:100%;box-sizing:border-box}
 .cp-price-unit{margin:0;color:var(--muted,#667085);font-size:13px}
 details.cp-settings-disclosure{display:block;border:1px solid var(--line,#d8deea);border-radius:12px;background:#fff;padding:0;overflow:hidden}
 details.cp-settings-disclosure>summary{display:list-item;list-style:disclosure-closed inside;padding:16px 18px;cursor:pointer;font-weight:700;color:var(--navy2,#172544)}
 details.cp-settings-disclosure[open]>summary{list-style-type:disclosure-open}
 details.cp-settings-disclosure>summary::-webkit-details-marker{display:inline}
 details.cp-settings-disclosure:not([open])>:not(summary){display:none!important}
 .cp-settings-body{padding:0 18px 18px;min-width:0}
 .cp-settings-body>.admin-card{margin:0 0 14px}
 .cp-settings-body .form-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
 .cp-settings-body input,.cp-settings-body select{max-width:100%;min-width:0;box-sizing:border-box}
 @media(max-width:760px){.cp-price-grid,.cp-settings-body .form-grid{grid-template-columns:minmax(0,1fr)}.cp-settings-body{padding:0 12px 12px}.cp-price-product{padding:14px}.cp-price-product h3{margin-bottom:12px}}
 </style>`;}
async function mountProductPriceSettings(){
 const host=document.getElementById('productPriceSettings');if(!host||!seCanReadSubscriptions())return;
 host.innerHTML='<section class="admin-card"><h2>Product pricing &amp; trials</h2><p>Loading…</p></section>';
 const {data:p,error}=await supabase.rpc('platform_product_pricing_api',{p_action:'context'});if(!host.isConnected)return;
 if(error){host.innerHTML=`<section class="admin-card"><h2>Product pricing &amp; trials</h2><p>${seEsc(error.message)}</p><button class="btn" id="cpPricingRetry">Retry</button></section>`;host.querySelector('button').onclick=mountProductPriceSettings;return;}
 const amount=v=>v==null?'':(v/100).toFixed(2);
 host.innerHTML=seStyles()+`<section class="admin-card form-wide se-page"><h2>Product pricing &amp; trials</h2><p class="cp-price-unit">${seEsc(p.currency)} per year</p><form id="cpProductPricingForm"><div class="cp-price-grid"><section class="cp-price-product" aria-labelledby="cpBattingPriceHeading"><h3 id="cpBattingPriceHeading">Club Batting</h3><label>Annual price<input name="batting_annual_price" type="number" min="0" step="0.01" required value="${amount(p.batting_annual_price_cents)}"></label><label>Free trial (days)<input name="batting_trial_days" type="number" min="1" max="180" step="1" required value="${Number(p.trial_days??60)}"></label></section><section class="cp-price-product" aria-labelledby="cpSelectionsPriceHeading"><h3 id="cpSelectionsPriceHeading">Teams &amp; availability</h3><label>Annual price<input name="selection_annual_price" type="number" min="0" step="0.01" placeholder="Not set" value="${amount(p.selection_annual_price_cents)}"></label><label>Free trial (days)<input name="selection_trial_days" type="number" min="1" max="365" step="1" required value="${Number(p.selection_trial_days??21)}"></label></section><section class="cp-price-product" aria-labelledby="cpBothPriceHeading"><h3 id="cpBothPriceHeading">Both products <small>Optional</small></h3><label>Annual price<input name="bundle_annual_price" type="number" min="0" step="0.01" placeholder="Not set" value="${amount(p.bundle_annual_price_cents)}"></label><p>Each product keeps its own trial length.</p></section></div><p class="help">Trial lengths apply to new trials. Existing trial dates and agreed club terms stay unchanged.</p><button class="btn" id="cpPricingSave" type="submit" disabled>Saved</button><p role="status"></p></form></section>`;
 const form=host.querySelector('form'),status=form.querySelector('[role=status]'),save=form.querySelector('button');if(!p.can_manage){form.querySelectorAll('input').forEach(x=>x.disabled=true);save.hidden=true;return;}
 let pending=null,busy=false,dirty=false;
 const edited=()=>{if(busy||pending)return;dirty=true;save.disabled=false;save.textContent='Save settings';status.textContent='';};
 form.addEventListener('input',edited);form.addEventListener('change',edited);
 form.onsubmit=async event=>{event.preventDefault();if(busy||(!dirty&&!pending))return;
 const value=name=>form.elements.namedItem(name).value,price=name=>value(name)===''?null:Math.round(Number(value(name))*100);
 pending??={batting_annual_price_cents:price('batting_annual_price'),selection_annual_price_cents:price('selection_annual_price'),bundle_annual_price_cents:price('bundle_annual_price'),batting_trial_days:Number(value('batting_trial_days')),selection_trial_days:Number(value('selection_trial_days')),state_token:p.state_token,request_id:crypto.randomUUID()};
 busy=true;form.querySelectorAll('input,button').forEach(x=>x.disabled=true);save.textContent='Saving…';status.textContent='';
 try{const {error}=await supabase.rpc('platform_product_pricing_api',{p_action:'save',p_data:pending});if(error){if(error.code)pending=null;throw Error(error.message);}pending=null;dirty=false;await mountProductPriceSettings();}
 catch(e){status.textContent=(pending?'Save not confirmed. Retry. ':'')+e.message;}
 finally{busy=false;if(form.isConnected){form.querySelectorAll('input').forEach(x=>x.disabled=!!pending);save.disabled=!pending&&!dirty;save.textContent=pending?'Retry save':dirty?'Save settings':'Saved';}}
 };
}

/* Club setup does not grant access to draft team selections. */
function seCanSetup(d=ensureSelections().data){return !!(d?.admin||(d?.selection_editor??d?.selector));}
function seFixtures(){
 const s=ensureSelections();if(!seCanSetup())return;
 const fixtures=s.data.fixtures.filter(f=>f.details).slice().sort((a,b)=>a.details.days[0].date.localeCompare(b.details.days[0].date)||a.details.grade.localeCompare(b.details.grade));
 document.getElementById('seContent').innerHTML=`<section class="se-card se-drawer"><div class="se-top"><h2>Fixtures</h2><button class="btn ghost" id="seImportFixtures">Import season fixtures</button><button class="btn ghost" id="seNewFixture">Enter fixtures manually</button></div>${fixtures.map(f=>`<div class="se-top" style="padding:12px 0;border-bottom:1px solid #e6ebf1"><div><strong>${seEsc(f.details.grade)}</strong><span class="se-role">${seEsc(f.details.opposition)} · ${f.details.days.map(d=>seDate(d.date)).join(' / ')}${f.details.cancelled?' · Cancelled':''}</span></div><button class="btn ghost" data-se-fixture-setup="${f.id}">Fixture details</button></div>`).join('')||'<p>No fixtures added yet.</p>'}</section>`;
 document.getElementById('seNewFixture').onclick=()=>seFixtureEditor();document.getElementById('seImportFixtures').onclick=()=>{if(confirmLeaveSelections())seImportFixtures();};
 document.querySelectorAll('[data-se-fixture-setup]').forEach(b=>b.onclick=()=>seFixtureEditor(fixtures.find(f=>f.id===b.dataset.seFixtureSetup)));
}
function seShowSelectorNames(form){
 const chosen=new Set(new FormData(form).getAll('users')),head=form.elements.head_selector_id.value;
 document.getElementById('seSelectorNames').textContent=ensureSelections().data.members.filter(m=>chosen.has(m.user_id)&&m.user_id!==head).map(m=>m.name).join(', ')||'None assigned';
}

/* Live sign-up/link follow-up; no messages are sent from these read operations. */
async function seFetchSignupFollowup(clubId){
 try{const {data,error}=await supabase.rpc('get_selection_signup_followup',{p_club_id:clubId});if(error)throw error;return data||{can_view:false,players:[]};}
 catch{return {can_view:false,players:[],error:true};}
}
function seNeedsAccountLink(p){const f=ensureSelections().data?.signup_followup;return !!(f?.can_view&&f.players.some(x=>x.id===p.id));}
function seSignupFlag(p){const item=ensureSelections().data?.signup_followup?.players.find(x=>x.id===p.id);return seNeedsAccountLink(p)?`<span class="se-signup-flag">${item?.status==='link'?'Check account link':'Sign-up needed'}</span>`:'';}
function seSignupFilter(){const s=ensureSelections();return s.data.signup_followup?.can_view?`<label class="se-check"><input type="checkbox" id="seSignupOnly" ${s.signupOnly?'checked':''}>Sign-up / link needed (${s.data.signup_followup.players.length})</label>`:'';}
async function seOpenSignupFollowup(){
 if(!await saveClubEditsBeforeNavigation())return;const s=ensureSelections();s.view='roster';s.rosterPanel=null;s.signupOnly=true;s.rosterGrade='';s.rosterSearch='';currentTab='teams';await renderTab();
}
function seInboxFollowup(f){
 if(f?.error)return '<p class="messages-status">Player follow-up could not load. <button class="btn ghost" id="retrySignupFollowup">Retry</button></p>';
 if(!f?.can_view||!f.players.length)return '';
 return `<div class="message-row se-inbox-followup"><div><strong>Players to follow up</strong><small>${f.players.length} player${f.players.length===1?'':'s'} · sign-up / link needed</small></div><button class="btn ghost" id="viewSignupFollowup">View players</button></div>`;
}

