function seRosterGradeKey(grade){return String(grade||'').trim().toLowerCase();}
function seRosterFilters(){
 const s=ensureSelections(),seen=new Set(),options=[['','All grades'],['none','No usual grade']];
 for(const c of seGradeChoices()){const key=seRosterGradeKey(c.grade);if(!key||seen.has(key))continue;seen.add(key);options.push(['grade:'+key,c.grade]);}
 if(!options.some(([key])=>key===s.rosterGrade))s.rosterGrade='';
 return `${seRosterStyles()}<div class="se-roster-filters"><label>Find player<input type="search" id="seRosterSearch" placeholder="Name or grade" value="${seEsc(s.rosterSearch||'')}"></label><label>Show players<select id="seRosterGrade">${seOpt(options,s.rosterGrade)}</select></label></div><div class="se-roster-filter-footer">${seSignupFilter()}<span class="se-roster-count" id="seRosterCount" role="status"></span></div>`;
}
function seBindRosterSearch(){
 const s=ensureSelections(),filter=()=>{
  s.rosterSearch=document.getElementById('seRosterSearch').value;s.rosterGrade=document.getElementById('seRosterGrade').value;
  const q=s.rosterSearch.trim().toLowerCase(),followup=new Set(s.data.signup_followup?.players.map(p=>p.id)||[]);let visible=0,total=0;
  document.querySelectorAll('[data-se-roster-id]').forEach(row=>{total++;const grade=row.dataset.seRosterGrade||'';row.hidden=!row.dataset.seRosterName.includes(q)||(s.rosterGrade==='none'&&grade!=='')||(s.rosterGrade.startsWith('grade:')&&grade!==s.rosterGrade.slice(6))||(s.signupOnly&&s.data.signup_followup?.can_view&&!followup.has(row.dataset.seRosterId));if(!row.hidden)visible++;});
  document.getElementById('seRosterCount').textContent=(visible===total?total:visible+' of '+total)+' player'+(total===1?'':'s');
  const empty=document.getElementById('seRosterEmpty');if(empty){empty.hidden=visible>0;empty.textContent=total?'No matching players.':s.data.roster.length?'No active players.':'No players added yet.';}
 };
 document.getElementById('seRosterSearch').oninput=filter;document.getElementById('seRosterGrade').onchange=filter;document.getElementById('seSignupOnly')?.addEventListener('change',e=>{s.signupOnly=e.target.checked;filter();});filter();
}
function seRosterSummary(p){
 const labels=[p.batting!=='unknown'?SE_BATTING.find(([key])=>key===p.batting)?.[1]:'',p.bowling==='pace'?'Quick':p.bowling==='spin'?spinLabel(p):'',['pace','spin'].includes(p.bowling)&&p.bowling_load==='part_time'?'Part time':'',p.keeper?'WK':'',p.fielding&&p.fielding!=='unknown'?'Fielding: '+fieldingLabel(p):''].filter(Boolean);
 return labels.join(' · ')||(p.bowling==='none'?'Does not bowl':'Roles not set');
}
function seRosterGradeEditor(p){
 const grades=seGradeChoices().map(c=>c.grade);if(p.grade&&!grades.includes(p.grade))grades.push(p.grade);
 return `<label><span class="se-roster-control-label">Usual grade</span><select name="grade" aria-label="Usual grade for ${seEsc(p.name)}">${seOpt([['','No usual grade'],...grades.map(grade=>['grade:'+grade,grade])],p.grade?'grade:'+p.grade:'')}</select></label>`;
}
function seRosterRow(p){
 const open=ensureSelections().rosterOpen===p.id,id=seEsc(p.id);
 return `<div class="se-roster-row${open?' is-open':''}" data-se-roster-id="${id}" data-se-roster-name="${seEsc((p.name+' '+p.grade).toLowerCase())}" data-se-roster-grade="${seEsc(seRosterGradeKey(p.grade))}"><div class="se-roster-person"><strong>${seEsc(p.name)}${p.active?'':' · inactive'}${memberPhoneStatusIcon(p.user_id)}</strong><div class="se-roster-meta"><span class="se-roster-grade-label">${seEsc(p.grade||'No usual grade')}</span>${seSignupFlag(p)}</div><span class="se-roster-summary">${seEsc(seRosterSummary(p))}</span><button class="se-roster-expand" type="button" data-se-expand-player="${id}" aria-expanded="${open}" aria-controls="seRosterFields-${id}" aria-label="${open?'Close':'Edit'} roles for ${seEsc(p.name)}">${open?'Close':'Edit'} <span aria-hidden="true">⌄</span></button></div><div class="se-roster-controls" id="seRosterFields-${id}">${seRosterGradeEditor(p)}${[['batting','Batting role',SE_BATTING],['bowling','Bowling role',SE_BOWLING],['bowling_load','Bowling workload',SE_LOAD],['fielding','Fielding',SE_FIELDING]].map(([key,label,options])=>`<div class="se-roster-role"><label><span class="se-roster-control-label">${label}</span><select name="${key}" aria-label="${label} for ${seEsc(p.name)}">${seOpt(options,p[key]||'unknown')}</select></label>${key==='bowling'?`<label class="se-spin-style-field" data-spin-style-field ${p.bowling==='spin'?'':'hidden'}><span>Spin type</span><select name="spin_style" aria-label="Spin type for ${seEsc(p.name)}">${seOpt(SPIN_STYLES,p.spin_style||'unknown')}</select></label>`:''}</div>`).join('')}<label class="se-check"><input name="keeper" type="checkbox" aria-label="Wicketkeeper: ${seEsc(p.name)}" ${p.keeper?'checked':''}><span class="se-roster-control-label">WK</span></label></div><div class="se-roster-actions"><button class="btn ghost" type="button" data-se-edit-player="${id}">${!p.user_id||seNeedsAccountLink(p)?'Link':'Details'}</button><button class="btn ghost" type="button" data-se-player-calendar="${id}">Calendar</button></div></div>`;
}
function seRosterEdits(){
 const s=ensureSelections();return [...document.querySelectorAll('#seRosterForm [data-se-roster-id]')].map(row=>{const p=s.data.roster.find(p=>p.id===row.dataset.seRosterId);return {...p,grade:row.querySelector('[name=grade]').value.slice(6),batting:row.querySelector('[name=batting]').value,bowling:row.querySelector('[name=bowling]').value,spin_style:row.querySelector('[name=bowling]').value==='spin'?row.querySelector('[name=spin_style]').value:'unknown',bowling_load:row.querySelector('[name=bowling_load]').value,keeper:row.querySelector('[name=keeper]').checked,fielding:row.querySelector('[name=fielding]').value};}).filter(p=>{const old=s.data.roster.find(x=>x.id===p.id);return ['grade','batting','bowling','spin_style','bowling_load','keeper','fielding'].some(key=>(['fielding','spin_style'].includes(key)?(old[key]||'unknown'):old[key])!==p[key]);});
}
function seRosterSaveState(){
 const s=ensureSelections(),button=document.getElementById('seSaveRosterRoles');if(!button)return;
 const dirty=seRosterEdits().length>0;s.formDirty=dirty;if(dirty)s.rosterSaved=false;
 button.disabled=!!(s.busy||s.pending||!dirty);button.textContent=s.rosterSaved&&!dirty&&!s.pending?'Saved':'Save changes';
}
function seRoster(){
 const s=ensureSelections();if(!seCanSetup())return seReadonlyPlayingList();
 if(s.rosterPanel==='inactive')return seInactivePlayers();const players=s.data.roster.filter(p=>p.active);
 document.getElementById('seContent').innerHTML=`<div class="se-toolbar"><button class="btn" id="seImportRoster">Import registration CSV</button><button class="btn ghost" id="seAddPlayer">Add player</button><button class="btn ghost" id="seRosterTemplate">Download CSV template</button><button class="se-inactive-link" id="seFindInactive" type="button">Inactive players</button></div>${seInviteButton()}${s.data.signup_followup?.error?'<p class="se-muted">Player follow-up could not load. Use Refresh to check.</p>':''}<form id="seRosterForm" class="se-card" style="margin-top:12px">${seRosterFilters()}<div class="se-roster-head" aria-hidden="true"><span>Player</span><div class="se-roster-controls"><span>Usual grade</span><span>Batting role</span><span>Bowling role</span><span>Workload</span><span>Fielding</span><span>WK</span></div><span></span></div><div id="seRosterRows">${players.map(seRosterRow).join('')}</div><p class="se-roster-empty" id="seRosterEmpty" hidden></p>${players.length?'<div class="se-roster-save"><button type="submit" class="btn" id="seSaveRosterRoles">Save changes</button></div>':''}</form>`;
 document.getElementById('seFindInactive').onclick=()=>{if(!confirmLeaveSelections())return;s.rosterPanel='inactive';s.inactiveSearch='';s.rosterOpen=null;seInactivePlayers();};
 seBindInvites();seBindRosterSearch();document.getElementById('seImportRoster').onclick=()=>{if(confirmLeaveSelections())seImport();};document.getElementById('seAddPlayer').onclick=()=>{if(confirmLeaveSelections())sePlayerEditor();};document.getElementById('seRosterTemplate').onclick=event=>{seDownload('Playing-list-template.csv','Registration ID,Player name,Usual grade,Player email\r\n','text/csv');event.currentTarget.textContent='Download started';};
 document.querySelectorAll('[data-se-expand-player]').forEach(button=>button.onclick=()=>{s.rosterOpen=s.rosterOpen===button.dataset.seExpandPlayer?null:button.dataset.seExpandPlayer;document.querySelectorAll('#seRosterForm [data-se-roster-id]').forEach(row=>{const open=row.dataset.seRosterId===s.rosterOpen,toggle=row.querySelector('[data-se-expand-player]'),p=s.data.roster.find(p=>p.id===row.dataset.seRosterId);row.classList.toggle('is-open',open);toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',(open?'Close':'Edit')+' roles for '+p.name);toggle.innerHTML=(open?'Close':'Edit')+' <span aria-hidden="true">⌄</span>';});});
 document.querySelectorAll('[data-se-edit-player]').forEach(button=>button.onclick=()=>{if(confirmLeaveSelections()){const p=s.data.roster.find(p=>p.id===button.dataset.seEditPlayer);sePlayerEditor(p);if(!p.user_id||seNeedsAccountLink(p))document.getElementById('seAccountLink').open=true;}});document.querySelectorAll('[data-se-player-calendar]').forEach(button=>button.onclick=()=>{if(confirmLeaveSelections()){s.view='availability';drawSelections();seAvailability(button.dataset.sePlayerCalendar);}});
 const form=document.getElementById('seRosterForm');form.addEventListener('change',event=>{const row=event.target.closest('[data-se-roster-id]');if(!row)return;const p={...s.data.roster.find(p=>p.id===row.dataset.seRosterId),grade:row.querySelector('[name=grade]').value.slice(6),batting:row.querySelector('[name=batting]').value,bowling:row.querySelector('[name=bowling]').value,spin_style:row.querySelector('[name=bowling]').value==='spin'?row.querySelector('[name=spin_style]').value:'unknown',bowling_load:row.querySelector('[name=bowling_load]').value,keeper:row.querySelector('[name=keeper]').checked,fielding:row.querySelector('[name=fielding]').value};row.querySelector('[data-spin-style-field]').hidden=p.bowling!=='spin';row.querySelector('.se-roster-summary').textContent=seRosterSummary(p);row.querySelector('.se-roster-grade-label').textContent=p.grade||'No usual grade';seRosterSaveState();});
 form.onsubmit=async event=>{event.preventDefault();const rows=seRosterEdits();if(!rows.length||s.pending||s.busy)return;const ok=await seMutate('save_roster',{revision:s.data.roster_revision,rows});if(ok&&s===selectionState){s.rosterSaved=true;if(s.view==='roster')seRosterSaveState();}};seRosterSaveState();void mountMemberPhoneStatuses(document.getElementById('seContent'));
}
function seInactivePlayers(){
 const s=ensureSelections();if(!seCanSetup())return seReadonlyPlayingList();
 const players=s.data.roster.filter(p=>!p.active).sort((a,b)=>a.name.localeCompare(b.name));
 document.getElementById('seContent').innerHTML=seRosterStyles()+`<section class="se-card se-drawer"><div class="se-top"><h2>Inactive players</h2><button class="btn ghost" id="seInactiveBack" type="button">Playing list</button></div><label>Find player<input type="search" id="seInactiveSearch" placeholder="Name or grade" value="${seEsc(s.inactiveSearch||'')}"></label><div id="seInactiveRows">${players.map(p=>`<button type="button" class="se-inactive-person" data-se-inactive-player="${seEsc(p.id)}" data-se-inactive-name="${seEsc((p.name+' '+p.grade).toLowerCase())}" aria-label="Edit ${seEsc(p.name)}"><span><strong>${seEsc(p.name)}</strong>${p.grade?`<small>${seEsc(p.grade)}</small>`:''}</span><span aria-hidden="true">›</span></button>`).join('')}</div><p class="se-roster-empty" id="seInactiveEmpty" hidden></p></section>`;
 document.getElementById('seInactiveBack').onclick=()=>{s.rosterPanel=null;seRoster();};
 document.querySelectorAll('[data-se-inactive-player]').forEach(b=>b.onclick=()=>{const p=s.data.roster.find(p=>p.id===b.dataset.seInactivePlayer);if(p&&!p.active)sePlayerEditor(p);});
 const filter=()=>{s.inactiveSearch=document.getElementById('seInactiveSearch').value;const q=s.inactiveSearch.trim().toLowerCase();let visible=0;document.querySelectorAll('[data-se-inactive-player]').forEach(b=>{b.hidden=!b.dataset.seInactiveName.includes(q);if(!b.hidden)visible++;});const empty=document.getElementById('seInactiveEmpty');empty.hidden=visible>0;empty.textContent=players.length?'No matching inactive players.':'No inactive players.';};
 document.getElementById('seInactiveSearch').oninput=filter;filter();
}
function seReadonlyPlayingList(){
 const s=ensureSelections();if(!s.data.signup_followup?.can_view)return;
 document.getElementById('seContent').innerHTML=`${seInviteButton()}<section class="se-card se-drawer se-roster-readonly">${seRosterFilters()}${s.data.roster.filter(p=>p.active).map(p=>`<div class="se-unselected-row" data-se-roster-id="${seEsc(p.id)}" data-se-roster-name="${seEsc((p.name+' '+p.grade).toLowerCase())}" data-se-roster-grade="${seEsc(seRosterGradeKey(p.grade))}"><strong>${seEsc(p.name)}</strong>${seSignupFlag(p)}<span class="se-role">${seEsc(p.grade||'No usual grade')}</span></div>`).join('')}<p class="se-roster-empty" id="seRosterEmpty" hidden></p></section>`;seBindRosterSearch();seBindInvites();
}

function seBindPlayerNameCheck(form,player){
 const key=value=>String(value||'').trim().toLowerCase().replace(/\s+/g,' '),host=form.querySelector('#seNameMatch'),save=form.querySelector('[type=submit]'),field=form.elements.name;
 const check=()=>{
  const s=ensureSelections(),name=key(field.value),changed=!player.id||name!==key(player.name),match=changed&&name&&s.data.roster.find(p=>p.id!==player.id&&key(p.name)===name);
  host.hidden=!match;host.innerHTML='';field.setCustomValidity(match?'This name already has a playing-list entry. Open the existing player or use a different name.':'');field.setAttribute('aria-invalid',match?'true':'false');
  if(match){
   const editing=player.id?'You are editing '+player.name+'. ':'';
   host.innerHTML=`<strong>Cannot save: ${seEsc(match.name)} already exists.</strong><p>${seEsc(editing)}${match.active?'There is already an active player with this name.':'There is already an inactive entry with this name.'} Open that entry, or use a different name here.</p><button type="button" class="se-match-link" data-se-open-existing>Open existing ${seEsc(match.name)}</button>`;
   host.querySelector('[data-se-open-existing]').onclick=()=>{if(!confirmLeaveSelections())return;const current=ensureSelections(),existing=current.data.roster.find(p=>p.id===match.id);if(!existing){seNotice('The playing list changed. Refresh and try again.');return;}current.rosterPanel=existing.active?null:'inactive';current.rosterOpen=existing.id;sePlayerEditor(existing);};
  }
  save.disabled=!!(match||s.busy||s.pending);save.textContent=match?'Name already exists':s.busy?'Saving…':player.id&&!player.active&&form.elements.active.checked?'Reactivate player':'Save player';return !match;
 };
 field.setAttribute('aria-describedby','seNameMatch');field.addEventListener('input',check);form.elements.active.addEventListener('change',check);check();return check;
}

/* Club setup date action and the available, unselected list. */
function seAvailabilityDateLabel(date){return /^\d{4}-\d{2}-\d{2}$/.test(date||'')?date.split('-').reverse().join('/'):'';}
function seAvailabilitySetupDate(s){
 const saved=s.data.availability_dates||[],chosen=s.bulkAvailabilityDate||s.date;
 return saved.some(x=>x.date===chosen)?chosen:saved.slice().sort((a,b)=>(b.updated_at||'').localeCompare(a.updated_at||''))[0]?.date||chosen||seClubDate(new Date(),s.data);
}
function seAvailabilitySavedNotice(s,date){
 const saved=(s.data.availability_dates||[]).find(x=>x.date===date);if(!saved)return '';
 const players=s.data.roster.filter(p=>p.active),available=players.filter(p=>(p.availability?.available_dates||[]).includes(date)).length,unavailable=players.filter(p=>(p.availability?.unavailable_dates||[]).includes(date)).length,unknown=players.length-available-unavailable;
 const stamp=new Intl.DateTimeFormat('en-AU',{timeZone:s.data.access.timezone||'Australia/Sydney',day:'2-digit',month:'2-digit',year:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date(saved.updated_at||saved.bulk_saved_at));
 return `<div class="se-availability-saved" role="status"><p><strong>Availability set for ${seAvailabilityDateLabel(date)}</strong><br>${available} available · ${unavailable} unavailable${unknown?' · '+unknown+' not yet set':''}</p><p class="se-muted">Last saved ${seEsc(stamp)}.</p></div>`;
}
function seAvailabilityDateSetup(){
 const s=ensureSelections(),d=s.data;if(!seCanSetup(d))return;
 const players=d.roster.filter(p=>p.active).sort((a,b)=>a.name.localeCompare(b.name));let date=s.bulkAvailabilityDate||s.date||seAvailabilitySetupDate(s),savedExceptions=new Set(),beforeReset=[];
 document.getElementById('seContent').innerHTML=`<form id="seAvailabilityDateForm" class="se-card se-drawer"><h2>Set availability for a date</h2><label>Date<input id="seBulkDate" type="date" required value="${date}"></label><div id="seBulkSaved"></div><p class="se-form-note">All active players will be available except those ticked below. Saved unavailability is kept.</p><label>Find player<input id="seBulkSearch" type="search" placeholder="Name"></label><div class="se-bulk-players">${players.map(p=>`<label class="se-check" data-se-bulk-name="${seEsc(p.name.toLowerCase())}"><input type="checkbox" name="unavailable" value="${p.id}">${seEsc(p.name)}</label>`).join('')}</div><label class="se-check"><input id="seResetUnavailable" type="checkbox">Clear saved unavailability for this date</label><p id="seResetUnavailableNote" class="se-form-note" hidden>Saved choices will be cleared when you save. Tick anyone who should still be unavailable.</p><div class="se-actions se-editor-actions"><button class="btn" id="seSaveDate" type="submit">Save availability</button><button class="btn ghost" type="button" id="seDateCancel">Back</button></div></form>`;
 const form=document.getElementById('seAvailabilityDateForm'),input=document.getElementById('seBulkDate'),reset=document.getElementById('seResetUnavailable'),save=document.getElementById('seSaveDate'),boxes=[...form.querySelectorAll('[name="unavailable"]')],selected=()=>boxes.filter(b=>b.checked).map(b=>b.value);
 const changed=()=>{const checked=selected(),saved=(d.availability_dates||[]).some(x=>x.date===date),unset=players.some(p=>!(p.availability?.available_dates||[]).includes(date)&&!(p.availability?.unavailable_dates||[]).includes(date));s.formDirty=reset.checked||checked.length!==savedExceptions.size||checked.some(id=>!savedExceptions.has(id));save.disabled=!players.length||!date||saved&&!unset&&!s.formDirty;save.textContent=save.disabled&&saved&&!s.formDirty?'Saved':'Save availability';};
 const loadDate=()=>{s.bulkAvailabilityDate=date;savedExceptions=new Set(players.filter(p=>(p.availability?.unavailable_dates||[]).includes(date)).map(p=>p.id));boxes.forEach(b=>b.checked=savedExceptions.has(b.value));reset.checked=false;beforeReset=[];document.getElementById('seResetUnavailableNote').hidden=true;document.getElementById('seBulkSaved').innerHTML=seAvailabilitySavedNotice(s,date);changed();};
 form.oninput=e=>{if(e.target.name==='unavailable')changed();};
 reset.onchange=()=>{if(reset.checked){beforeReset=selected();boxes.forEach(b=>b.checked=false);}else boxes.forEach(b=>b.checked=beforeReset.includes(b.value));document.getElementById('seResetUnavailableNote').hidden=!reset.checked;changed();};
 input.onchange=()=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(input.value)||!confirmLeaveSelections()){input.value=date;return;}date=input.value;loadDate();};
 document.getElementById('seBulkSearch').oninput=e=>{const q=e.target.value.toLowerCase().trim();form.querySelectorAll('[data-se-bulk-name]').forEach(row=>row.hidden=!row.dataset.seBulkName.includes(q));};
 document.getElementById('seDateCancel').onclick=()=>{if(confirmLeaveSelections())drawSelections();};
 form.onsubmit=async e=>{e.preventDefault();if(save.disabled||input.value!==date||!date)return;const unavailable=selected();
  if(await seMutate('availability_batch',{date,make_all_available:true,reset_unavailable:reset.checked,roster_revision:d.roster_revision,revisions:Object.fromEntries(players.map(p=>[p.id,p.availability?.revision||0])),unavailable_ids:unavailable,available_ids:[...savedExceptions].filter(id=>!unavailable.includes(id))}))seNotice('Availability saved for '+seAvailabilityDateLabel(date)+'.',{quiet:true});
 };loadDate();
}
function seAvailableUnselected(){queueMicrotask(()=>{recordSelectionNavigation();bindSelectionBackButtons();});
 const s=ensureSelections();if(!s.data.selector)return;s.boardPanel='unselected';const today=new Date().toLocaleDateString('en-CA',{timeZone:s.data.access.timezone}),date=s.unselectedDate||s.date||today,players=seUnselectedAvailable(s.data.roster,s.data.fixtures,date);s.unselectedDate=date;
 document.getElementById('seContent').innerHTML=`<section class="se-card se-drawer"><div class="se-top"><h2>Available, not selected</h2><button class="btn ghost" id="seUnselectedBack">Selection board</button></div><label>Date<input type="date" id="seUnselectedDate" value="${date}"></label><p class="se-muted">${players.length} player${players.length===1?'':'s'} · current drafts, all grades</p>${players.map(p=>`<div class="se-unselected-row"><strong>${seEsc(p.name)}</strong><span class="se-role">${seEsc([p.grade,seRole(p)].filter(Boolean).join(' · '))}</span></div>`).join('')||'<p>No available players are unselected on this date.</p>'}</section>`;
 document.getElementById('seUnselectedBack').onclick=()=>{s.boardPanel=null;seBoard();};document.getElementById('seUnselectedDate').onchange=e=>{if(e.target.value){s.unselectedDate=e.target.value;seAvailableUnselected();}else e.target.value=date;};
}

/* Match appointments are roster identities, independent of batting accounts. */
function seMatchGroup(f,data){
 const d=f.details,groups=data.groups||[],link=(data.group_links||[]).find(l=>l.grade===d.grade&&l.competition===(d.competition||''));
 return groups.find(g=>g.id===d.grade_group_id)||groups.find(g=>g.id===link?.group_id)||groups.find(g=>g.name.toLowerCase()===d.grade.toLowerCase());
}
function seMatchRoles(f,data){
 const group=seMatchGroup(f,data),out={};
 f.details.days.forEach((day,i)=>{
  const key='d'+(i+1),ps=f.slots.map(s=>data.roster.find(p=>p.id===s[key]&&p.active)).filter(Boolean),old=f.details.match_roles?.[key]||{},role={};
  for(const kind of ['captain','keeper']){
   let manual=old[kind+'_manual']===true&&ps.some(p=>p.id===old[kind+'_id']);
   const choices=kind==='keeper'?ps.filter(p=>p.keeper):ps.filter(p=>(group?.captain_roster_ids||[]).includes(p.id)||(p.user_id&&(group?.captain_user_ids||[]).includes(p.user_id)));
   if(kind==='captain'&&choices.length===1)manual=false;
   role[kind+'_id']=manual?old[kind+'_id']:choices.length===1?choices[0].id:null;role[kind+'_manual']=manual;
  }
  out[key]=role;
 });return out;
}
function sePrepareMatch(f,data=ensureSelections().data){const copy=structuredClone(f);copy.details.match_roles=seMatchRoles(copy,data);copy.details.captain_id=null;return copy;}
function seMatchRoleIssues(f,roles){
 if(f.details.cancelled)return [];
 return f.details.days.flatMap((_,i)=>['captain','keeper'].filter(k=>!roles['d'+(i+1)]?.[k+'_id']).map(k=>k==='keeper'?{level:'warning',code:'missing_keeper',text:`Day ${i+1}: Wicketkeeper not named`}:{level:'error',text:`Day ${i+1}: choose a captain`}));
}
function seGloves(){return '<span class="se-keeper" role="img" aria-label="Wicketkeeper" title="Wicketkeeper"><svg viewBox="0 0 26 24" aria-hidden="true" focusable="false" fill="#e8eef7" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"><g transform="translate(0 3) scale(.63)"><path d="M7 22v-4l-4-6a1.4 1.4 0 0 1 2.2-1.7L7 13V5a1.3 1.3 0 0 1 2.6 0v5V3.5a1.3 1.3 0 0 1 2.6 0V10V4.5a1.3 1.3 0 0 1 2.6 0V10V7a1.3 1.3 0 0 1 2.6 0v6c0 2.7-1.4 4-1.4 5v4Z"/><path d="M7 18h9"/></g><g transform="translate(26 3) scale(-.63 .63)"><path d="M7 22v-4l-4-6a1.4 1.4 0 0 1 2.2-1.7L7 13V5a1.3 1.3 0 0 1 2.6 0v5V3.5a1.3 1.3 0 0 1 2.6 0V10V4.5a1.3 1.3 0 0 1 2.6 0V10V7a1.3 1.3 0 0 1 2.6 0v6c0 2.7-1.4 4-1.4 5v4Z"/><path d="M7 18h9"/></g></svg></span>';}
function seRoleMarks(id,role={},text=false){return (id&&role.captain_id===id?' (c)':'')+(id&&role.keeper_id===id?text?' (wk)':' '+seGloves():'');}
function seSnapshotName(snap,id,day,text=false){const name=snap.players.find(p=>p.id===id)?.name||'Vacant';return (text?name:seEsc(name))+seRoleMarks(id,snap.details.match_roles?.['d'+(day+1)],text);}
function seSnapshotSplit(snap,slot){return snap.details.days.length>1&&(slot.d1!==slot.d2||seRoleMarks(slot.d1,snap.details.match_roles?.d1,true)!==seRoleMarks(slot.d2,snap.details.match_roles?.d2,true));}
/* Selection follow-up: private shared conversation markers. */
function seStatsAllowed(d=ensureSelections().data){return !!(d&&(d.admin||seBoardAccess(d)));}
function seToggleStats(){seNotice('Analysis is paused while selections are being restored.');}
function seMountStats(){const s=ensureSelections();s.statsOpen=false;}
function seOpenStatsPlayer(panel,id){
 const s=ensureSelections(),p=s.data.roster.find(p=>p.id===id);
 if(!p?.active||!seCanSetup(s.data)||s.busy||s.pending||!confirmLeaveSelections())return;
 recordSelectionNavigation();
 Object.assign(s,{view:'roster',statsOpen:false,boardPanel:null,rosterPanel:null,navigationDrawer:null,restoreDrawer:null,active:null,formDirty:false,notice:'',followupOpen:false,boardChatOpen:null,boardCommentOpen:null,teamChange:null,availabilityReturn:null,availabilityPlayerId:null,rosterOpen:id,rosterSearch:p.name,rosterGrade:'',signupOnly:false});
 drawSelections();
 const row=[...document.querySelectorAll('[data-se-roster-id]')].find(row=>row.dataset.seRosterId===id);
 if(row){row.tabIndex=-1;row.focus({preventScroll:true});row.scrollIntoView({block:'center',behavior:'smooth'});}
}
function seMountSelectionEvidence(){
 const s=ensureSelections(),host=document.getElementById('seContent');
 if(!host||currentTab!=='teams'||s.view!=='board'||s.boardPanel||!seBoardAccess(s.data)){selectionEvidence.pause();return;}
 const today=seClubDate(),referenceTeams=seSelectionFixtures().map(f=>({...f.details,id:f.id,slots:f.slots,published:f.published,historyConfirmed:!!f.scorecard_sync?.match_id&&!f.scorecard_sync.pending?.length,returningEligible:f.details.days[0]?.date>=today&&!seFixtureLocked(f)}));
 selectionEvidence.mount(host,{scope:s.key,viewKey:JSON.stringify([s.selectionGroup,s.date]),clubId:club.id,formButton:document.getElementById('seFormIndicators'),returningButton:document.getElementById('seCompareReturning'),canCalculate:()=>s===selectionState&&!s.busy&&!s.pending&&!s.ordering,roster:s.data.roster,referenceTeams,teams:referenceTeams.filter(f=>f.days[0]?.date===s.date),season:s.data.returning_context?.season,today,returningEntries:seReturningEntries(),returningEligible:(team,person,day)=>!seUsed(person,team.days[day],s.data.fixtures,{},team)});
}
function seReturningEntries(){
 const s=ensureSelections(),data=s.data,meta=data?.returning_context;
 if(!meta?.season?.start||!meta.season.end||!seBoardAccess(data)||s.boardPanel)return [];
 const today=seClubDate();
 // The authoritative context changes after a save or an explicit refresh.
 // Picker/search/board redraws reuse the same availability reminders.
 if(s.returningCache?.data!==data||s.returningCache.today!==today)s.returningCache={data,today,views:new Map()};
 const fixtures=seSelectionFixtures(),key=JSON.stringify([s.selectionGroup,s.date]);
 if(s.returningCache.views.has(key))return s.returningCache.views.get(key);
 const references=fixtures.map(f=>({...f.details,id:f.id,slots:f.slots,published:f.published,historyConfirmed:!!f.scorecard_sync?.match_id&&!f.scorecard_sync.pending?.length,returningEligible:f.details.days[0]?.date>=today&&!seFixtureLocked(f)}));
 const entries=returningPlayers({teams:references.filter(f=>f.days[0]?.date===s.date),references,roster:data.roster,season:meta.season,today,noPlay:meta.no_play||[],compare:false,eligible:(team,person,day)=>!seUsed(person,team.days[day],data.fixtures,{},team)});
 s.returningCache.views.set(key,entries);return entries;
}
function seMountReturningPlayers(){
 const s=ensureSelections(),host=document.getElementById('seContent');
 if(!host||currentTab!=='teams'||s.view!=='board'||s.boardPanel||!seBoardAccess(s.data))return;
 const entries=seReturningEntries();
 for(const card of host.querySelectorAll('[data-se-team]')){
  const rows=entries.filter(entry=>entry.team.id===card.dataset.seTeam);
  card.querySelector('[data-se-returning]')?.remove();if(!rows.length)continue;
  const control=card.ownerDocument.createElement('section');control.dataset.seReturning='';control.className='se-available-again';control.setAttribute('aria-label','Available again for '+rows[0].team.grade);
  control.innerHTML='<span class="se-available-heading">Available again</span>'+rows.map(entry=>`<details data-se-return-key="${seEsc(entry.key)}"><summary title="${seEsc(entry.person.name+': available again')}" aria-label="${seEsc(entry.person.name+': available again. Expand availability details')}"><span aria-hidden="true">↩</span><strong>${seEsc(entry.person.name)}</strong></summary><p data-return-facts>Available again after ${entry.missed.length} ${entry.missed.length===1?'game':'games'} unavailable. Last selected ${seEsc(seDate(entry.previous.days[0].date))} at No. ${entry.position}.${entry.team.days.length>1?' Available: '+entry.availableDays.map(day=>'Day '+(day+1)).join(' / ')+'.':''}</p><div data-return-analysis></div></details>`).join('');
  const anchor=card.querySelector(':scope > .se-actions')||card.querySelector('[data-se-order-list]')||card.querySelector(':scope > ol');if(anchor)anchor.after(control);else card.append(control);
 }
}
function seBoardAccess(d=ensureSelections().data){return d?.can_view_board===true||d?.selector===true||d?.captain===true;}
function seFollowupRows(date=ensureSelections().date,data=ensureSelections().data){return (data.conversations||[]).filter(m=>m.kind==='lower_grade'&&!m.spoken_at&&m.availability!=='unavailable'&&(date===null||m.date===date));}
function seFollowupPanel(){
 const s=ensureSelections(),rows=seFollowupRows();if(seBoardAccess(s.data)||!rows.length)return '';
 const needs=rows.filter(m=>!m.spoken_at).length;
 return `<section class="se-card se-followup" id="seFollowup"><h2>Dropped a grade</h2><p class="se-muted">${needs?needs+' to check':'Up to date'}</p>${rows.map(m=>`<article class="se-conversation-row ${m.spoken_at?'se-spoken':'se-dropped'}"><strong>${seEsc(m.name)}</strong><span class="se-role">${seEsc(m.previous_grade)} → ${seEsc(m.grade)} · ${seEsc(m.competition)}</span>${seConversationControl(m)}</article>`).join('')}</section>`;
}
function seMovementBadge(m){return seConversationControl(m);}
function seBoardMatchConversation(f){return f.published&&f.can_chat?`<details class="se-board-comments se-board-chat" data-se-board-chat="${seEsc(f.id)}" ${ensureSelections().boardChatOpen===f.id?'open':''}><summary class="btn" aria-expanded="${ensureSelections().boardChatOpen===f.id}">${ensureSelections().boardChatOpen===f.id?'Hide conversation':'Match conversation'}${seMatchConversationClosed(f)?' · closed':''}</summary><div data-se-board-chat-body></div></details>`:'';}
function seBindBoardChats(){
 const s=ensureSelections();document.querySelectorAll('[data-se-board-chat]').forEach(details=>{
  details.ontoggle=()=>{if(!details.isConnected||currentTab!=='teams'||ensureSelections()!==s)return;const f=s.data.fixtures.find(f=>f.id===details.dataset.seBoardChat),button=details.querySelector('summary');button.textContent=(details.open?'Hide conversation':'Match conversation')+(seMatchConversationClosed(f,s.data)?' · closed':'');button.setAttribute('aria-expanded',String(details.open));if(details.open){s.boardChatOpen=details.dataset.seBoardChat;void seLoadBoardChat(details);}else if(s.boardChatOpen===details.dataset.seBoardChat)s.boardChatOpen=null;recordSelectionNavigation();};
  if(details.open)void seLoadBoardChat(details);
 });
}
async function seLoadBoardChat(details){
 const s=ensureSelections(),id=details.dataset.seBoardChat,host=details.querySelector('[data-se-board-chat-body]'),f=s.data.fixtures.find(x=>x.id===id);
 if(!host||host.dataset.loading||host.dataset.loaded||!f?.published||!f.can_chat)return;
 const here=()=>s===selectionState&&currentTab==='teams'&&s.view==='board'&&host.isConnected;
 host.dataset.loading='true';host.innerHTML='<p role="status">Loading conversation…</p>';
 try{
  const posts=await seRPC('posts',{id});if(!here())return;
  const closed=seMatchConversationClosed(f,s.data)||f.can_post_match===false,draft=s.boardChatDrafts?.[id]||'',lastDate=sePublishedDates(f).at(-1);
  host.innerHTML=`<p class="se-muted" data-se-board-chat-status role="status">${closed?'Conversation closed. Previous messages are read-only.':'Visible to selected players, captains and match staff.'+(lastDate?' Closes after '+seDate(lastDate)+'.':'')}</p><div class="se-board-chat-posts">${posts.map(p=>`<article class="se-post"><strong>${seEsc(p.author_name)}</strong><small> · ${seEsc(new Date(p.created_at).toLocaleString('en-AU'))}</small><p>${seEsc(p.body)}</p></article>`).join('')||'<p class="se-muted">No messages yet.</p>'}</div>${closed?`<button class="btn ghost" type="button" data-se-board-chat-refresh>Refresh conversation</button>`:`<form data-se-board-chat-form data-fixture-id="${seEsc(id)}"><label>Message<textarea name="body" required maxlength="1500" rows="2">${seEsc(draft)}</textarea></label><div class="se-actions"><button class="btn" type="submit">Send to match group</button><button class="btn ghost" type="button" data-se-board-chat-refresh>Refresh conversation</button></div></form>`}`;
  host.dataset.loaded='true';if(s.pending||s.busy)host.querySelectorAll('button,textarea').forEach(el=>el.disabled=true);
  const form=host.querySelector('form');if(form){
   form.oninput=()=>{(s.boardChatDrafts??={})[id]=form.elements.body.value;s.formDirty=[...Object.values(s.boardCommentDrafts||{}),...Object.values(s.boardChatDrafts)].some(x=>x.trim());};
   form.onsubmit=async e=>{e.preventDefault();if(s.busy||s.pending||!here())return;if(seMatchConversationClosed(f,s.data)){seUpdateConversationState();return;}const body=form.elements.body.value.trim();if(!body)return;
    (s.boardChatDrafts??={})[id]=body;s.boardChatOpen=id;
    const button=form.querySelector('[type=submit]');button.disabled=true;button.textContent='Sending…';
    const saved=await seMutate('post',{id,body});
    if(saved&&s===selectionState&&currentTab==='teams'&&s.view==='board'){
     if(s.boardChatDrafts[id]?.trim()===body)delete s.boardChatDrafts[id];s.formDirty=[...Object.values(s.boardCommentDrafts||{}),...Object.values(s.boardChatDrafts)].some(x=>x.trim());
     const active=document.querySelector(`[data-se-board-chat="${id}"]`);if(active){active.querySelector('[data-se-board-chat-body]').dataset.loaded='';await seLoadBoardChat(active);}
    }else if(here()){button.disabled=!!s.pending||s.busy||seMatchConversationClosed(f,s.data);button.textContent='Send to match group';}
   };
  }
  host.querySelector('[data-se-board-chat-refresh]').onclick=e=>seReadButton(e.currentTarget,'Refreshing…',async()=>{if(!here())return;delete host.dataset.loaded;await seLoadBoardChat(details);});
 }catch(error){if(here()){host.innerHTML=`<p role="alert">${seEsc(error.message)}</p><button class="btn ghost" type="button">Retry conversation</button>`;host.querySelector('button').onclick=()=>seLoadBoardChat(details);}}
 finally{delete host.dataset.loading;}
}
function seBoardComments(f){return f.can_comment?`<details class="se-board-comments" data-se-comments="${seEsc(f.id)}" ${ensureSelections().boardCommentOpen===f.id?'open':''}><summary>Selection comments · private${f.comment_count?' ('+Number(f.comment_count)+')':''}</summary><div data-se-comments-body="${seEsc(f.id)}"></div></details>`:'';}
function seBindBoardComments(){
 const s=ensureSelections();document.querySelectorAll('[data-se-comments]').forEach(details=>{
  details.ontoggle=()=>{if(!details.isConnected||currentTab!=='teams'||ensureSelections()!==s)return;if(details.open){s.boardCommentOpen=details.dataset.seComments;void seLoadBoardComments(details);}else if(s.boardCommentOpen===details.dataset.seComments)s.boardCommentOpen=null;recordSelectionNavigation();};
  if(details.open)void seLoadBoardComments(details);
 });
 document.getElementById('seFollowup')?.addEventListener('toggle',e=>{if(!e.target.isConnected||currentTab!=='teams'||ensureSelections()!==s)return;s.followupOpen=e.target.open;recordSelectionNavigation();});
}
async function seLoadBoardComments(details){
 const s=ensureSelections(),id=details.dataset.seComments,host=details.querySelector('[data-se-comments-body]'),f=s.data.fixtures.find(x=>x.id===id);
 if(!host||host.dataset.loading||host.dataset.loaded||!f?.can_comment)return;
 const here=()=>s===selectionState&&currentTab==='teams'&&s.view==='board'&&host.isConnected;
 host.dataset.loading='true';host.innerHTML='<p role="status">Loading comments…</p>';
 try{
  const posts=await seRPC('review_posts',{id});if(!here())return;
  const draft=s.boardCommentDrafts?.[id]||'';
  host.innerHTML=`<p class="se-muted">Private to this team’s captains and selectors.</p>${posts.map(p=>`<article class="se-post"><strong>${seEsc(p.author_name)}</strong><small> · ${seEsc(new Date(p.created_at).toLocaleString('en-AU'))}${p.review_revision!==f.revision?' · earlier team version':''}</small><p>${seEsc(p.body)}</p></article>`).join('')||'<p class="se-muted">No comments yet.</p>'}<form data-se-comment-form><label>Comment<textarea name="body" required maxlength="1500" rows="2">${seEsc(draft)}</textarea></label><div class="se-actions"><button class="btn" type="submit">Add comment</button><button class="btn ghost" type="button" data-se-comments-refresh>Refresh comments</button></div><p role="status" data-se-comment-status></p></form>`;
  host.dataset.loaded='true';const form=host.querySelector('form');if(f.can_post_comment===false){form.querySelector('label').hidden=true;form.querySelector('[type=submit]').hidden=true;}if(s.pending||s.busy||f.can_post_comment===false)form.querySelectorAll('button,textarea').forEach(el=>el.disabled=true);
  form.oninput=()=>{(s.boardCommentDrafts??={})[id]=form.elements.body.value;s.formDirty=[...Object.values(s.boardCommentDrafts),...Object.values(s.boardChatDrafts||{})].some(x=>x.trim());};
  form.onsubmit=async e=>{e.preventDefault();if(s.busy||s.pending||f.can_post_comment===false)return;const body=form.elements.body.value.trim();if(!body)return;
   (s.boardCommentDrafts??={})[id]=body;s.boardCommentOpen=id;
   const button=form.querySelector('[type=submit]');button.disabled=true;button.textContent='Saving…';
   const saved=await seMutate('review_post',{id,body,review_revision:f.revision});
   if(saved){delete s.boardCommentDrafts[id];s.formDirty=[...Object.values(s.boardCommentDrafts),...Object.values(s.boardChatDrafts||{})].some(x=>x.trim());const active=document.querySelector(`[data-se-comments="${id}"]`);if(active){const current=active.querySelector('[data-se-comments-body]');current.dataset.loaded='';await seLoadBoardComments(active);}}
   else if(here()){button.disabled=false;button.textContent='Add comment';}
  };
  host.querySelector('[data-se-comments-refresh]').onclick=async e=>{if(!confirmLeaveSelections())return;s.boardCommentOpen=id;await seReadButton(e.currentTarget,'Refreshing…',async()=>{await seReload();if(here())seBoard();});};
 }catch(error){if(here()){host.innerHTML=`<p role="alert">${seEsc(error.message)}</p><button class="btn ghost" type="button">Retry comments</button>`;host.querySelector('button').onclick=()=>seLoadBoardComments(details);}}
 finally{delete host.dataset.loading;}
}
function seCaptainAvailability(){const d=ensureSelections().data;return seIsCaptain(d)&&!seCanSetup(d)&&d.roster.some(p=>p.active&&p.user_id===session?.user?.id)?'<button class="btn ghost" id="seMyAvailability">My availability</button>':'';}
function seFixtureDetailsAction(f,published=false){return `<button type="button" class="btn se-fixture-details" ${published?'data-se-result-fixture':'data-se-edit'}="${seEsc(f.id)}"><span>Fixture details <span>&amp; results</span></span><span aria-hidden="true">→</span></button>`;}
function seBoardPublishedTeam(f){
 if(!f.published||!seDraftChanged(f))return '';const snap=f.published,d=snap.details;
 return `<details class="se-board-comments"><summary>Published team</summary><p>v ${seEsc(d.opposition)} · ${d.days.map(day=>seDate(day.date)+(day.start?' · '+seEsc(day.start):'')).join(' / ')}${d.ground?' · '+seEsc(d.ground):''}</p><ol>${snap.slots.map(slot=>`<li>${seSnapshotName(snap,slot.d1,0)}${seSnapshotSplit(snap,slot)?` <span class="se-date-tag">Day 1</span><br>${seSnapshotName(snap,slot.d2,1)} <span class="se-date-tag">Day 2</span>`:''}</li>`).join('')}</ol></details>`;
}
function seReadOnlyTeamCard(f){
 const d=f.details,roles={d1:d.match_roles?.d1||{},d2:d.match_roles?.d2||{}},state=d.cancelled?'Cancelled':f.published?(seDraftChanged(f)?'Draft changes · not published':'Published'):'Draft · not published';
 return `<section class="se-card se-readonly-sheet" data-team-state="${d.cancelled?'cancelled':f.published?(seDraftChanged(f)?'changed':'published'):'draft'}" data-se-team="${seEsc(f.id)}"><div class="se-team-head se-team-compact-head se-team-fixture-head"><div class="se-team-title"><h2>${seEsc(d.grade)}</h2><small class="se-team-state">${state}</small></div>${seFixtureDetailsAction(f)}<p>v ${seEsc(d.opposition)} · ${d.days.map(day=>seDate(day.date)).join(' / ')}</p></div>${seScorecardNote(f)}<p class="se-muted">${seEsc(seTeamNumbers(f))}</p><ol>${f.slots.map(slot=>{const split=d.days.length>1&&slot.d1!==slot.d2;return `<li class="se-published-name">${(split?[0,1]:[0]).map(day=>{const id=slot['d'+(day+1)],movement=seMovement(f,id);return `<div class="se-player-cell ${movement?(movement.spoken_at?'se-spoken':'se-dropped'):''}"><span>${seEsc(id?seName(id):'Vacant')}${seBoardRoleMarks(id,roles,split?[day]:d.days.length>1?[0,1]:[0])}${split?` <span class="se-date-tag">Day ${day+1}</span>`:''}${id?seBoardAvailability(f,id,split?[day]:d.days.map((_,i)=>i)):''}</span>${id?`<span class="se-evidence" data-se-evidence data-evidence-fixture="${seEsc(f.id)}" data-evidence-player="${seEsc(id)}"></span>`:''}${seMovementBadge(movement)}</div>`;}).join('')}</li>`;}).join('')}</ol>${seBoardPublishedTeam(f)}${seBoardComments(f)}${seBoardMatchConversation(f)}</section>`;
}
async function seShowDropped(){
 const s=ensureSelections();if(!s.data?.selector||s.view!=='board'||s.boardPanel||s.busy||s.pending)return;
 const ids=seBoardFixtures().map(f=>f.id);if(!ids.length){seNotice('Choose teams to check for dropped players.');return;}
 await seMutate('show_dropped',{ids});
}
function seMovement(f,id){return seFollowupRows(null).find(x=>x.fixture_id===f.id&&x.roster_id===id);}
function seConversationControl(m){
 if(!m||m.spoken_at)return '';
 return `<div class="se-conversation-status"><small>Dropped from ${seEsc(m.previous_grade)}${m.previous_date?` · ${seEsc(seDate(m.previous_date))}`:''}</small><button type="button" class="se-conversation-toggle" data-se-conversation="${seEsc(m.fixture_id)}" data-se-conversation-player="${seEsc(m.roster_id)}" aria-label="${seEsc(m.name)}: mark as spoken to" ${m.can_update===false?'disabled title="A selector or authorised captain/coach can mark this conversation"':''}>Mark as spoken to</button></div>`;
}
function seBindConversations(){
 document.querySelectorAll('[data-se-conversation]').forEach(button=>button.onclick=async()=>{
  const s=ensureSelections(),m=seFollowupRows(null,s.data).find(x=>x.fixture_id===button.dataset.seConversation&&x.roster_id===button.dataset.seConversationPlayer);
  if(!m||m.can_update===false||s.busy||s.pending)return;
  await seMutate('conversation',{fixture_id:m.fixture_id,roster_id:m.roster_id,movement_key:m.movement_key,revision:m.revision,spoken:!m.spoken_at});
 });
}
function seConversations(){const s=ensureSelections();s.view='board';s.followupOpen=true;if(s.conversationDate){s.date=s.conversationDate;s.boardDateChosen=true;}drawSelections();}
function seShortTeams(fixtures){return fixtures.filter(f=>!f.details.cancelled).map(f=>({fixture:f,days:f.details.days.map((_,i)=>({day:i+1,count:f.slots.filter(s=>s['d'+(i+1)]).length})).filter(d=>d.count<11)})).filter(x=>x.days.length);}
function seTeamNumbers(f){return f.details.days.map((_,i)=>`${f.details.days.length>1?'Day '+(i+1)+': ':''}${f.slots.filter(s=>s['d'+(i+1)]).length}/11`).join(' · ');}
function seGradeLevel(competition,grade,data=ensureSelections().data){
 const key=s=>String(s||'').trim().toLowerCase(),saved=data.access.grade_levels?.find(x=>key(x.competition)===key(competition)&&key(x.grade)===key(grade));
 if(saved)return Number(saved.level);
 const match=String(grade||'').trim().match(/^(?:([1-9][0-9]?)(?:st|nd|rd|th)?\s+grade|grade\s+([1-9][0-9]?))$/i);return match?Number(match[1]||match[2]):null;
}
function seGradeLevels(){
 const s=ensureSelections(),host=document.getElementById('seGradeLevels'),rows=[...(s.data.access.grade_levels||[])];
 for(const f of s.data.fixtures){const d=f.details;if(d&&!rows.some(x=>x.competition===d.competition&&x.grade===d.grade))rows.push({competition:d.competition,grade:d.grade,level:seGradeLevel(d.competition,d.grade)});}
 host.innerHTML=`<summary>Grade levels for player moves</summary><p class="se-muted">1 is highest. Use the same level for equal teams. Leave unranked teams blank.</p><form id="seGradeLevelsForm">${rows.map((r,i)=>`<label>${r.competition?seEsc(r.competition)+' · ':''}${seEsc(r.grade)}<input data-se-level="${i}" type="number" min="1" max="99" step="1" value="${r.level??''}" placeholder="Unranked"></label>`).join('')||'<p>Add fixtures to set grade levels.</p>'}<button type="submit" class="btn se-editor-actions">Save grade levels</button></form>`;
 const form=document.getElementById('seGradeLevelsForm');seSettingsSaveState(form,'Save grade levels','grade_levels');
 form.onsubmit=async e=>{e.preventDefault();const values=[...form.querySelectorAll('[data-se-level]')].filter(el=>el.value!=='').map(el=>({...rows[Number(el.dataset.seLevel)],level:Number(el.value)}));if(await seMutate('grade_levels',{rows:values,revision:s.data.access.revision}))document.getElementById('seGradeLevels').open=true;};
}
/* End selection follow-up. */

/* Completed fixtures: club-local final day, with a short explicit correction window. */
function seFixtureCompleted(f,now=new Date(),timezone=ensureSelections().data?.access?.timezone||'Australia/Sydney'){
 const dates=(f?.details||f?.published?.details)?.days?.map(d=>d.date).filter(d=>/^\d{4}-\d{2}-\d{2}$/.test(d||'')).sort()||[];
 return !!dates.length&&dates.at(-1)<now.toLocaleDateString('en-CA',{timeZone:timezone});
}
function seFixtureLocked(f,now=new Date()){
 return !!(f?.published||seFixtureCompleted(f,now))&&!(Date.parse(f.selection_unlocked_until||'')>now.getTime());
}
function seFixtureLockControls(f,location='board'){
 if(!f.published&&!seFixtureCompleted(f))return '';
 const s=ensureSelections(),locked=seFixtureLocked(f),allowed=s.data.group_permissions_enabled?f.can_edit===true&&(!f.published||f.can_unlock===true):!f.published||s.data.head_selector||s.data.access.head_selector_id===session?.user?.id;
 if(f.result_complete===true&&locked)return allowed&&location==='details'?`<details class="se-emergency-correction"><summary>Emergency correction</summary><button type="button" class="btn ghost" data-se-fixture-lock="${seEsc(f.id)}">Unlock for changes</button></details>`:'';
 return `<div class="se-fixture-lock"><p>${locked?(f.published?'Published · locked':'Completed · locked'):'Open for changes · republish to notify players'}</p>${allowed?`<button type="button" class="btn ghost" data-se-fixture-lock="${seEsc(f.id)}">${locked?'Unlock for changes':'Lock again'}</button>`:'<small>Head of Selections can unlock</small>'}</div>`;
}
function seRenderFixtureLockControls(f){
 const primary=document.getElementById('seFixturePrimaryLock'),emergency=document.getElementById('seFixtureEmergencyLock');if(!primary||!emergency)return;
 const s=ensureSelections(),quiet=f.result_complete===true&&seFixtureLocked(f),controls=seCanSetup()&&!f.result_only?seFixtureLockControls(f,'details'):'';
 primary.innerHTML=quiet?'':controls;emergency.innerHTML=quiet?controls:'';
 (quiet?emergency:primary).querySelector('[data-se-fixture-lock]')?.addEventListener('click',async()=>{if(!confirmLeaveSelections())return;await seToggleFixtureLock(f.id);const current=s.data.fixtures.find(x=>x.id===f.id);if(current)seFixtureEditor(current);});
}
function seFixtureResultLoaded(drawer,card){
 const s=ensureSelections();if(s.key!==drawer.scope||s.navigationDrawer!==drawer.drawer)return;
 const f=s.data.fixtures.find(x=>x.id===drawer.fixtureId);if(!f)return;
 const linked=card?.fixture_id===f.id||drawer.context?.fixtures?.some(x=>x.id===f.id&&x.match_id&&x.match_id===card?.scorecard?.match_id);
 f.result_complete=!!linked&&!!card?.snapshot_id&&card.scorecard?.status==='completed';seRenderFixtureLockControls(f);
}
async function seToggleFixtureLock(id){
 const s=ensureSelections(),f=s.data.fixtures.find(x=>x.id===id);if(!f||s.busy||s.pending||!seCanSetup())return;
 sePickerSaved();await seMutate('fixture_lock',{id,revision:f.revision,unlock:seFixtureLocked(f)});
}
function seGuardFixtureEdit(action,data){
 if(!['save_board','save_fixture','publish','send_review'].includes(action))return true;
 const state=ensureSelections();
 const ids=action==='save_board'?(data.fixtures||[]).map(f=>f.id):action==='save_fixture'?[data.id]:data.ids||[];
 if(state.data.group_permissions_enabled&&state.data.fixtures.some(f=>ids.includes(f.id)&&(f.can_edit!==true||action==='publish'&&f.can_publish!==true))){seNotice('Your permissions do not allow this change in that Selection Group.');return false;}
 if(state.data.fixtures.some(f=>ids.includes(f.id)&&seFixtureLocked(f))){seNotice('Team is locked. Use Unlock for changes before editing.');return false;}
 return true;
}
/* END COMPLETED FIXTURE HELPERS */

function seMatchRoleFields(f,roles,separateKind=''){
 const data=ensureSelections().data;if(f.details.cancelled)return '';
 const days=f.details.days.map((_,i)=>i),group=seMatchGroup(f,data),players=days.map(i=>f.slots.map(slot=>data.roster.find(p=>p.id===slot['d'+(i+1)]&&p.active)).filter(Boolean));
 return `<div class="se-match-roles">${['captain','keeper'].map(kind=>{
  const same=days.length===2&&roles.d1[kind+'_id']===roles.d2[kind+'_id'],editing=same&&separateKind===kind,shared=same&&!editing,shown=shared?[0]:days;
  return `<div data-se-role-group="${kind}">${shown.map(i=>{
   const key='d'+(i+1),ps=shared?players[0].filter(p=>players[1].some(other=>other.id===p.id)):players[i],value=roles[key][kind+'_id']||'',when=shown.length>1?' · Day '+(i+1):'',label=kind==='captain'?((group?.captain_roster_ids?.length||group?.captain_user_ids?.length)?'Stand-in captain':'Captain'):'Keeper';
   const captain=kind==='captain'&&ps.find(p=>p.id===value&&((group?.captain_roster_ids||[]).includes(p.id)||(p.user_id&&(group?.captain_user_ids||[]).includes(p.user_id))));
   if(captain)return `<div><small>Captain${when}</small><p><strong>${seEsc(captain.name)}</strong> · season captain</p></div>`;
   const options=[['',kind==='captain'?'Choose captain':'Who is keeping?'],...ps.map(p=>[p.id,p.name]),...(shared?[['__se_separate_days__','Choose separately by day…']]:[])];
   return `<label>${label}${when}<select data-se-match-role="${kind}" data-se-role-fixture="${seEsc(f.id)}" data-se-role-day="${key}" data-se-role-all="${shared?'1':'0'}" aria-label="${seEsc(f.details.grade)} ${label}${shared?' both days':when}" class="${value?'':'se-role-needed'}" ${ps.length||shared&&players.some(list=>list.length)?'':'disabled'}>${seOpt(options,value)}</select></label>`;
  }).join('')}${editing?`<button type="button" class="se-role-cancel" data-se-role-collapse="${seEsc(f.id)}" data-se-role-kind="${kind}" aria-label="Cancel separate ${kind} choices">Cancel</button>`:''}</div>`;
 }).join('')}</div>`;
}
function seBindMatchRoles(){
 const redraw=(el,f,kind='')=>{const host=el.closest('.se-match-roles');host.outerHTML=seMatchRoleFields(f,seMatchRoles(f,ensureSelections().data),kind);seBindMatchRoles();document.querySelector(`[data-se-role-fixture="${CSS.escape(f.id)}"][data-se-match-role="${kind||el.dataset.seRoleKind}"]`)?.focus({preventScroll:true});};
 document.querySelectorAll('[data-se-role-collapse]').forEach(el=>el.onclick=()=>{const s=ensureSelections(),f=s.data.fixtures.find(f=>f.id===el.dataset.seRoleCollapse);if(!s.busy&&!s.pending&&f)redraw(el,f);});
 document.querySelectorAll('[data-se-match-role]').forEach(el=>el.onchange=async()=>{
  const s=ensureSelections();if(s.busy||s.pending)return;
  const f=s.data.fixtures.find(f=>f.id===el.dataset.seRoleFixture),kind=el.dataset.seMatchRole,day=el.dataset.seRoleDay;if(!f)return;
  if(el.value==='__se_separate_days__'){redraw(el,f,kind);return;}
  const copy=sePrepareMatch(f),days=el.dataset.seRoleAll==='1'?Object.keys(copy.details.match_roles):[day];
  // Shared choices require a player selected on both days; day controls change only that day.
  if(el.value&&days.some(key=>!copy.slots.some(slot=>slot[key]===el.value))){seNotice('Choose a player selected on each applicable day.');return;}
  for(const key of days){copy.details.match_roles[key][kind+'_id']=el.value||null;copy.details.match_roles[key][kind+'_manual']=!!el.value;}
  await seMutate('save_board',{fixtures:[copy]},{undo:[structuredClone(f)]});
 });
}
async function seWithSavedRoles(fs,next){
 const s=ensureSelections();if(s.busy||s.pending)return;
 try{const changed=fs.filter(f=>f.can_edit!==false&&!seFixtureLocked(f)&&!f.details.cancelled).map(f=>sePrepareMatch(f)).filter(f=>JSON.stringify(f.details)!==JSON.stringify(s.data.fixtures.find(x=>x.id===f.id).details));
  if(changed.length&&!await seMutate('save_board',{fixtures:changed})){seRevealPublication('seNotice');return;}
  if(s!==selectionState||currentTab!=='teams')return;
  let current=fs.map(f=>s.data.fixtures.find(x=>x.id===f.id)).filter(f=>f&&!seFixtureLocked(f));
  if(next===sePublishReview&&current.some(seDraftChanged)){
   const scope=JSON.stringify([s.view,s.date,s.selectionGroup,s.loadSequence]),sequence=(s.publicationCheckSequence||0)+1;s.publicationCheckSequence=sequence;
   seNotice('Checking teams for publication…');
   const checked=await seRPC('publication_check',{ids:current.filter(seDraftChanged).map(f=>f.id)});
   if(s!==selectionState||currentTab!=='teams'||s.publicationCheckSequence!==sequence||scope!==JSON.stringify([s.view,s.date,s.selectionGroup,s.loadSequence]))return;
   const byId=new Map((checked?.fixtures||[]).map(f=>[f.id,f]));
   current=current.map(f=>{if(!seDraftChanged(f))return f;const check=byId.get(f.id);if(!check||check.revision!==f.revision||!Array.isArray(check.issues))throw Error('A team changed while checking publication. Refresh and review again.');return {...f,issues:check.issues};});
  }
  next(current);
 }catch(error){seNotice(error.message||'The review could not open. Refresh and try again.');seRevealPublication('seNotice');}
}
function seReviewCaptains(f,data=ensureSelections().data){
 const roles=f.details.match_roles,group=seMatchGroup(f,data),people=roles?[...new Set(Object.values(roles).map(r=>r.captain_id).filter(Boolean))].map(id=>data.roster.find(p=>p.id===id)).filter(Boolean):data.members.filter(m=>m.user_id===f.details.captain_id);
 for(const uid of group?.captain_user_ids||[])if(!people.some(p=>p.user_id===uid)){const m=data.members.find(m=>m.user_id===uid);if(m)people.push({name:m.name,user_id:uid});}
 for(const id of group?.captain_roster_ids||[])if(!people.some(p=>p.id===id)){const p=data.roster.find(p=>p.id===id);if(p)people.push(p);}
 return people;
}

/* Fixture defaults and captain input. Final publication belongs to the Head of Selections. */
function seGradeChoices(extra=[]){
 const d=ensureSelections().data,groups=d.groups||[],choices=groups.map(g=>({value:'group:'+g.id,grade:g.name,grade_group_id:g.id}));
 for(const r of [...(d.access.fixture_defaults?.rows||[]),...d.fixtures.map(f=>f.details).filter(Boolean),...d.roster,...extra]){
  const grade=r.grade?.trim();if(!grade||choices.some(c=>c.grade.toLowerCase()===grade.toLowerCase()))continue;
  choices.push({value:'grade:'+grade,grade,grade_group_id:null});
 }
 return choices;
}
function seGradeFields(key,grade='',groupId=null,options={}){
 const choices=seGradeChoices(grade?[{grade}]:[]),value=(choices.find(c=>groupId&&c.grade_group_id===groupId)||choices.find(c=>c.grade===grade))?.value||'';
 return `<label>${seEsc(options.label||'Grade')}<select name="${key}" ${options.required===false?'':'required'}>${seOpt([['',options.required===false?'No usual grade':'Choose grade'],...choices.map(c=>[c.value,c.grade]),['other','Other grade…']],value)}</select></label><label data-grade-other="${key}" hidden>Grade name<input name="${key}_other" maxlength="${options.maxlength||120}" value=""></label>`;
}
function seReadGrade(form,key){const value=form.elements[key].value;if(value==='other')return {grade:form.elements[key+'_other'].value.trim(),grade_group_id:null};return seGradeChoices().find(c=>c.value===value)||{grade:value.startsWith('grade:')?value.slice(6):'',grade_group_id:null};}
function seBindGrade(form,key,changed=()=>{}){
 const select=form.elements[key],other=form.elements[key+'_other'],label=form.querySelector(`[data-grade-other="${key}"]`);
 select.onchange=()=>{label.hidden=select.value!=='other';other.required=!label.hidden;changed();if(!label.hidden)other.focus();};other.onchange=changed;
}
/* BEGIN CONTROLLED FIXTURE CORRECTION V129 */
let fixtureCorrectionState=null;
function fixtureCorrectionIsPending(){return !!fixtureCorrectionState?.pending;}
function fixtureCorrectionConfirmLeave(){
 if(fixtureCorrectionIsPending()){alert('This correction is not yet confirmed. Retry it before leaving so the same change is confirmed once.');return false;}
 return !fixtureCorrectionState?.dirty||confirm('Leave without applying this match correction?');
}
function fixtureCorrectionReset(){fixtureCorrectionState=null;}
function fixtureCorrectionAbandon(){if(!fixtureCorrectionConfirmLeave())return false;fixtureCorrectionReset();return true;}
function fixtureCorrectionAction(fixtureId){return isAdmin()&&fixtureId?`<button type="button" class="btn ghost" data-correct-fixture="${esc(fixtureId)}">Correct match details</button>`:'';}
function wireFixtureCorrectionActions(host=document,onSaved=null){host.querySelectorAll('[data-correct-fixture]').forEach(button=>button.onclick=()=>openFixtureCorrection(button.dataset.correctFixture,{onSaved}));}
function fixtureCorrectionDecorateEditor(f){
 const form=document.getElementById('seFixtureForm');if(!f||!form||!isAdmin())return;
 const note=document.createElement('p');note.className='help';note.innerHTML='Once players have saved match records, grade, start date, format and opposition stay linked. Use the correction preview to repair an error across those records. '+fixtureCorrectionAction(f.id);
 form.querySelector('.se-editor-actions')?.before(note);wireFixtureCorrectionActions(note,async()=>{await seReload();drawSelections();});
}
async function openFixtureCorrection(fixtureId,options={}){
 if(!isAdmin()||fixtureCorrectionIsPending())return;
 if(currentTab==='teams'&&typeof confirmLeaveSelections==='function'&&!confirmLeaveSelections())return;
 if(currentTab==='team_review'&&typeof confirmLeaveTeamReview==='function'&&!confirmLeaveTeamReview())return;
 const host=options.host||document.getElementById(currentTab==='teams'?'seContent':'page');if(!host)return;
 const targetClub=club.id,s={fixtureId,clubId:targetClub,host,options,dirty:false,pending:null,preview:null,values:null};fixtureCorrectionState=s;
 const back=async()=>{if(!fixtureCorrectionConfirmLeave())return;fixtureCorrectionReset();if(options.onCancel)return options.onCancel();if(currentTab==='teams')drawSelections();else if(currentTab==='team_review')renderTeamReviewContent();};
 host.innerHTML='<section class="card"><h2>Correct match details</h2><p role="status">Loading the saved fixture…</p></section>';
 try{
  const {data,error}=await supabase.rpc('get_fixture_correction_context',{p_club_id:targetClub,p_fixture_id:fixtureId});if(error)throw error;
  if(fixtureCorrectionState!==s||club?.id!==targetClub)return;s.context=data;
  const d=data.details,groups=data.groups||[];
  host.innerHTML=`<section class="card"><h2>Correct match details</h2><p>Club Admin correction for this saved match. Preview the affected records before applying it. The same match, innings and observations stay linked together.</p><style>#fixtureCorrectionForm label{display:flex;flex-direction:column;gap:6px;font-size:14px;font-weight:600;min-width:0}#fixtureCorrectionForm .team-review-fields>label{flex:1 1 180px}#fixtureCorrectionForm input,#fixtureCorrectionForm select,#fixtureCorrectionForm textarea{box-sizing:border-box;width:100%;padding:10px;border:1px solid #b8c5d9;border-radius:8px;background:#fff;color:#172c4d;font:inherit}#fixtureCorrectionPreview table{width:100%;border-collapse:collapse;font-size:14px}#fixtureCorrectionPreview tbody th{min-width:76px;overflow-wrap:normal!important}#fixtureCorrectionPreview th,#fixtureCorrectionPreview td{text-align:left;vertical-align:top;border-bottom:1px solid #dce3ed;padding:9px 6px;overflow-wrap:anywhere}</style><form id="fixtureCorrectionForm"><div class="team-review-fields" style="display:flex;flex-wrap:wrap;gap:12px"><label>Grade<select name="group_id" required>${groups.map(g=>`<option value="${esc(g.id)}" ${g.id===d.grade_group_id?'selected':''}>${esc(g.name)}</option>`).join('')}</select></label><label>Match start date<input type="date" name="match_date" required value="${esc(d.days[0].date)}"></label>${d.days.length===2?`<label>Day 2 date<input type="date" name="second_match_date" required value="${esc(d.days[1].date)}"></label>`:''}<label>Format<select name="format_key" required>${FORMATS.map(([key,label])=>`<option value="${esc(key)}" ${key===d.format?'selected':''}>${esc(label)}</option>`).join('')}</select></label><label>Opposition<input name="opposition" maxlength="120" required value="${esc(d.opposition)}"></label></div><label style="display:block;margin-top:12px">Why is this correction needed?<textarea name="reason" required minlength="10" maxlength="800" rows="2" placeholder="For example: the original fixture was entered one day early."></textarea></label><p class="help">Published predictions, official results and confirmed scorecard imports require their own reviewed correction. This action explains any blocker before it changes anything.</p><div class="btnrow"><button type="submit" class="btn secondary" id="previewFixtureCorrection">Preview correction</button><button type="button" class="btn ghost" id="cancelFixtureCorrection">Back</button></div><p role="status" id="fixtureCorrectionStatus"></p></form><div id="fixtureCorrectionPreview"></div></section>`;
  const form=host.querySelector('#fixtureCorrectionForm'),status=host.querySelector('#fixtureCorrectionStatus'),area=host.querySelector('#fixtureCorrectionPreview');
  s.form=form;s.status=status;
  const invalidate=()=>{s.dirty=true;s.preview=null;area.innerHTML='';};form.addEventListener('input',invalidate);form.addEventListener('change',invalidate);
  host.querySelector('#cancelFixtureCorrection').onclick=back;
  const lock=busy=>{for(const el of form.elements)el.disabled=busy;};
  form.onsubmit=async e=>{
   e.preventDefault();if(s.pending||!form.reportValidity())return;const values=Object.fromEntries(new FormData(form));const reason=values.reason.trim();delete values.reason;
   s.values=values;s.reason=reason;lock(true);status.textContent='Checking this correction…';
   try{const {data:preview,error}=await supabase.rpc('preview_fixture_correction',{p_club_id:targetClub,p_fixture_id:fixtureId,p_values:values});if(error)throw error;if(fixtureCorrectionState!==s||club?.id!==targetClub)return;
    s.preview=preview;status.textContent='';const labels={grade:'Grade',match_date:'Start date',second_match_date:'Day 2',format_key:'Format',opposition:'Opposition'};
    area.innerHTML=`<h3>Review the correction</h3><div style="overflow-x:auto"><table><thead><tr><th>Detail</th><th>Saved now</th><th>After correction</th></tr></thead><tbody>${Object.entries(labels).filter(([k])=>preview.before[k]||preview.after[k]).map(([key,label])=>`<tr><th>${esc(label)}</th><td>${esc(key==='format_key'?formatLabel(preview.before[key]):preview.before[key]||'—')}</td><td>${esc(key==='format_key'?formatLabel(preview.after[key]):preview.after[key]||'—')}</td></tr>`).join('')}</tbody></table></div><p>${Number(preview.counts.innings)} innings, ${Number(preview.counts.preparations)} preparations and ${Number(preview.counts.reviews)} saved reviews will follow the corrected details, keeping their existing notes and links.</p>${preview.blockers.map(x=>`<p role="alert"><strong>${esc(x)}</strong></p>`).join('')}${preview.warnings.map(x=>`<p class="help">${esc(x)}</p>`).join('')}<p><strong>Reason:</strong> ${esc(reason)}</p>${preview.can_apply?'<button type="button" class="btn secondary" id="applyFixtureCorrection">Apply this correction</button>':''}`;
    const applyButton=area.querySelector('#applyFixtureCorrection');if(applyButton)applyButton.onclick=apply;
   }catch(err){status.textContent=err.message||'The preview could not be loaded. Try again.';}finally{if(fixtureCorrectionState===s&&!s.pending)lock(false);}
  };
  const apply=async()=>{
   if(s.busy||!s.preview)return;
   s.pending=s.pending||{p_club_id:targetClub,p_fixture_id:fixtureId,p_request_id:crypto.randomUUID(),p_expected_revision:s.preview.revision,p_preview_token:s.preview.token,p_reason:s.reason,p_values:s.values};
   s.busy=true;lock(true);const btn=area.querySelector('#applyFixtureCorrection');if(btn){btn.disabled=true;btn.textContent='Applying correction…';}status.textContent='Saving the correction and linked records together…';
   try{
    const {data:result,error}=await supabase.rpc('apply_fixture_correction',s.pending);if(error){if(error.code&&error.code!=='PGRST000'&&error.code!=='PGRST001'&&error.code!=='PGRST002')s.pending=null;throw error;}
    if(!result?.correction_id||result.fixture_id!==fixtureId)throw new Error('The correction has not been confirmed. Retry to confirm the same request.');
    s.pending=null;s.dirty=false;fixtureCorrectionReset();
    host.innerHTML=`<section class="card"><h2>Match details corrected</h2><p>The same match, player innings, observations and preparations now use the corrected details.</p>${result.requires_republish?'<p>The previously published team remains as originally shared. Ask the Head of Selections to check and republish the corrected fixture.</p>':''}<button type="button" class="btn secondary" id="fixtureCorrectionDone">Done</button></section>`;
    host.querySelector('#fixtureCorrectionDone').onclick=async()=>{if(options.onSaved)return options.onSaved(result);if(currentTab==='teams'){await seReload();drawSelections();}else if(currentTab==='team_review'){const r=ensureTeamReviewState();r.group=s.values.group_id;r.match_date=result.after.match_date;r.format_key=result.after.format_key;r.opposition=result.after.opposition;r.loaded=teamReviewIdentity(r);r.needsReload=true;await renderTeamReview();}};
   }catch(err){status.textContent=(err.message||'The save could not be confirmed.')+(s.pending?' Retry the same correction to confirm it.':' Review a fresh preview before applying again.');if(btn){btn.disabled=false;btn.textContent=s.pending?'Retry correction':'Preview again';btn.onclick=s.pending?apply:()=>{s.preview=null;area.innerHTML='';form.requestSubmit();};}if(!s.pending)lock(false);}finally{s.busy=false;}
  };
 }catch(err){if(fixtureCorrectionState!==s)return;host.innerHTML=`<section class="card"><h2>Correct match details</h2><p role="alert">${esc(err.message||'Unable to load this fixture.')}</p><button type="button" class="btn ghost" id="fixtureCorrectionBack">Back</button></section>`;host.querySelector('#fixtureCorrectionBack').onclick=back;}
}
window.addEventListener('beforeunload',event=>{if(fixtureCorrectionState?.dirty||fixtureCorrectionIsPending()){event.preventDefault();event.returnValue='';}});
