 const copy=structuredClone(f);copy.slots.splice(index,1);copy.slots=seTrimSlots(copy.slots);sePickerSaved();
 return seMutate('save_board',{fixtures:[copy]},{undo:[structuredClone(f)],order:{id,slot:Math.min(index,copy.slots.length-1),message:`${seOrderName(f,index)} cleared from ${f.details.grade} · draft saved ✓`}});
