/* BEGIN MEMBER PHONE STATUS — maintained source: tools/member_phone_status_ui.js */
let memberPhoneStatusState=null;
function memberPhoneStatusContext(){
 if(!isAdmin()||!club?.id||!session?.user?.id)return null;
 const key=`${session.user.id}:${club.id}`;
 if(memberPhoneStatusState?.key!==key)memberPhoneStatusState={key,rows:new Map(),checkedAt:0,pending:null};
 return memberPhoneStatusState;
}
function phoneStatusStyles(){
 if(document.getElementById('phoneStatusStyles'))return;
 const style=document.createElement('style');style.id='phoneStatusStyles';style.textContent=`
 .phone-status-slot{display:inline-flex;vertical-align:middle;margin-left:4px}
 button.phone-status-icon{display:inline-flex!important;align-items:center;justify-content:center;vertical-align:middle;flex:0 0 28px;width:28px;height:28px;min-height:28px!important;padding:3px!important;margin:0 0 0 4px;border:0;border-radius:5px;background:transparent;color:#64748b;cursor:pointer;box-sizing:border-box;line-height:1}
 .phone-status-slot button.phone-status-icon{margin:0}
 button.phone-status-icon[data-phone-state=on]{color:#207044}
 button.phone-status-icon:hover,button.phone-status-icon:focus-visible{background:#edf2f7;outline:2px solid currentColor;outline-offset:1px}
 .phone-status-icon svg{width:22px;height:22px;flex:none;pointer-events:none}
 #phoneStatusTooltip{position:fixed;z-index:10000;max-width:min(240px,calc(100vw - 16px));padding:8px 10px;border-radius:6px;background:#263445;color:white;font:13px/1.4 system-ui,sans-serif;box-shadow:0 3px 12px #0003;box-sizing:border-box;pointer-events:none}
 #phoneStatusTooltip[hidden]{display:none}
 .workspace-roster-person h3:has(.phone-status-slot){display:flex;align-items:center;gap:2px;flex-wrap:wrap}
 `;document.head.append(style);
 const tooltip=document.createElement('div');tooltip.id='phoneStatusTooltip';tooltip.setAttribute('role','tooltip');tooltip.hidden=true;document.body.append(tooltip);
 let active=null,position=null;
 const hide=()=>{active?.removeAttribute('aria-describedby');active=null;tooltip.hidden=true;};
 const show=button=>{
  if(!button)return;hide();active=button;tooltip.textContent=button.getAttribute('aria-label');tooltip.hidden=false;button.setAttribute('aria-describedby',tooltip.id);
  const rect=button.getBoundingClientRect(),box=tooltip.getBoundingClientRect();position={left:rect.left,top:rect.top};
  tooltip.style.left=Math.max(8,Math.min(rect.left,innerWidth-box.width-8))+'px';
  tooltip.style.top=Math.max(8,rect.bottom+6+box.height>innerHeight?rect.top-box.height-6:rect.bottom+6)+'px';
 };
 document.addEventListener('pointerover',e=>{const b=e.target.closest?.('[data-phone-status-icon]');if(b&&e.pointerType!=='touch')show(b);});
 document.addEventListener('pointerout',e=>{if(e.target.closest?.('[data-phone-status-icon]')&&!e.relatedTarget?.closest?.('[data-phone-status-icon]'))hide();});
 document.addEventListener('focusin',e=>{const b=e.target.closest?.('[data-phone-status-icon]');if(b)show(b);else hide();});
 document.addEventListener('click',e=>{const b=e.target.closest?.('[data-phone-status-icon]');if(b){e.preventDefault();e.stopPropagation();show(b);}else hide();},true);
 document.addEventListener('keydown',e=>{if(e.key==='Escape')hide();});
 document.addEventListener('scroll',()=>{if(active){const r=active.getBoundingClientRect();if(r.left!==position?.left||r.top!==position?.top)hide();}},true);window.addEventListener('resize',hide);
 new MutationObserver(()=>{if(active&&!active.isConnected)hide();}).observe(document.getElementById('page')||document.body,{childList:true,subtree:true});
}
function phoneStatusBadge(ready){
 phoneStatusStyles();
 const state=ready===true?'on':ready===false?'off':'unknown';
 const label=ready===true?'Phone alerts enabled for club messages':ready===false?'Phone alerts not enabled for club messages':'Phone notification status unavailable';
 const mark=ready===true?'<path d="m15 13 3 3 5-6"/>':ready===false?'<path d="m3 3 18 18"/>':'<path d="M15 10a2 2 0 1 1 3 1.7c-.7.4-1 1-1 1.8"/><path d="M17 17h.01"/>';
 return `<button type="button" class="phone-status-icon" data-phone-status-icon data-phone-state="${state}" aria-label="${label}"><svg viewBox="0 0 26 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="5" y="2" width="10" height="20" rx="2"/><path d="M9 5h2M10 19h.01"/>${mark}</svg></button>`;
}
function memberPhoneStatusIcon(userId){
 const state=memberPhoneStatusContext();if(!state||!userId)return '';
 return `<span class="phone-status-slot" data-member-phone="${esc(userId)}">${phoneStatusBadge(state.rows.get(userId))}</span>`;
}
async function mountMemberPhoneStatuses(host){
 const state=memberPhoneStatusContext();if(!state||!host?.querySelector('[data-member-phone]'))return;
 const clubId=club.id;
 if(!state.pending&&Date.now()-state.checkedAt>=15000){
  state.pending=(async()=>{
   try{
    const {data,error}=await supabase.rpc('get_club_member_phone_status',{p_club_id:clubId});
    if(error||!Array.isArray(data)||data.some(r=>typeof r.user_id!=='string'||typeof r.phone_ready!=='boolean'))throw error||Error('Status unavailable');
    state.rows=new Map(data.map(r=>[r.user_id,r.phone_ready]));
   }catch{state.rows=new Map();}
   finally{state.checkedAt=Date.now();state.pending=null;}
  })();
 }
 if(state.pending)await state.pending;
 if(state!==memberPhoneStatusContext()||!host.isConnected)return;
 host.querySelectorAll('[data-member-phone]').forEach(el=>{const ready=state.rows.get(el.dataset.memberPhone),value=ready===true?'on':ready===false?'off':'unknown';if(el.querySelector('[data-phone-status-icon]')?.dataset.phoneState!==value)el.innerHTML=phoneStatusBadge(ready);});
}
/* END MEMBER PHONE STATUS */


/* BEGIN TEMPORARY MATCH CAPTAIN — maintained source: tools/temporary_captain_ui.js */
let matchCaptainAccess=null,matchCaptainAccessSequence=0,matchCaptainPending=null;
function hasMatchCaptainAccess(){
 return !!(matchCaptainAccess?.key===selectionsScopeKey()&&!selectionsStandalone()&&matchCaptainAccess.batting&&(matchCaptainAccess.season_groups?.length||matchCaptainAccess.appointments?.some(d=>Date.parse(d.expires_at)>Date.now())));
}
async function loadMatchCaptainAccess(){
 const key=selectionsScopeKey(),clubId=club?.id;
 if(!key||!clubId||!session?.user?.id){matchCaptainAccess=null;return null;}
 if(matchCaptainPending?.key===key)return matchCaptainPending.promise;
 const sequence=++matchCaptainAccessSequence;
 const promise=(async()=>{
  let result;try{result=await supabase.rpc('get_my_match_captain_access',{p_club_id:clubId});}catch(error){result={error};}
  if(key!==selectionsScopeKey()||sequence!==matchCaptainAccessSequence)return null;
  matchCaptainAccess={key,timezone:result?.data?.timezone||'Australia/Sydney',batting:!result?.error&&result?.data?.batting===true,season_groups:!result?.error&&Array.isArray(result?.data?.season_groups)?result.data.season_groups:[],appointments:!result?.error&&Array.isArray(result?.data?.appointments)?result.data.appointments:[]};
  syncMatchCaptainNavigation();return matchCaptainAccess;
 })();
 matchCaptainPending={key,promise};try{return await promise;}finally{if(matchCaptainPending?.promise===promise)matchCaptainPending=null;}
}
function syncMatchCaptainNavigation(){
 const nav=document.querySelector('.shell>.nav');if(!nav||!club?.id||!session?.user?.id)return;
 for(const [tab,label] of [['players','Players'],['team_review','Match review']]){
  const permitted=!selectionsStandalone()&&(tab==='players'?canUsePlayersWorkspace():canUseTeamReview());
  let button=nav.querySelector(`[data-tab="${tab}"]`);
  if(!button&&permitted){
   button=document.createElement('button');button.dataset.tab=tab;button.dataset.navGroup='club';button.textContent=label;
   button.onclick=()=>openClubSectionHome(tab);
   nav.insertBefore(button,nav.querySelector('[data-nav-group="player"]')||nav.firstChild);
  }
  if(button)button.hidden=!permitted;
 }
}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&session?.user?.id&&club?.id&&!(currentTab==='teams'&&selectionState?.view==='board'))void loadMatchCaptainAccess();});
setInterval(()=>{if(document.visibilityState==='visible'&&session?.user?.id&&club?.id&&!(currentTab==='teams'&&selectionState?.view==='board')){syncMatchCaptainNavigation();void loadMatchCaptainAccess();}},60000);
/* END TEMPORARY MATCH CAPTAIN */


/* BEGIN PRODUCT ENQUIRIES — maintained in tools/product_enquiries_ui.js */
const PRODUCT_ENQUIRY_LABELS={batting:'Club Batting',selections:'Mirelion Select',both:'Both products'};
let productEnquiryDraft=null;
const productEnquiryChoice=value=>Object.hasOwn(PRODUCT_ENQUIRY_LABELS,value)?value:'';
async function productEnquiryRPC(action,data={}){const {data:result,error}=await supabase.rpc('club_product_enquiries',{p_action:action,p_data:data});if(error){const failure=Error(error.message);failure.code=error.code;throw failure;}return result;}
function productEnquiryStyles(){return `<style>.pe-entry{max-width:660px;margin:30px auto;padding:24px;box-sizing:border-box}.pe-entry h1{font-size:32px;margin:8px 0 14px}.pe-entry p{font-size:15px;line-height:1.55}.pe-entry input,.pe-entry select{font:inherit;font-size:16px;min-height:44px;max-width:100%;box-sizing:border-box;width:100%}.pe-entry .field{margin:16px 0}.pe-entry .btn{min-height:44px}.pe-entry .btnrow{gap:8px}.pe-account{padding:12px;background:#f3f5fb;border-radius:8px;overflow-wrap:anywhere}.pe-row{display:flex;justify-content:space-between;gap:12px;padding:14px 0;border-bottom:1px solid #e4e8ef;align-items:center}.pe-row small{display:block;color:#667085;margin-top:4px;overflow-wrap:anywhere}.pe-row>div{min-width:0}.pe-history{margin-top:18px}.pe-contact{overflow-wrap:anywhere}.pe-request-list{margin-top:18px}@media(max-width:480px){.pe-entry{margin:14px 0;padding:18px}.pe-entry h1{font-size:28px}.pe-row{align-items:flex-start}.pe-row .btn{flex-shrink:0}}</style>`;}
function rememberProductEnquiry(){
 const form=document.getElementById('productEnquiryForm');if(!form)return productEnquiryDraft;
 const previous=productEnquiryDraft;
 const next={club_name:form.elements.club_name.value.trim(),contact_name:form.elements.contact_name.value.trim(),product:form.elements.product.value};
 const same=previous&&['club_name','contact_name','product'].every(k=>previous[k]===next[k]);
 productEnquiryDraft={...next,request_id:same?previous.request_id:crypto.randomUUID()};return productEnquiryDraft;
}
async function renderProductEnquiryEntry(message=''){
 const params=new URLSearchParams(location.search),continuation=params.get('continue_enquiry')==='1',requestId=params.get('enquiry_request');
 if(session&&requestId)return renderProductEnquiryStatus(requestId==='all'?null:requestId);
 const saved=continuation&&session?(session.user.user_metadata?.product_enquiry_request||{}):(productEnquiryDraft||{});
 if(continuation&&session&&saved.request_id&&saved.club_name&&saved.contact_name&&productEnquiryChoice(saved.product)){
  app.innerHTML=productEnquiryStyles()+'<section class="card pe-entry"><h1>Recording your request…</h1></section>';
  try{await submitProductEnquiry(saved);return;}catch(error){message=error.message;}
 }
 const product=productEnquiryChoice(saved.product)||productEnquiryChoice(params.get('enquiry'));
 const signedIn=!!session,userId=session?.user?.id;let busy=false;
 app.innerHTML=productEnquiryStyles()+`<section class="card pe-entry"><div class="section-label">Mirelion</div><h1>Get started with your club.</h1><p>Choose what interests you. We’ll help arrange the right setup.</p>${signedIn?`<p class="pe-account">Signed in as <strong>${esc(session.user.email||'')}</strong><br><button class="guide-inline-link" type="button" id="peSwitchAccount">Use a different email</button></p>`:'<p>Already registered? <button class="guide-inline-link" type="button" id="peShowSignIn">Sign in</button></p>'}<form id="productEnquiryForm"><div class="field"><label for="peProduct">I’m interested in</label><select id="peProduct" name="product" required><option value="">Choose a product</option>${Object.entries(PRODUCT_ENQUIRY_LABELS).map(([key,label])=>`<option value="${key}" ${product===key?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label for="peClub">Club name</label><input id="peClub" name="club_name" autocomplete="organization" minlength="3" maxlength="160" required value="${esc(saved.club_name||'')}"></div><div class="field"><label for="peName">Your name</label><input id="peName" name="contact_name" autocomplete="name" minlength="2" maxlength="120" required value="${esc(saved.contact_name||session?.user?.user_metadata?.display_name||'')}"></div>${signedIn?'':`<div class="field"><label for="peEmail">Email</label><input id="peEmail" name="email" type="email" autocomplete="email" required></div><div class="field"><label for="pePassword">Choose a password</label><input id="pePassword" name="password" type="password" autocomplete="new-password" minlength="10" required></div><p class="help">At least 10 characters. Confirm your email to finish.</p>`}<button class="btn secondary" type="submit" id="peSubmit">Register interest</button></form><p class="help">No payment or subscription starts here.</p><p id="peStatus" role="status" aria-live="polite">${esc(message)}</p>${signedIn?'<button class="guide-inline-link" id="peMyRequests" type="button">My requests</button>':''}<p><a href="./">Mirelion home</a></p></section>`;
 const form=document.getElementById('productEnquiryForm'),status=document.getElementById('peStatus');
 const lock=value=>{busy=value;document.querySelectorAll('.pe-entry input,.pe-entry select,.pe-entry button').forEach(control=>control.disabled=value);};
 document.getElementById('peMyRequests')?.addEventListener('click',()=>renderProductEnquiryStatus());
 document.getElementById('peShowSignIn')?.addEventListener('click',()=>{rememberProductEnquiry();renderProductEnquirySignIn();});
 document.getElementById('peSwitchAccount')?.addEventListener('click',async()=>{
  if(busy||authActionInFlight)return;const draft=rememberProductEnquiry();lock(true);authActionInFlight=true;
  try{const {error}=await supabase.auth.signOut({scope:'local'});if(error)throw error;session=null;platformRole=null;platformAccessError=false;canBootstrapPlatform=false;club=null;membership=null;allMemberships=[];userProfile=null;productEnquiryDraft={...draft,request_id:crypto.randomUUID()};const target=new URL(location.href);for(const key of ['continue_enquiry','enquiry_request','signin','code'])target.searchParams.delete(key);target.hash='';history.replaceState({},'',target);renderProductEnquiryEntry();}catch(error){status.textContent=error.message;lock(false);}finally{authActionInFlight=false;}
 });
 form.onsubmit=async event=>{
  event.preventDefault();if(busy||authActionInFlight)return;const draft=rememberProductEnquiry();lock(true);authActionInFlight=true;status.textContent='Recording your request…';
  try{
   if(signedIn&&(session?.user?.id!==userId))throw Error('Your account changed. Refresh and check the email shown.');
   if(!session){
    const target=new URL('./app.html',location.href);target.searchParams.set('enquiry',draft.product);target.searchParams.set('continue_enquiry','1');
    const {data,error}=await supabase.auth.signUp({email:form.elements.email.value.trim(),password:form.elements.password.value,options:{emailRedirectTo:target.href,data:{display_name:draft.contact_name,product_enquiry_request:draft}}});
    if(error)throw error;
    form.elements.password.value='';
    if(!data.session){status.textContent='Check your email to confirm and send your request. If you already have an account, sign in above.';return;}
    session=data.session;
   }
   await submitProductEnquiry(draft);
  }catch(error){if(form.isConnected)status.textContent=error.message||'Your request was not confirmed. Please retry.';}
  finally{authActionInFlight=false;if(form.isConnected)lock(false);}
 };
}
async function submitProductEnquiry(draft){
 const requester=session?.user?.id;if(!requester)throw Error('Sign in before continuing.');
 const result=await productEnquiryRPC('submit',draft);
 if(session?.user?.id!==requester)throw Error('Your account changed. Refresh to check your requests.');
 productEnquiryDraft=null;
 const target=new URL('./app.html',location.href);target.searchParams.set('enquiry',draft.product);target.searchParams.set('enquiry_request',result.id);history.replaceState({},'',target);
 await renderProductEnquiryStatus(result.id);
}
function renderProductEnquirySignIn(message=''){
 app.innerHTML=productEnquiryStyles()+`<section class="card pe-entry"><div class="section-label">Mirelion</div><h1>Sign in to continue.</h1><form id="peSignInForm"><div class="field"><label for="peLoginEmail">Email</label><input id="peLoginEmail" type="email" name="email" autocomplete="username" required></div><div class="field"><label for="peLoginPassword">Password</label><input id="peLoginPassword" type="password" name="password" autocomplete="current-password" required></div><button class="btn secondary" id="peLoginSubmit" type="submit">Sign in</button></form><p id="peLoginStatus" role="status">${esc(message)}</p><div class="btnrow"><button class="guide-inline-link" type="button" id="peBack">Back to request</button><button class="guide-inline-link" type="button" id="peReset">Set or reset password</button></div></section>`;
 document.getElementById('peBack').onclick=()=>renderProductEnquiryEntry();document.getElementById('peReset').onclick=()=>renderPasswordReset();
 document.getElementById('peSignInForm').onsubmit=async event=>{event.preventDefault();if(authActionInFlight)return;const button=document.getElementById('peLoginSubmit'),status=document.getElementById('peLoginStatus'),form=event.currentTarget;button.disabled=true;authActionInFlight=true;status.textContent='Signing in…';try{const {data,error}=await supabase.auth.signInWithPassword({email:form.elements.email.value.trim(),password:form.elements.password.value});if(error)throw error;session=data.session;passwordFlow.finish();history.replaceState(history.state,'',cleanPasswordUrl(location.href));await renderProductEnquiryEntry();}catch(error){if(status.isConnected)status.textContent=error.message;}finally{authActionInFlight=false;if(button.isConnected)button.disabled=false;}};
}
async function renderProductEnquiryStatus(requestId=null){
 const requester=session?.user?.id;
 app.innerHTML=productEnquiryStyles()+'<section class="card pe-entry"><h1>Your requests</h1><p>Loading…</p></section>';
 try{
  const rows=await productEnquiryRPC('mine');if(session?.user?.id!==requester)return;
  const shown=requestId?rows.filter(row=>row.id===requestId):rows;
  app.innerHTML=productEnquiryStyles()+`<section class="card pe-entry"><div class="section-label">Mirelion</div><h1>${requestId&&shown.length?'Request received.':'Your requests'}</h1>${shown.length?shown.map(row=>`<article class="pe-request-list"><h2>${esc(row.club_name)}</h2><p>${esc(PRODUCT_ENQUIRY_LABELS[row.product]||'')}</p><p>${row.trial_started_at?'Your trial started automatically. Open your club to check its products and trial dates.':row.trial_scheduled_at?'Your trial is scheduled. Open Account → Products & trials to check or change its start date.':row.trial_scheduled_at?'Your trial is scheduled. Open Account → Products & trials to check or change its start date.':row.trial_scheduled_at?'Your trial is scheduled. Open Account → Products & trials to check or change its start date.':row.trial_scheduled_at?'Your trial is scheduled. Open Account → Products & trials to check or change its start date.':row.club_id?'Your club workspace is ready. Product access is arranged separately.':row.status==='closed'?'This request is closed. Choose New request if your club is interested again.':'We’ll review your request and help arrange your club’s setup.'}</p>${row.club_id?`<a class="btn secondary" href="./app.html?club=${encodeURIComponent(row.club_id)}">Open club</a>`:''}</article>`).join(''):'<p>No requests found for this account.</p>'}<div class="btnrow" style="margin-top:20px"><button class="btn ghost" id="peRefreshStatus">Refresh</button><button class="btn ghost" id="peAnotherRequest">New request</button></div><p><a href="./app.html">My account</a> · <a href="./">Mirelion home</a></p></section>`;
  document.getElementById('peRefreshStatus').onclick=()=>renderProductEnquiryStatus(requestId);
  document.getElementById('peAnotherRequest').onclick=()=>{productEnquiryDraft=null;const target=new URL('./app.html?enquiry=',location.href);history.replaceState({},'',target);renderProductEnquiryEntry();};
 }catch(error){app.innerHTML=productEnquiryStyles()+`<section class="card pe-entry"><h1>Your requests</h1><p role="status">${esc(error.message)}</p><button class="btn" id="peRetryStatus">Retry</button><p><a href="./">Mirelion home</a></p></section>`;document.getElementById('peRetryStatus').onclick=()=>renderProductEnquiryStatus(requestId);}
}
async function renderPlatformProductEnquiries(){
 const host=document.getElementById('platformProductEnquiries'),requester=session?.user?.id;if(!host)return;
 const current=()=>host.isConnected&&document.getElementById('platformProductEnquiries')===host&&session?.user?.id===requester;
 try{
  const result=await productEnquiryRPC('list');if(!current())return;
  const rows=result.rows||[],open=rows.filter(row=>row.status!=='closed'&&!(row.trial_started_at||row.trial_scheduled_at)),started=rows.filter(row=>row.trial_started_at||row.trial_scheduled_at),closed=rows.filter(row=>row.status==='closed'&&!(row.trial_started_at||row.trial_scheduled_at));
  const rowHTML=row=>`<article class="pe-row"><div><strong>${esc(row.club_name)}</strong><small>${esc(PRODUCT_ENQUIRY_LABELS[row.product])} · ${row.trial_started_at?'Trial started automatically':row.trial_scheduled_at?'Trial scheduled automatically':row.trial_scheduled_at?'Trial scheduled automatically':row.trial_scheduled_at?'Trial scheduled automatically':row.trial_scheduled_at?'Trial scheduled automatically':row.club_id?'Workspace ready':'New request'}</small><small>${esc(row.contact_name)} · ${esc(row.contact_email)}</small></div><button class="btn ghost" data-pe-review="${esc(row.id)}">${result.can_manage&&!(row.trial_started_at||row.trial_scheduled_at)?'Review':'View'}</button></article>`;
  host.innerHTML=productEnquiryStyles()+`<div class="section-label">Product sign-ups</div><h2>${open.length?`${open.length} request${open.length===1?'':'s'} to review`:'No new requests'}</h2>${open.map(rowHTML).join('')}${started.length?`<details class="pe-history"><summary>Automatic trials · ${started.length}</summary><p>No approval required.</p>${started.map(rowHTML).join('')}</details>`:''}${closed.length?`<details class="pe-history"><summary>Closed requests · ${closed.length}</summary>${closed.map(rowHTML).join('')}</details>`:''}`;
  host.querySelectorAll('[data-pe-review]').forEach(button=>button.onclick=()=>openProductEnquiryReview(rows.find(row=>row.id===button.dataset.peReview),result.can_manage));
 }catch(error){if(current()){host.innerHTML=`<h2>Product enquiries</h2><p role="status">${esc(error.message)}</p><button class="btn ghost" id="peReloadPipeline">Retry</button>`;host.querySelector('#peReloadPipeline').onclick=renderPlatformProductEnquiries;}}
}
async function openProductEnquiryReview(row,canManage){
 const dialog=document.createElement('dialog');dialog.className='cp-dialog';dialog.innerHTML=clubProductsStyles()+productEnquiryStyles()+`<div class="se-top"><h2>${esc(row.club_name)}</h2><button class="btn ghost" id="peReviewClose">Close</button></div><p><strong>${esc(PRODUCT_ENQUIRY_LABELS[row.product])}</strong></p><p class="pe-contact">${esc(row.contact_name)}<br>${esc(row.contact_email)}</p><div id="peReviewActions">Loading…</div><p id="peReviewStatus" role="status"></p>`;document.body.append(dialog);dialog.showModal();let busy=false,pending=null;const requester=session?.user?.id;
 dialog.querySelector('#peReviewClose').onclick=()=>{if(!busy)dialog.close();};dialog.addEventListener('cancel',event=>{if(busy)event.preventDefault();});dialog.addEventListener('close',()=>dialog.remove(),{once:true});
 const current=()=>dialog.isConnected&&session?.user?.id===requester;
 const actions=dialog.querySelector('#peReviewActions'),status=dialog.querySelector('#peReviewStatus');
 const run=async(action,data={})=>{
  if(busy||!canManage||!current())return;pending??={action,data:{id:row.id,revision:row.revision,...data}};busy=true;dialog.querySelectorAll('button,select').forEach(x=>x.disabled=true);status.textContent='Saving…';
  const requestedAction=pending.action;
  try{const result=await productEnquiryRPC(pending.action,pending.data);pending=null;if(!current())return;busy=false;dialog.close();await renderPlatformProductEnquiries();if(result.club_id&&requestedAction!=='close')await openClubSubscriptions(result.club_id,row.club_name);}
  catch(error){if(current()){if(error.code)pending=null;status.textContent=(pending?'Save not confirmed. ':'')+error.message;dialog.querySelectorAll('button,select').forEach(x=>x.disabled=!!pending);dialog.querySelector('#peReviewClose').disabled=false;if(pending){const retry=document.createElement('button');retry.className='btn ghost';retry.id='peRetryAction';retry.textContent='Retry save';retry.onclick=()=>{retry.remove();run(pending.action,pending.data);};status.append(document.createElement('br'),retry);}}}
  finally{busy=false;}
 };
 try{
  const clubs=row.club_id?[]:await productEnquiryRPC('clubs',{id:row.id});if(!current())return;
  actions.innerHTML=row.club_id?`<div class="btnrow"><button class="btn secondary" id="peManageProducts">${canManage?'Manage products':'View products'}</button><button class="btn ghost" id="peCopyClubLink">Copy club link</button></div>`:row.status==='closed'?'<p>This request is closed.</p>':canManage?`<p>Prepare the club with ${esc(row.contact_name)} as its non-playing Club Admin. Set product access on the next screen.</p><button class="btn secondary" id="pePrepareClub">Prepare club</button>${clubs.length?`<div class="field"><label for="peExistingClub">Or use a club they already administer</label><select id="peExistingClub"><option value="">Choose club</option>${clubs.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select></div><button class="btn ghost" id="peLinkClub">Use this club</button>`:''}`:'<p>Awaiting Platform Admin.</p>';
  if(canManage&&row.status!=='closed')actions.insertAdjacentHTML('beforeend','<p><button class="guide-inline-link" id="peCloseRequest">Close request</button></p>');
  actions.querySelector('#peManageProducts')?.addEventListener('click',()=>{dialog.close();openClubSubscriptions(row.club_id,row.club_name);});
  actions.querySelector('#peCopyClubLink')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(new URL(`./app.html?club=${encodeURIComponent(row.club_id)}`,location.href).href);status.textContent='Copied';}catch{status.textContent=new URL(`./app.html?club=${encodeURIComponent(row.club_id)}`,location.href).href;}});
  actions.querySelector('#pePrepareClub')?.addEventListener('click',()=>{if(pending||confirm(`Prepare ${row.club_name} with ${row.contact_name} (${row.contact_email}) as Club Admin? Requested: ${PRODUCT_ENQUIRY_LABELS[row.product]}. Product access starts only when you add it on the next screen.`))run('prepare',{confirmation:row.club_name});});
  actions.querySelector('#peLinkClub')?.addEventListener('click',()=>{const clubId=actions.querySelector('#peExistingClub').value;if(clubId)run('link',{club_id:clubId});else status.textContent='Choose a club.';});
  actions.querySelector('#peCloseRequest')?.addEventListener('click',()=>{if(pending||confirm('Close this request? Existing club access stays unchanged.'))run('close');});
 }catch(error){if(current()){status.textContent=error.message;actions.innerHTML='<button class="btn ghost" id="peRetryReview">Retry</button>';actions.querySelector('#peRetryReview').onclick=()=>{dialog.close();openProductEnquiryReview(row,canManage);};}}
}
/* END PRODUCT ENQUIRIES */


/* BEGIN PRODUCT TRIALS — maintained in tools/product_trials_ui.js */
let productTrialDraft=null,productTrialBusy=false;
const productTrialChoice=value=>Object.hasOwn(PRODUCT_ENQUIRY_LABELS,value)?value:'';
async function productTrialRPC(action,data={}){
 const {data:result,error}=await supabase.rpc('club_product_trials',{p_action:action,p_data:data});
 if(error){const failure=Error(error.message);failure.code=error.code;throw failure;}return result;
}
function productTrialRemember(){
 const form=document.getElementById('productTrialForm');if(!form)return productTrialDraft;
 const previous=productTrialDraft,next={club_id:form.elements.club_id?.value||'',club_name:form.elements.club_name.value.trim(),
  contact_name:form.elements.contact_name.value.trim(),product:form.elements.product.value,start_mode:form.elements.start_mode.value,starts_on:form.elements.start_mode.value==='later'?form.elements.starts_on.value:null,timezone:form.elements.timezone.value};
 const same=previous&&['club_id','club_name','contact_name','product','start_mode','starts_on','timezone'].every(k=>(previous[k]||'')===(next[k]||''));
 productTrialDraft={...next,request_id:same?previous.request_id:crypto.randomUUID()};return productTrialDraft;
}
async function productTrialStart(draft){
 const userId=session?.user?.id;if(!userId)throw Error('Sign in before continuing.');
 const result=await productTrialRPC('start',draft);
 if(session?.user?.id!==userId)throw Error('Your account changed. Sign in again to open your club.');
 productTrialDraft=null;
 const target=new URL('./app.html',location.href);target.searchParams.set('club',result.club_id);
 target.searchParams.set('tab',result.next_tab==='products'?'products':result.next_tab==='teams'?'teams':'dashboard');
 app.innerHTML=productEnquiryStyles()+`<section class="card pe-entry"><h1>Your trial is arranged.</h1><p>${esc(result.club_name)}</p><a class="btn secondary" href="${esc(target.href)}">Open your club</a></section>`;
 location.assign(target.href);
}
async function renderProductTrialEntry(message='',skipContinuation=false){
 const params=new URLSearchParams(location.search),userId=session?.user?.id;
 const continuation=!skipContinuation&&params.get('continue_trial')==='1';
 const metadata=continuation&&session?session.user.user_metadata?.product_trial_request:null;
 const saved=productTrialDraft||(metadata&&typeof metadata==='object'?metadata:{});
 if(continuation&&session&&saved.request_id&&saved.club_name&&saved.contact_name&&productTrialChoice(saved.product)){
  if(productTrialBusy)return;productTrialBusy=true;
  app.innerHTML=productEnquiryStyles()+'<section class="card pe-entry"><h1>Arranging your trial…</h1><p>Your chosen dates will be saved automatically.</p></section>';
  try{await productTrialStart(saved);return;}catch(error){message=error.message;productTrialDraft={...saved};}
  finally{productTrialBusy=false;}
 }
 let options={clubs:[],trial_days:{batting:60,selections:21}};
 if(session){
  app.innerHTML=productEnquiryStyles()+'<section class="card pe-entry"><h1>Start your free trial.</h1><p>Loading your clubs…</p></section>';
  try{options=await productTrialRPC('options');if(session?.user?.id!==userId)return;}
  catch(error){
   app.innerHTML=productEnquiryStyles()+`<section class="card pe-entry"><h1>Start your free trial.</h1><p role="status">${esc(error.message)}</p><button class="btn" id="ptRetryOptions">Retry</button><p><a href="./app.html?signin=1">Sign in</a></p></section>`;
   document.getElementById('ptRetryOptions').onclick=()=>renderProductTrialEntry('',true);return;
  }
 }
 const clubs=options.clubs||[],product=productTrialChoice(saved.product)||productTrialChoice(params.get('trial_product'));
 const requested=saved.club_id||params.get('trial_club')||'',selected=clubs.find(c=>c.id===requested);
 const signedIn=!!session;let busy=false,pending=null;
 app.innerHTML=productEnquiryStyles()+`<section class="card pe-entry"><div class="section-label">Mirelion</div><h1>Start your free trial.</h1><p>Choose either product or both, then choose when your full trial begins.</p>${signedIn?`<p class="pe-account">Signed in as <strong>${esc(session.user.email||'')}</strong><br><button class="guide-inline-link" type="button" id="ptSwitchAccount">Use a different email</button></p>`:'<p>Already registered? <button class="guide-inline-link" type="button" id="ptShowSignIn">Sign in</button></p>'}<form id="productTrialForm"><div class="field"><label for="ptProduct">Try</label><select id="ptProduct" name="product" required><option value="">Choose a product</option>${Object.entries(PRODUCT_ENQUIRY_LABELS).map(([key,label])=>`<option value="${key}" ${product===key?'selected':''}>${label}</option>`).join('')}</select></div>${clubs.length?`<div class="field"><label for="ptExistingClub">Club</label><select id="ptExistingClub" name="club_id"><option value="">Set up a new club</option>${clubs.map(c=>`<option value="${esc(c.id)}" ${selected?.id===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div>`:''}<div class="field" id="ptClubNameField" ${selected?'hidden':''}><label for="ptClub">Club name</label><input id="ptClub" name="club_name" autocomplete="organization" minlength="3" maxlength="160" ${selected?'':'required'} value="${esc(selected?.name||saved.club_name||'')}"></div><div class="field"><label for="ptName">Your name</label><input id="ptName" name="contact_name" autocomplete="name" minlength="2" maxlength="120" required value="${esc(saved.contact_name||session?.user?.user_metadata?.display_name||'')}"></div>${signedIn?'':`<div class="field"><label for="ptEmail">Email</label><input id="ptEmail" name="email" type="email" autocomplete="email" required></div><div class="field"><label for="ptPassword">Choose a password</label><input id="ptPassword" name="password" type="password" autocomplete="new-password" minlength="10" required></div><p class="help">At least 10 characters.</p>`}${trialScheduleFields(saved)}<p class="help" id="ptTrialTerms"></p><button class="btn secondary" type="submit" id="ptSubmit">Start free trial</button></form><p class="help">No card required. Nothing is automatically charged.</p><p id="ptStatus" role="status" aria-live="polite">${esc(message)}</p><p><a href="./">Mirelion home</a></p></section>`;
 const form=document.getElementById('productTrialForm'),status=document.getElementById('ptStatus');
 const lock=value=>{busy=value;app.querySelectorAll('input,select,button').forEach(control=>control.disabled=value);if(!value&&clubs.find(c=>c.id===form.elements.club_id?.value)?.timezone)form.elements.timezone.disabled=true;};
 bindTrialScheduleFields(form,clubs,options.trial_days);
 const terms=()=>{
  const value=form.elements.product.value,c=clubs.find(row=>row.id===form.elements.club_id?.value);
  if(c){form.elements.club_name.value=c.name;form.elements.club_name.required=false;document.getElementById('ptClubNameField').hidden=true;}
  else{form.elements.club_name.required=true;document.getElementById('ptClubNameField').hidden=false;}
  const chosen=value==='both'?['batting','selections']:value?[value]:[];
  document.getElementById('ptTrialTerms').textContent=chosen.map(k=>c?.products?.[k]?.active?`${PRODUCT_ENQUIRY_LABELS[k]} is already active.`:
   c?.products?.[k]?.scheduled?`${PRODUCT_ENQUIRY_LABELS[k]} is scheduled for ${niceDate(c.products[k].starts_on)}.`:
   c?.products?.[k]&&!c.products[k].trial_available?`${PRODUCT_ENQUIRY_LABELS[k]} has already been tried. Open your club to continue.`:
   `${options.trial_days?.[k]||(k==='selections'?21:60)} days to try ${PRODUCT_ENQUIRY_LABELS[k]}.`).join(' ')+(c?' Your accounts, branding and current access stay in place.':'');
 };
 form.elements.product.onchange=terms;form.elements.club_id?.addEventListener('change',()=>{if(!form.elements.club_id.value)form.elements.club_name.value='';terms();});terms();
 document.getElementById('ptShowSignIn')?.addEventListener('click',()=>{productTrialRemember();renderProductTrialSignIn();});
 document.getElementById('ptSwitchAccount')?.addEventListener('click',async()=>{
  if(busy||authActionInFlight)return;const draft=productTrialRemember();lock(true);authActionInFlight=true;
  try{const {error}=await supabase.auth.signOut({scope:'local'});if(error)throw error;
   session=null;platformRole=null;platformAccessError=false;canBootstrapPlatform=false;club=null;membership=null;allMemberships=[];userProfile=null;
   productTrialDraft={...draft,club_id:'',request_id:crypto.randomUUID()};
   const target=new URL(location.href);for(const key of ['continue_trial','trial_club','code'])target.searchParams.delete(key);target.hash='';history.replaceState({},'',target);
   await renderProductTrialEntry('',true);
  }catch(error){status.textContent=error.message;lock(false);}finally{authActionInFlight=false;}
 });
 const start=async draft=>{
  lock(true);authActionInFlight=true;status.textContent='Arranging your trial…';
  try{
   if(signedIn&&session?.user?.id!==userId)throw Object.assign(Error('Your account changed. Refresh and check the email shown.'),{code:'ACCOUNT_CHANGED'});
   if(!session){
    const target=new URL('./app.html',location.href);target.searchParams.set('trial_product',draft.product);target.searchParams.set('continue_trial','1');
    const {data,error}=await supabase.auth.signUp({email:form.elements.email.value.trim(),password:form.elements.password.value,
     options:{emailRedirectTo:target.href,data:{display_name:draft.contact_name,product_trial_request:draft}}});
    if(error)throw Object.assign(Error(error.message),{code:error.code||'AUTH_FAILED'});
    form.elements.password.value='';
    if(!data.session){status.textContent='Check your email. Confirm it to save your chosen trial dates and open your club. Already have an account? Sign in above.';return;}
    session=data.session;
   }
   pending={...draft};await productTrialStart(pending);
  }catch(error){
   if(!form.isConnected)return;
   status.textContent=error.message||'Your trial was not confirmed.';
   if(error.code)pending=null;
   if(pending){status.append(document.createTextNode(' Check again to safely finish the same signup. '));const retry=document.createElement('button');retry.id='ptRetryStart';retry.className='btn ghost';retry.type='button';retry.textContent='Check trial';retry.onclick=()=>{retry.remove();start(pending);};status.append(retry);}
  }finally{authActionInFlight=false;if(form.isConnected){lock(!!pending);const retry=document.getElementById('ptRetryStart');if(retry)retry.disabled=false;}}
 };
 form.onsubmit=event=>{event.preventDefault();if(busy||authActionInFlight)return;start(productTrialRemember());};
}
function renderProductTrialSignIn(message=''){
 app.innerHTML=productEnquiryStyles()+`<section class="card pe-entry"><h1>Sign in to start your trial.</h1><form id="ptSignInForm"><div class="field"><label for="ptLoginEmail">Email</label><input id="ptLoginEmail" name="email" type="email" autocomplete="username" required></div><div class="field"><label for="ptLoginPassword">Password</label><input id="ptLoginPassword" name="password" type="password" autocomplete="current-password" required></div><button class="btn secondary" type="submit">Sign in</button></form><p id="ptLoginStatus" role="status">${esc(message)}</p><div class="btnrow"><button class="guide-inline-link" id="ptBack" type="button">Back to trial</button><button class="guide-inline-link" id="ptReset" type="button">Set or reset password</button></div></section>`;
 document.getElementById('ptBack').onclick=()=>renderProductTrialEntry('',true);
 document.getElementById('ptReset').onclick=()=>renderPasswordReset();
 document.getElementById('ptSignInForm').onsubmit=async event=>{
  event.preventDefault();if(authActionInFlight)return;authActionInFlight=true;const form=event.currentTarget,status=document.getElementById('ptLoginStatus');
  form.querySelector('button').disabled=true;
  try{const {data,error}=await supabase.auth.signInWithPassword({email:form.elements.email.value.trim(),password:form.elements.password.value});if(error)throw error;session=data.session;passwordFlow.finish();history.replaceState(history.state,'',cleanPasswordUrl(location.href));await renderProductTrialEntry('',true);}
  catch(error){if(status.isConnected)status.textContent=error.message;}
  finally{authActionInFlight=false;if(form.isConnected)form.querySelector('button').disabled=false;}
 };
}
async function openMyClubProducts(){
 if(!canOpenClubTab('products')||!await saveClubEditsBeforeNavigation())return;
 currentTab='products';localStorage.setItem(`bdp-tab-${club.id}`,currentTab);await renderTab();
}
function bindProductTrialLinks(){
 document.querySelectorAll('[data-product-trials]').forEach(button=>button.onclick=openMyClubProducts);
}
async function renderMyClubProducts(){return renderScheduledClubProducts();}
