// The full reference stays searchable. The first useful actions reflect the
// user's role and the club's products, with specialist steps shown on demand.
function guideTutorialContext(){
 const role=typeof guideAudienceKey==='function'?guideAudienceKey():'member';
 const known=typeof selectionAccess!=='undefined'&&!!selectionAccess&&!selectionAccess.error;
 return {role,staff:['admin','head_coach','coach','captain'].includes(role),teams:typeof selectionsEnabled==='function'&&selectionsEnabled(),batting:typeof selectionsStandalone!=='function'||!selectionsStandalone(),known};
}
function guideContextAllows(item,context=guideTutorialContext()){
 if(item?.roles?.length&&!item.roles.includes(context.role))return false;
 if(item?.staff_only&&!context.staff)return false;
 if(!context.known||!item?.products?.length)return true;
 return item.products.some(product=>product==='batting'&&context.batting||product==='teams'&&context.teams||product==='batting_only'&&context.batting&&!context.teams||product==='both'&&context.batting&&context.teams);
}
function guideTopicRelevant(topic,context=guideTutorialContext()){
 const source=CLUB_BATTING_HELP?.[topic.capability_key]||null;
 return guideContextAllows(source||topic,context);
}
function guideTutorialSections(topic,context=guideTutorialContext()){
 const source=CLUB_BATTING_HELP?.[topic.capability_key]||null;
 const steps=(topic.tutorial||[]).filter(step=>guideContextAllows(step,context));
 const explicit=steps.some(step=>typeof step.quick_start==='boolean');
 const count=source?.quick_start_count??topic.quick_start_count??5;
 return explicit?{main:steps.filter(step=>step.quick_start===true),additional:steps.filter(step=>step.quick_start!==true)}:{main:steps.slice(0,count),additional:steps.slice(count)};
}
function guideTutorialSteps(topic,context){return guideTutorialSections(topic,context).main;}
function guideTutorialAdditionalSteps(topic,context){return guideTutorialSections(topic,context).additional;}
function helpVideoRelevant(video,context=guideTutorialContext()){return guideContextAllows(video,context);}
function helpVideosForContext(){
 const available=HELP_VIDEOS.filter(v=>helpVideoRelevant(v));
 if(currentTab==='guide')return guideSelectedCapabilityKey==='whole_process'?available:available.filter(v=>v.topics.includes(guideSelectedCapabilityKey));
 if(currentTab==='phone_app')return HELP_VIDEOS.filter(v=>v.id.startsWith('phone-')&&(!phoneIsIOS()&&!phoneIsAndroid()||v.id===`phone-${phoneIsIOS()?'iphone':'android'}`));
 return [];
}
function helpVideoStyles(){return `<style id="helpVideoStyles">
 .phone-video-preview{display:flex;align-items:center;gap:14px;box-sizing:border-box;width:100%;margin:8px 0 16px;padding:12px;border:1px solid #ccd5e8;border-radius:12px;background:#f5f7fc;color:#17245f;text-align:left;font:inherit;cursor:pointer}.phone-video-preview:hover{background:#eef2fb;border-color:#8598c7}.phone-video-preview:focus-visible{outline:3px solid #6679dd;outline-offset:3px}.phone-video-thumb{position:relative;display:block;flex:0 0 88px}.phone-video-thumb img{display:block;width:88px;height:156px;object-fit:cover;border-radius:7px;background:#101d3b}.phone-video-play{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);display:grid;place-items:center;width:40px;height:40px;border-radius:50%;background:#fffffff2;color:#17245f;font-size:20px;box-shadow:0 2px 8px #101d3b55}.phone-video-copy{display:flex;flex-direction:column;gap:7px;min-width:0}.phone-video-copy strong{font-size:16px}.phone-video-copy>span{font-size:14px;line-height:1.4}.phone-video-copy small{font-size:12px;color:#5e6678}
 .help-video-links{display:flex;flex-wrap:wrap;align-items:center;gap:4px 12px;margin:8px 0 14px}.help-video-links button{border:0;background:none;padding:8px 0;color:var(--navy,#202f78);font-family:inherit;font-size:13px;font-weight:600;line-height:1.4;text-align:left;min-height:40px;cursor:pointer}.help-video-links button:focus-visible{outline:3px solid #6679dd;outline-offset:3px}.help-video-links small{font-size:12px;color:#5e6678;font-weight:400}.help-video-catalogue{margin:12px 0}.help-video-catalogue>summary{min-height:44px;cursor:pointer;font-weight:700;align-content:center}.help-video-catalogue .help-video-links{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr))}
 .help-video-dialog{width:min(760px,calc(100vw - 32px));max-height:calc(100dvh - 32px);box-sizing:border-box;overflow:auto;border:1px solid #cbd2e4;border-radius:14px;padding:16px;background:white;color:#172033}.help-video-dialog::backdrop{background:#10172cd9}.help-video-dialog header{display:flex;gap:12px;align-items:center;justify-content:space-between}.help-video-dialog h2{font-size:19px;margin:0}.help-video-dialog header button{flex-shrink:0;min-width:44px;min-height:44px}.help-video-dialog video{display:block;max-width:100%;max-height:min(65dvh,640px);width:auto;height:auto;aspect-ratio:9/16;margin:12px auto;background:#17245f}.help-video-dialog p,.help-video-dialog li{font-size:14px;line-height:1.5}.help-video-dialog summary{min-height:44px;align-content:center;cursor:pointer}.help-video-dialog a{color:#202f78}.help-video-dialog [hidden]{display:none!important}
 </style>`;}
function phoneVideoPreview(v){
 const suffix=v.asset_version?'?v='+encodeURIComponent(v.asset_version):'';
 return `<button type="button" class="phone-video-preview" data-help-video="${esc(v.id)}" aria-label="Watch ${esc(v.title)}"><span class="phone-video-thumb" aria-hidden="true"><img src="videos/${esc(v.id)}.jpg${suffix}" alt="" width="88" height="156" loading="lazy"><span class="phone-video-play">▶</span></span><span class="phone-video-copy"><strong>Watch video</strong><span>${esc(v.title)}</span><small>${Math.round(v.duration)} seconds</small></span></button>`;
}
function bindContextHelpVideos(){
 const page=document.getElementById('page');if(!page)return;
 const existing=page.querySelector('#contextHelpVideos'),videos=helpVideosForContext();
 const deviceSections=currentTab==='phone_app'?[...page.querySelectorAll('[data-phone-device]')]:[];
 if(deviceSections.length){
  existing?.remove();
  if(!document.getElementById('helpVideoStyles'))document.head.insertAdjacentHTML('beforeend',helpVideoStyles());
  for(const section of deviceSections){
   const v=HELP_VIDEOS.find(v=>v.id==='phone-'+section.dataset.phoneDevice);if(!v)continue;
   let host=section.querySelector('.phone-device-video');
   if(host?.dataset.videoId===v.id)continue;
   host?.remove();host=document.createElement('div');host.className='phone-device-video';host.dataset.videoId=v.id;host.innerHTML=phoneVideoPreview(v);
   section.querySelector('summary').insertAdjacentElement('afterend',host);
   const button=host.querySelector('[data-help-video]');button.onclick=()=>openHelpVideo(v.id,button);
  }
  return;
 }
 const heading=currentTab==='guide'?(guideSelectedCapabilityKey==='whole_process'?page.querySelector('#guideProcessHeading'):page.querySelector('.guide-tutorial-card h2')):page.querySelector('h1')||page.querySelector('h2');
 if(!videos.length||!heading){existing?.remove();return;}
 const signature=currentTab+':'+(currentTab==='guide'?guideSelectedCapabilityKey:'')+':'+videos.map(v=>v.id).join(',');
 const anchor=heading.closest('.innings-title-row')||heading;
 if(existing?.dataset.signature===signature&&existing.previousElementSibling===anchor)return;
 existing?.remove();
 if(!document.getElementById('helpVideoStyles'))document.head.insertAdjacentHTML('beforeend',helpVideoStyles());
 const links=videos.map(v=>`<button type="button" data-help-video="${esc(v.id)}">▶ Watch: ${esc(v.title)} <small>· ${Math.round(v.duration)} sec</small></button>`).join('');
 const host=document.createElement('div');host.id='contextHelpVideos';host.dataset.signature=signature;
 host.innerHTML=currentTab==='phone_app'?videos.map(phoneVideoPreview).join(''):currentTab==='guide'&&guideSelectedCapabilityKey==='whole_process'?`<details class="help-video-catalogue"><summary>Short how-to videos</summary><div class="help-video-links">${links}</div></details>`:`<div class="help-video-links">${links}</div>`;
 anchor.insertAdjacentElement('afterend',host);
 host.querySelectorAll('[data-help-video]').forEach(b=>b.onclick=()=>openHelpVideo(b.dataset.helpVideo,b));
}
function openHelpVideo(id,opener){
 const v=HELP_VIDEOS.find(v=>v.id===id);if(!v)return;
 const assetSuffix=v.asset_version?'?v='+encodeURIComponent(v.asset_version):'';
 document.getElementById('helpVideoDialog')?.close();
 const dialog=document.createElement('dialog');dialog.id='helpVideoDialog';dialog.className='help-video-dialog';dialog.setAttribute('aria-labelledby','helpVideoTitle');
 dialog.innerHTML=`<header><h2 id="helpVideoTitle">${esc(v.title)}</h2><button type="button" class="btn ghost" data-video-close aria-label="Close video">✕</button></header><p>${esc(v.description||'Fictional club demonstration · captions included.')}</p><video controls playsinline preload="none" poster="videos/${esc(v.id)}.jpg${assetSuffix}" aria-label="${esc(v.title)}"><source src="videos/${esc(v.id)}.mp4${assetSuffix}" type="video/mp4"><track kind="captions" src="videos/${esc(v.id)}.vtt${assetSuffix}" srclang="en" label="English"></video><p data-video-error hidden>The video could not load. Try the download link or use the written steps below.</p><details><summary>Written steps</summary><ol>${v.captions.map(c=>`<li>${esc(c.replace(/\n/g,' '))}</li>`).join('')}</ol></details><p><a href="videos/${esc(v.id)}.mp4${assetSuffix}" download>Download video</a> <small>(${(v.bytes/1000000).toFixed(1)} MB)</small></p>`;
 document.body.append(dialog);const video=dialog.querySelector('video');
 dialog.querySelector('[data-video-close]').onclick=()=>dialog.close();
 const showError=()=>dialog.querySelector('[data-video-error]').hidden=false;
 video.addEventListener('error',showError);video.querySelector('source').addEventListener('error',showError);
 dialog.addEventListener('close',()=>{video.pause();video.removeAttribute('src');video.querySelectorAll('source,track').forEach(s=>s.removeAttribute('src'));video.load();dialog.remove();if(opener?.isConnected)opener.focus();},{once:true});
 dialog.showModal();dialog.querySelector('[data-video-close]').focus();
 // Playback follows this explicit Watch click; opening an app screen loads no media.
 void video.play().catch(()=>{});
}
// These screens also redraw themselves without a main-tab navigation.
for(const [get,set] of [[()=>renderPhoneApp,v=>renderPhoneApp=v],[()=>renderClubBattingGuide,v=>renderClubBattingGuide=v],[()=>renderSelections,v=>renderSelections=v]]){
 const original=get();set(async function(...args){const result=await original.apply(this,args);bindContextHelpVideos();return result;});
}
// Forms and Teams subviews can redraw without calling renderTab. Reuse an
// unchanged link block, so observing those redraws cannot create a render loop.
if(document.body){
 let scheduled=false;
 new MutationObserver(()=>{if(scheduled)return;scheduled=true;requestAnimationFrame(()=>{scheduled=false;bindContextHelpVideos();});}).observe(document.body,{childList:true,subtree:true});
}
