 document.getElementById('aiAllowanceRefresh').onclick=socialPlatformAI;document.getElementById('aiUsageDownload').onclick=()=>seDownload('AI-artwork-usage.json',JSON.stringify({as_at:new Date().toISOString(),...data},null,2),'application/json');
