async function loadSocialFeatures(){
 const scope=selectionsScopeKey(),request=requestedFeatureScope();
 if(!ensureSelections().data?.socials)throw Error('Socials Manager access is required.');
 const state=socialEnsure();
 if(socialEngine&&socialEngineScope===scope&&socialEngineState===state)return socialEngine;
 if(socialEngineTask?.scope===scope&&socialEngineTask.request===request&&socialEngineTask.state===state)return socialEngineTask.promise;
 const current=()=>state===socialState&&scope===selectionsScopeKey()&&request===requestedFeatureScope()&&ensureSelections().data?.socials===true;
 const task={scope,request,state};socialEngineTask=task;
 task.promise=(async()=>{
  const module=await import('./social-workspace.js?v=0.8.62.294');
  if(!current())return null;
  const engine=module.createSocialWorkspace({appNavigationBack,club,drawSelections,ensureSelections,matchReviewExtractUrl,mountScorecardTeam,normaliseHex,platformRole,recordSelectionNavigation,renderSocialPlatformSetup,restoreSocialNavigation,seDownload,seEsc,seFormatLabel,seNotice,seOpt,seReload,selectionsScopeKey,session,socialCanLeave,socialEnsure,socialHere,socialOpenFixture,socialState,supabase});
  await engine.loadSocialFeatures();if(!current())return null;
  socialEngine=engine;socialEngineScope=scope;socialEngineState=state;({socialAwardScopes,socialAwardLabels,socialResults,socialAwards,socialPlayerWeek,socialWeek,socialSandbox,socialTeamWorkflow,socialPublishing}=engine.controllers);return engine;
 })().finally(()=>{if(socialEngineTask===task)socialEngineTask=null;});
 return task.promise;
}
